def hmusic_student_parent_label(student_name, parent_name=None):
    name = str(student_name or "").strip()
    parent = str(parent_name or "").strip()
    if parent:
        return f"{name} · Parent: {parent}"
    return f"{name} · Parent: No parent"


def hmusic_clean_student_picker_value(value):
    text = str(value or "").strip()
    for separator in (" · Parent:", " • Parent:", " | Parent:"):
        if separator in text:
            return text.split(separator, 1)[0].strip()
    return text


def hmusic_now():
    if HMUSIC_TIMEZONE:
        return datetime.now(HMUSIC_TIMEZONE)
    return datetime.now()


def hmusic_today():
    return hmusic_now().date()


def hmusic_teacher_student_rows(cursor, teacher_name=None, include_all=False):
    teacher = str(teacher_name or "").strip()
    if include_all:
        cursor.execute("""
        SELECT name, COALESCE(parent_name, '')
        FROM students
        WHERE name IS NOT NULL
        AND TRIM(name) != ''
        ORDER BY name
        """)
        return cursor.fetchall()

    if not teacher:
        return []

    cursor.execute("""
    SELECT base.student_name, COALESCE(st.parent_name, '')
    FROM (
        SELECT TRIM(student_name) AS student_name
        FROM enrollments
        WHERE LOWER(TRIM(teacher_name)) = LOWER(?)
        AND COALESCE(LOWER(TRIM(status)), 'active') NOT IN ('inactive', 'cancelled', 'canceled', 'archived', 'deleted')
        UNION
        SELECT TRIM(name) AS student_name
        FROM students
        WHERE LOWER(TRIM(teacher)) = LOWER(?)
        UNION
        SELECT TRIM(student_name) AS student_name
        FROM schedule
        WHERE LOWER(TRIM(teacher)) = LOWER(?)
    ) base
    LEFT JOIN students st ON LOWER(TRIM(st.name)) = LOWER(TRIM(base.student_name))
    WHERE base.student_name IS NOT NULL
    AND TRIM(base.student_name) != ''
    GROUP BY LOWER(TRIM(base.student_name))
    ORDER BY base.student_name
    """, (teacher, teacher, teacher))
    return cursor.fetchall()


def hmusic_parent_visible_lesson_note(value):
    text = str(value or "").strip()
    if not text:
        return ""
    text = re.sub(r"(?:^|\s)Billing decision:\s*[^.。]*(?:[.。]|$)", " ", text, flags=re.IGNORECASE)
    text = re.sub(r"(?:^|\s)Lesson count:\s*[^.。]*(?:[.。]|$)", " ", text, flags=re.IGNORECASE)
    return " ".join(text.split()).strip()


def hmusic_csrf_token():
    token = session.get("_csrf_token")
    if not token:
        token = secrets.token_urlsafe(32)
        session["_csrf_token"] = token
    return token


def hmusic_validate_csrf():
    csrf_exempt_paths = {
        "/owner_login",
        "/teacher_login",
        "/parent_login",
        "/stripe/webhook",
        "/square/webhook",
    }
    if request.path in csrf_exempt_paths:
        return True
    expected = session.get("_csrf_token")
    submitted = (
        request.form.get("_csrf_token")
        or request.headers.get("X-CSRFToken")
        or request.headers.get("X-CSRF-Token")
    )
    return bool(
        expected
        and submitted
        and secrets.compare_digest(str(expected), str(submitted))
    )


CSRF_FORM_RE = re.compile(
    r'(<form\b(?=[^>]*\bmethod\s*=\s*["\']?post["\']?)[^>]*>)',
    re.IGNORECASE
)


def hmusic_inject_csrf(html):
    token = hmusic_csrf_token()
    hidden = f'\n<input type="hidden" name="_csrf_token" value="{token}">'
    html = CSRF_FORM_RE.sub(lambda match: match.group(1) + hidden, html)
    favicon_links = (
        '<link rel="icon" href="/favicon.ico" sizes="any">\n'
        '<link rel="icon" href="/hmusic-icon.svg" type="image/svg+xml">\n'
        '<link rel="apple-touch-icon" href="/hmusic-icon.png">\n'
    )
    csrf_script = (
        f'<meta name="csrf-token" content="{token}">\n'
        f'<script>window.HMUSIC_CSRF_TOKEN = "{token}";</script>'
    )
    if "</head>" in html:
        if 'rel="icon"' not in html and "rel='icon'" not in html:
            html = html.replace("</head>", favicon_links + csrf_script + "\n</head>", 1)
        else:
            html = html.replace("</head>", csrf_script + "\n</head>", 1)
    return html


@app.before_request
def enforce_csrf_token():
    if request.method in ("POST", "PUT", "PATCH", "DELETE") and not hmusic_validate_csrf():
        session.pop("_csrf_token", None)
        if request.method == "POST" and not request.is_json:
            target = request.path
            separator = "&" if "?" in target else "?"
            return redirect(f"{target}{separator}csrf_refresh=1")
        return {"ok": False, "error": "CSRF token missing or invalid. Please refresh and try again."}, 403


@app.before_request
def refresh_parent_session_lifetime():
    if session.get("parent_id") is not None or session.get("parent_student_name") is not None:
        session.permanent = True


@app.after_request
def inject_csrf_token(response):
    if (
        response.status_code == 200
        and response.content_type
        and response.content_type.startswith("text/html")
    ):
        html = response.get_data(as_text=True)
        if "<form" in html or "</head>" in html:
            html = hmusic_inject_csrf(html)
            response.set_data(html)
            response.content_length = len(response.get_data())
    return response


def add_column_if_missing(cursor, table, column_name, column_sql):
    cursor.execute(f"PRAGMA table_info({table})")
    columns = [row[1] for row in cursor.fetchall()]
    if column_name not in columns:
        cursor.execute(f"ALTER TABLE {table} ADD COLUMN {column_sql}")


def safe_minutes(value, default=0):
    if value in (None, ""):
        return default
    try:
        return int(float(value))
    except (TypeError, ValueError):
        match = re.search(r"\d+(?:\.\d+)?", str(value))
        if not match:
            return default
        try:
            return int(float(match.group(0)))
        except (TypeError, ValueError):
            return default


def migrate_legacy_passwords(cursor, table, limit=None):
    if os.environ.get("HMUSIC_RUN_PASSWORD_MIGRATION") != "1":
        return 0
    cursor.execute(f"PRAGMA table_info({table})")
    columns = [row[1] for row in cursor.fetchall()]
    if "password" not in columns or "password_hash" not in columns:
        return 0
    limit_clause = " LIMIT ?" if limit else ""
    params = (int(limit),) if limit else ()
    cursor.execute(f"""
    SELECT id, password
    FROM {table}
    WHERE (password_hash IS NULL OR password_hash = '')
    AND password IS NOT NULL
    AND password != ''
    {limit_clause}
    """, params)
    migrated = 0
    for record_id, legacy_password in cursor.fetchall():
        cursor.execute(
            f"UPDATE {table} SET password_hash = ?, password = '' WHERE id = ?",
            (hmusic_password_hash(legacy_password), record_id)
        )
        migrated += 1
    return migrated


def set_password_columns(cursor, table, record_id, password, must_change=True):
    cursor.execute(
        f"UPDATE {table} SET password_hash = ?, password = '', must_change_password = ? WHERE id = ?",
        (hmusic_password_hash(password), 1 if must_change else 0, record_id)
    )


