def ensure_teacher_management_schema():
    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()

    cursor.execute("""
    CREATE TABLE IF NOT EXISTS teachers (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        teacher_name TEXT UNIQUE
    )
    """)

    cursor.execute("PRAGMA table_info(teachers)")
    teacher_columns = [row[1] for row in cursor.fetchall()]
    for column_name, column_sql in [
        ("username", "username TEXT"),
        ("password", "password TEXT"),
        ("password_hash", "password_hash TEXT"),
        ("must_change_password", "must_change_password INTEGER DEFAULT 0"),
        ("hourly_rate", "hourly_rate REAL DEFAULT 30"),
        ("email", "email TEXT"),
        ("phone", "phone TEXT"),
        ("active", "active INTEGER DEFAULT 1"),
        ("notes", "notes TEXT"),
        ("created_at", "created_at TEXT"),
        ("updated_at", "updated_at TEXT")
    ]:
        if column_name not in teacher_columns:
            cursor.execute(f"ALTER TABLE teachers ADD COLUMN {column_sql}")

    cursor.execute("""
    CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE,
        password TEXT,
        password_hash TEXT,
        must_change_password INTEGER DEFAULT 0,
        role TEXT,
        display_name TEXT,
        linked_teacher_name TEXT,
        linked_student_name TEXT
    )
    """)

    for column_name, column_sql in [
        ("password", "password TEXT"),
        ("password_hash", "password_hash TEXT"),
        ("must_change_password", "must_change_password INTEGER DEFAULT 0"),
        ("role", "role TEXT"),
        ("display_name", "display_name TEXT"),
        ("linked_teacher_name", "linked_teacher_name TEXT"),
        ("linked_student_name", "linked_student_name TEXT")
    ]:
        add_column_if_missing(cursor, "users", column_name, column_sql)

    owner_username = os.environ.get("HMUSIC_OWNER_USERNAME", OWNER_USERNAME)
    owner_password = os.environ.get("HMUSIC_OWNER_PASSWORD", OWNER_PASSWORD)
    owner_display_name = os.environ.get("HMUSIC_OWNER_DISPLAY_NAME", "Owner")

    cursor.execute("SELECT COUNT(*) FROM users WHERE role = 'owner'")
    owner_count = cursor.fetchone()[0]
    if owner_count == 0:
        cursor.execute("""
        INSERT OR IGNORE INTO users (
            username,
            password,
            role,
            display_name
        )
        VALUES (?, ?, ?, ?)
        """, (
            owner_username,
            "",
            "owner",
            owner_display_name
        ))
        cursor.execute("""
        UPDATE users
        SET password_hash = ?,
            must_change_password = ?
        WHERE username = ?
        AND role = 'owner'
        """, (
            hmusic_password_hash(owner_password),
            1 if owner_password == OWNER_PASSWORD else 0,
            owner_username
        ))

    migrate_legacy_passwords(cursor, "teachers", limit=5)
    migrate_legacy_passwords(cursor, "users", limit=5)

    conn.commit()
    conn.close()


def teacher_login_username(teacher_name):
    base = "".join(ch.lower() for ch in (teacher_name or "") if ch.isalnum())
    return base or "teacher"


def sqlite_table_exists(cursor, table_name):
    cursor.execute("SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ?", (table_name,))
    return cursor.fetchone() is not None


def update_teacher_name_references(cursor, old_name, new_name):
    for table, column in [
        ("students", "teacher"),
        ("schedule", "teacher"),
        ("teacher_open_slots", "teacher"),
        ("teacher_course_rates", "teacher_name"),
        ("teacher_rate_cards", "teacher_name"),
        ("teacher_permissions", "teacher_name"),
        ("teacher_time_off_requests", "teacher_name")
    ]:
        if sqlite_table_exists(cursor, table):
            cursor.execute(f"UPDATE {table} SET {column} = ? WHERE {column} = ?", (new_name, old_name))


def count_teacher_references(cursor, teacher_name):
    reference_count = 0
    for table, column in [
        ("students", "teacher"),
        ("schedule", "teacher"),
        ("teacher_open_slots", "teacher"),
        ("teacher_course_rates", "teacher_name"),
        ("teacher_rate_cards", "teacher_name"),
        ("teacher_permissions", "teacher_name"),
        ("teacher_time_off_requests", "teacher_name")
    ]:
        if sqlite_table_exists(cursor, table):
            cursor.execute(f"SELECT COUNT(*) FROM {table} WHERE {column} = ?", (teacher_name,))
            reference_count += cursor.fetchone()[0] or 0
    return reference_count


def unique_teacher_username(cursor, desired_username, teacher_id, linked_teacher_name):
    base = "".join(ch for ch in (desired_username or "").strip() if ch.isalnum() or ch in ("_", "-")) or f"teacher{teacher_id}"
    candidate = base
    suffix = 2
    while True:
        cursor.execute("SELECT 1 FROM teachers WHERE username = ? AND id != ?", (candidate, teacher_id))
        teacher_conflict = cursor.fetchone() is not None
        cursor.execute("""
        SELECT 1 FROM users
        WHERE username = ?
        AND COALESCE(linked_teacher_name, '') != ?
        """, (candidate, linked_teacher_name or ""))
        user_conflict = cursor.fetchone() is not None
        if not teacher_conflict and not user_conflict:
            return candidate
        candidate = f"{base}{suffix}"
        suffix += 1


def sync_teacher_user_account(cursor, old_name, teacher_name, username, password_hash=None):
    cursor.execute("""
    SELECT id FROM users
    WHERE linked_teacher_name = ?
    AND username = ?
    ORDER BY id
    LIMIT 1
    """, (old_name, username))
    primary_user = cursor.fetchone()

    if not primary_user:
        cursor.execute("""
        SELECT id FROM users
        WHERE linked_teacher_name = ?
        AND role = 'teacher'
        ORDER BY id
        LIMIT 1
        """, (old_name,))
        primary_user = cursor.fetchone()

    if primary_user:
        primary_user_id = primary_user[0]
    else:
        cursor.execute("""
        INSERT INTO users (username, password, role, display_name, linked_teacher_name)
        VALUES (?, '', 'teacher', ?, ?)
        """, (username, teacher_name, teacher_name))
        primary_user_id = cursor.lastrowid

    password_sql = ""
    password_values = []
    if password_hash:
        password_sql = "password = '', password_hash = ?, must_change_password = 1,"
        password_values.append(password_hash)

    cursor.execute(f"""
    UPDATE users
    SET username = ?,
        {password_sql}
        role = 'teacher',
        display_name = ?,
        linked_teacher_name = ?
    WHERE id = ?
    """, (username, *password_values, teacher_name, teacher_name, primary_user_id))

    cursor.execute("""
    UPDATE users
    SET role = 'teacher',
        display_name = ?,
        linked_teacher_name = ?
    WHERE linked_teacher_name = ?
    AND id != ?
    """, (teacher_name, teacher_name, old_name, primary_user_id))



HSTUDIO_APP_NAME = "H-Music Studio"


def hstudio_money_whole(value):
    try:
        return f"${float(value):,.0f}"
    except (TypeError, ValueError):
        return "$0"


def hstudio_date_short(value):
    try:
        return datetime.strptime(value, "%Y-%m-%d").strftime("%-m/%-d")
    except Exception:
        return value or "-"


def hstudio_status_key(status):
    raw = (status or "scheduled").strip().lower()
    compact = raw.replace("-", "_").replace(" ", "_")
    if compact == "present":
        return "present"
    if compact in ("no_show", "noshow"):
        return "noshow"
    if compact in (
        "excused",
        "excused_24h",
        "cancel_>_24h",
        "cancelled_>_24h",
        "canceled_>_24h",
        "teacher_cancel",
        "teacher_cancelled",
        "last_min_cancel",
    ) or compact.startswith("cancel"):
        return "cancelled"
    return "scheduled"


def hstudio_badge(count):
    try:
        number = int(count or 0)
    except (TypeError, ValueError):
        number = 0
    if number <= 0:
        return ""
    return f'<span class="nav-badge">{number}</span>'


def get_missing_homework_lessons(limit=None, teacher_name=None):
    ensure_calendar_lesson_panel_schema()

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()

    filters = ["LOWER(COALESCE(s.status, '')) = 'present'", "COALESCE(s.homework_skipped, 0) = 0"]
    params = []
    if teacher_name:
        filters.append("s.teacher = ?")
        params.append(teacher_name)

    limit_sql = ""
    if limit:
        limit_sql = "LIMIT ?"
        params.append(limit)

    cursor.execute(f"""
    SELECT
        s.id,
        s.student_name,
        s.teacher,
        s.lesson_date,
        s.lesson_time,
        s.classroom
    FROM schedule s
    WHERE {" AND ".join(filters)}
    AND NOT EXISTS (
        SELECT 1
        FROM lessons l
        WHERE l.student_name = s.student_name
        AND TRIM(COALESCE(l.homework, '')) != ''
        AND (
            COALESCE(l.schedule_id, 0) = s.id
            OR l.lesson_date = s.lesson_date
            OR (
                l.lesson_date >= s.lesson_date
                AND l.lesson_date <= date(s.lesson_date, '+14 days')
                AND COALESCE(l.created_by, '') IN ('', 'teacher:' || COALESCE(s.teacher, ''))
            )
        )
    )
    AND TRIM(COALESCE(s.homework_assignment, '')) = ''
    ORDER BY s.lesson_date DESC, s.lesson_time DESC, s.id DESC
    {limit_sql}
    """, params)
    rows = cursor.fetchall()
    conn.close()
    return rows


def get_missing_homework_count(teacher_name=None):
    ensure_calendar_lesson_panel_schema()

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()

    filters = ["LOWER(COALESCE(s.status, '')) = 'present'", "COALESCE(s.homework_skipped, 0) = 0"]
    params = []
    if teacher_name:
        filters.append("s.teacher = ?")
        params.append(teacher_name)

    cursor.execute(f"""
    SELECT COUNT(*)
    FROM schedule s
    WHERE {" AND ".join(filters)}
    AND NOT EXISTS (
        SELECT 1
        FROM lessons l
        WHERE l.student_name = s.student_name
        AND TRIM(COALESCE(l.homework, '')) != ''
        AND (
            COALESCE(l.schedule_id, 0) = s.id
            OR l.lesson_date = s.lesson_date
            OR (
                l.lesson_date >= s.lesson_date
                AND l.lesson_date <= date(s.lesson_date, '+14 days')
                AND COALESCE(l.created_by, '') IN ('', 'teacher:' || COALESCE(s.teacher, ''))
            )
        )
    )
    AND TRIM(COALESCE(s.homework_assignment, '')) = ''
    """, params)
    count = cursor.fetchone()[0] or 0
    conn.close()
    return count


