@app.route("/delete_student/<name>", methods=["POST"])
def delete_student(name):
    if not require_owner():
        return redirect("/owner_login")

    ensure_v27_schema()
    ensure_teacher_management_schema()
    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()

    cursor.execute("SELECT name FROM students WHERE name = ? LIMIT 1", (name,))
    student = cursor.fetchone()
    if not student:
        conn.close()
        return redirect("/students")

    student_name = student[0]

    def table_exists(table_name):
        cursor.execute(
            "SELECT name FROM sqlite_master WHERE type = 'table' AND name = ?",
            (table_name,)
        )
        return cursor.fetchone() is not None

    def table_has_column(table_name, column_name):
        if not table_exists(table_name):
            return False
        cursor.execute(f"PRAGMA table_info({table_name})")
        return column_name in [row[1] for row in cursor.fetchall()]

    def delete_by_student_name(table_name, column_name="student_name"):
        if table_has_column(table_name, column_name):
            cursor.execute(
                f"DELETE FROM {table_name} WHERE {column_name} = ?",
                (student_name,)
            )

    if table_has_column("message_threads", "student_name"):
        cursor.execute("SELECT id FROM message_threads WHERE student_name = ?", (student_name,))
        thread_ids = [row[0] for row in cursor.fetchall()]
        for thread_id in thread_ids:
            if table_exists("message_attachments") and table_exists("messages"):
                cursor.execute(
                    """
                    DELETE FROM message_attachments
                    WHERE message_id IN (
                        SELECT id FROM messages WHERE thread_id = ?
                    )
                    """,
                    (thread_id,)
                )
            if table_exists("messages"):
                cursor.execute("DELETE FROM messages WHERE thread_id = ?", (thread_id,))
            if table_exists("message_participants"):
                cursor.execute("DELETE FROM message_participants WHERE thread_id = ?", (thread_id,))
            cursor.execute("DELETE FROM message_threads WHERE id = ?", (thread_id,))

    for table_name in [
        "schedule",
        "payments",
        "invoices",
        "lessons",
        "student_ledger",
        "parent_students",
        "enrollments",
        "student_course_rates",
        "student_credit_wallets",
        "parent_booking_requests",
        "event_rsvps",
        "reschedule_requests",
        "child_os_requests",
    ]:
        delete_by_student_name(table_name)

    cursor.execute("DELETE FROM students WHERE name = ?", (student_name,))
    conn.commit()
    conn.close()
    return redirect("/students")


def ensure_student_detail_schema():
    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()

    cursor.execute("""
    CREATE TABLE IF NOT EXISTS students (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT UNIQUE,
        teacher TEXT,
        parent_name TEXT,
        parent_email TEXT,
        parent_phone TEXT,
        lessons_left INTEGER DEFAULT 0
    )
    """)
    for column_name, column_sql in [
        ("name", "name TEXT"),
        ("teacher", "teacher TEXT"),
        ("parent_name", "parent_name TEXT"),
        ("parent_email", "parent_email TEXT"),
        ("parent_phone", "parent_phone TEXT"),
        ("lessons_left", "lessons_left INTEGER DEFAULT 0"),
    ]:
        add_column_if_missing(cursor, "students", column_name, column_sql)

    cursor.execute("""
    CREATE TABLE IF NOT EXISTS lessons (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        student_name TEXT,
        lesson_date TEXT,
        lesson_content TEXT,
        performance TEXT,
        homework TEXT
    )
    """)
    for column_name, column_sql in [
        ("student_name", "student_name TEXT"),
        ("lesson_date", "lesson_date TEXT"),
        ("lesson_content", "lesson_content TEXT"),
        ("performance", "performance TEXT"),
        ("homework", "homework TEXT"),
    ]:
        add_column_if_missing(cursor, "lessons", column_name, column_sql)

    cursor.execute("""
    CREATE TABLE IF NOT EXISTS payments (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        student_name TEXT,
        payment_date TEXT,
        amount REAL,
        lessons_added INTEGER,
        payment_method TEXT
    )
    """)
    for column_name, column_sql in [
        ("student_name", "student_name TEXT"),
        ("payment_date", "payment_date TEXT"),
        ("amount", "amount REAL"),
        ("lessons_added", "lessons_added INTEGER"),
        ("payment_method", "payment_method TEXT"),
    ]:
        add_column_if_missing(cursor, "payments", column_name, column_sql)

    cursor.execute("""
    CREATE TABLE IF NOT EXISTS invoices (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        student_name TEXT,
        charge_lessons REAL,
        amount REAL,
        status TEXT,
        invoice_type TEXT,
        created_at TEXT
    )
    """)
    for column_name, column_sql in [
        ("student_name", "student_name TEXT"),
        ("charge_lessons", "charge_lessons REAL"),
        ("amount", "amount REAL"),
        ("status", "status TEXT"),
        ("invoice_type", "invoice_type TEXT"),
        ("created_at", "created_at TEXT"),
        ("payment_reminder_sent_at", "payment_reminder_sent_at TEXT"),
        ("payment_reminder_count", "payment_reminder_count INTEGER DEFAULT 0"),
    ]:
        add_column_if_missing(cursor, "invoices", column_name, column_sql)

    cursor.execute("""
    CREATE TABLE IF NOT EXISTS student_ledger (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        student_name TEXT,
        entry_type TEXT,
        amount REAL,
        description TEXT,
        related_invoice_id INTEGER,
        created_at TEXT,
        related_schedule_id INTEGER
    )
    """)
    for column_name, column_sql in [
        ("student_name", "student_name TEXT"),
        ("entry_type", "entry_type TEXT"),
        ("amount", "amount REAL"),
        ("description", "description TEXT"),
        ("related_invoice_id", "related_invoice_id INTEGER"),
        ("created_at", "created_at TEXT"),
        ("related_schedule_id", "related_schedule_id INTEGER"),
    ]:
        add_column_if_missing(cursor, "student_ledger", column_name, column_sql)

    cursor.execute("""
    CREATE TABLE IF NOT EXISTS schedule (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        student_name TEXT,
        lesson_date TEXT,
        lesson_time TEXT,
        teacher TEXT,
        classroom TEXT,
        status TEXT DEFAULT 'scheduled',
        duration INTEGER,
        schedule_type TEXT
    )
    """)
    for column_name, column_sql in [
        ("student_name", "student_name TEXT"),
        ("lesson_date", "lesson_date TEXT"),
        ("lesson_time", "lesson_time TEXT"),
        ("teacher", "teacher TEXT"),
        ("classroom", "classroom TEXT"),
        ("status", "status TEXT DEFAULT 'scheduled'"),
        ("duration", "duration INTEGER"),
        ("schedule_type", "schedule_type TEXT"),
    ]:
        add_column_if_missing(cursor, "schedule", column_name, column_sql)

    cursor.execute("""
    CREATE TABLE IF NOT EXISTS parent_profiles (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        parent_name TEXT,
        email TEXT UNIQUE,
        phone TEXT,
        active INTEGER DEFAULT 1,
        must_change_password INTEGER DEFAULT 0
    )
    """)
    for column_name, column_sql in [
        ("parent_name", "parent_name TEXT"),
        ("email", "email TEXT"),
        ("phone", "phone TEXT"),
        ("active", "active INTEGER DEFAULT 1"),
        ("must_change_password", "must_change_password INTEGER DEFAULT 0"),
    ]:
        add_column_if_missing(cursor, "parent_profiles", column_name, column_sql)

    cursor.execute("""
    CREATE TABLE IF NOT EXISTS parent_students (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        parent_id INTEGER,
        student_name TEXT,
        active INTEGER DEFAULT 1
    )
    """)
    for column_name, column_sql in [
        ("parent_id", "parent_id INTEGER"),
        ("student_name", "student_name TEXT"),
        ("active", "active INTEGER DEFAULT 1"),
    ]:
        add_column_if_missing(cursor, "parent_students", column_name, column_sql)

    cursor.execute("""
    CREATE TABLE IF NOT EXISTS teachers (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        teacher_name TEXT UNIQUE
    )
    """)
    add_column_if_missing(cursor, "teachers", "teacher_name", "teacher_name TEXT")

    cursor.execute("""
    CREATE TABLE IF NOT EXISTS enrollments (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        student_name TEXT,
        teacher_name TEXT,
        status TEXT DEFAULT 'active'
    )
    """)
    for column_name, column_sql in [
        ("student_name", "student_name TEXT"),
        ("teacher_name", "teacher_name TEXT"),
        ("status", "status TEXT DEFAULT 'active'"),
    ]:
        add_column_if_missing(cursor, "enrollments", column_name, column_sql)

    conn.commit()
    conn.close()


@app.route("/student/<name>")
def student_detail(name):
    ensure_student_detail_schema()
    ensure_v321_schema()
    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()

    cursor.execute("""
    SELECT name, teacher, parent_email, parent_phone, lessons_left, COALESCE(parent_name, '')
    FROM students
    WHERE name = ?
    """, (name,))

    student = cursor.fetchone()

    if not student:
        conn.close()
        return "<h1>Student not found</h1>"

    today_str = date.today().strftime("%Y-%m-%d")

    cursor.execute("""
    SELECT lesson_date, lesson_content, performance, homework
    FROM lessons
    WHERE student_name = ?
    ORDER BY id DESC
    LIMIT 8
    """, (name,))
    lessons = cursor.fetchall()

    cursor.execute("""
    SELECT id, payment_date, amount, lessons_added, payment_method, COALESCE(course_type_name, ''), COALESCE(teacher_name, '')
    FROM payments
    WHERE student_name = ?
    ORDER BY id DESC
    LIMIT 8
    """, (name,))
    payments = cursor.fetchall()

    cursor.execute("""
    SELECT id, charge_lessons, amount, status, invoice_type, created_at,
           COALESCE(payment_reminder_sent_at, ''), COALESCE(payment_reminder_count, 0)
    FROM invoices
    WHERE student_name = ?
    ORDER BY id DESC
    LIMIT 8
    """, (name,))
    invoices = cursor.fetchall()

    cursor.execute("""
    SELECT id, amount, description, created_at, related_schedule_id
    FROM student_ledger
    WHERE student_name = ?
    AND entry_type = 'pending_last_min_fee'
    AND related_invoice_id IS NULL
    AND amount > 0
    ORDER BY id DESC
    """, (name,))
    pending_fees = cursor.fetchall()

    cursor.execute("""
    SELECT lesson_date, lesson_time, teacher, classroom, status, duration, schedule_type
    FROM schedule
    WHERE student_name = ?
    AND lesson_date >= ?
    AND COALESCE(status, '') NOT IN ('cancelled', 'canceled')
    ORDER BY lesson_date, lesson_time
    LIMIT 1
    """, (name, today_str))
    next_lesson = cursor.fetchone()

    cursor.execute("""
    SELECT id, parent_name, email, phone, active, must_change_password
    FROM parent_profiles
    WHERE email = ?
    LIMIT 1
    """, (student[2] or "",))
    parent_account = cursor.fetchone() if student[2] else None

    if not parent_account:
        cursor.execute("""
        SELECT p.id, p.parent_name, p.email, p.phone, p.active, p.must_change_password
        FROM parent_profiles p
        JOIN parent_students ps ON ps.parent_id = p.id
        WHERE ps.student_name = ?
        AND ps.active = 1
        ORDER BY p.active DESC, p.id DESC
        LIMIT 1
        """, (student[0],))
        parent_account = cursor.fetchone()

    teacher_links = []
    if student[1]:
        teacher_links.append((student[1], "Primary Teacher"))

    cursor.execute("""
    SELECT DISTINCT teacher_name
    FROM enrollments
    WHERE student_name = ?
    AND status = 'active'
    AND teacher_name IS NOT NULL
    AND teacher_name != ''
    ORDER BY teacher_name
    """, (name,))
    for row in cursor.fetchall():
        teacher_links.append((row[0], "Active Enrollment"))

    cursor.execute("""
    SELECT DISTINCT teacher
    FROM schedule
    WHERE student_name = ?
    AND teacher IS NOT NULL
    AND teacher != ''
    ORDER BY teacher
    """, (name,))
    for row in cursor.fetchall():
        teacher_links.append((row[0], "Scheduled Lesson"))

    cursor.execute("SELECT teacher_name FROM teachers ORDER BY teacher_name")
    all_teachers = cursor.fetchall()
    total_course_credits, course_credit_rows = hmusic_student_total_course_credits(cursor, student[0], student[4])
    teacher_has_access = (
        require_teacher()
        and teacher_can_access_student_record(cursor, student[0], session.get("teacher_name"))
    )
    conn.close()

    seen_teacher_links = set()
    teacher_link_html = ""
    for teacher_name, source in teacher_links:
        key = (teacher_name, source)
        if key in seen_teacher_links:
            continue
        seen_teacher_links.add(key)
        teacher_link_html += f"<li>{escape(teacher_name)} <span style='color:#6b7280;'>({source})</span></li>"
    if not teacher_link_html:
        teacher_link_html = "<li>No teacher linked yet.</li>"

    teacher_options = ""
    for t in all_teachers:
        selected = "selected" if t[0] == student[1] else ""
        teacher_options += f'<option value="{escape(t[0])}" {selected}>{escape(t[0])}</option>'

    student_url_name = quote(student[0])
    teacher_link_form = ""
    if require_owner():
        teacher_link_form = f"""
        <form method="POST" action="/link_student_teacher/{student_url_name}" class="inline-form">
            <label>Primary teacher</label>
            <div class="inline-row">
                <select name="teacher">{teacher_options}</select>
                <button type="submit">Save</button>
            </div>
        </form>
        """

    lesson_html = ""
    if lessons:
        for lesson in lessons:
            visible_lesson_note = hmusic_parent_visible_lesson_note(lesson[1]) or "No lesson notes yet."
            lesson_html += f"""
            <div class="timeline-item">
                <div class="timeline-date">{escape(lesson[0] or '')}</div>
                <div>
                    <b>{escape(lesson[2] or 'Lesson note')}</b>
                    <p>{escape(visible_lesson_note)}</p>
                    <p class="muted"><b>Homework:</b> {escape(lesson[3] or 'No homework recorded.')}</p>
                </div>
                <span class="pill">Lesson</span>
            </div>
            """
    else:
        lesson_html = "<div class='empty'>No lesson history yet.</div>"

    pending_fee_html = ""
    pending_fee_total = round(sum(float(fee[1] or 0) for fee in pending_fees), 2)
    if pending_fees and require_owner():
        pending_fee_html += f"""
        <div class="pending-fee-summary">
            <div>
                <b>Pending fee: ${hmusic_money(pending_fee_total)}</b>
                <p>Last Min Cancel fee(s). They will be added to the next package invoice by default.</p>
            </div>
            <a class="button" href="/create_package_invoice/{student_url_name}">Add to next invoice</a>
        </div>
        """
        for fee in pending_fees:
            pending_fee_html += f"""
            <div class="timeline-item billing pending-fee">
                <div class="timeline-date">{escape(str(fee[3] or 'Pending'))}</div>
                <div>
                    <b>Last Min Cancel fee · ${hmusic_money(fee[1])}</b>
                    <p>{escape(str(fee[2] or 'Pending fee'))}</p>
                </div>
                <div class="payment-actions">
                    <form class="inline-pay-form" method="POST" action="/create_pending_fee_invoice/{fee[0]}">
                        <button type="submit">Create invoice now</button>
                    </form>
                    <form class="inline-pay-form" method="POST" action="/waive_pending_fee/{fee[0]}" onsubmit="return confirm('Waive this pending fee?');">
                        <button class="danger-link" type="submit">Waive</button>
                    </form>
                </div>
            </div>
            """

    payment_html = pending_fee_html
    for invoice in invoices:
        invoice_id, charge_lessons, amount, status, invoice_type, created_at, reminder_sent_at, reminder_count = invoice
        status_text = status or "unpaid"
        action_html = ""
        if require_owner() and status_text != "paid":
            action_html = f"""
            <form class="inline-pay-form" method="POST" action="/pay_invoice/{invoice_id}">
                <input type="hidden" name="payment_date" value="{date.today().strftime('%Y-%m-%d')}">
                <input type="hidden" name="payment_method" value="Owner marked paid">
                <button type="submit">Mark paid</button>
            </form>
            """
        reminder_html = ""
        reminder_meta = ""
        if require_owner() and status_text in ("unpaid", "payment_failed"):
            reminder_html = f"""
            <form class="inline-pay-form" method="POST" action="/send_invoice_payment_reminder/{invoice_id}" onsubmit="return confirm('Send payment reminder for invoice #{invoice_id}?');">
                <input type="hidden" name="return_to" value="/student/{student_url_name}#payments">
                <button type="submit">Send reminder</button>
            </form>
            """
            if reminder_sent_at or reminder_count:
                reminder_meta = f"<p class='muted reminder-meta'>Reminder: {escape(str(reminder_count or 0))} sent{(' · last ' + escape(str(reminder_sent_at))) if reminder_sent_at else ''}</p>"
        delete_html = ""
        if require_owner() and status_text in ("unpaid", "payment_failed"):
            delete_html = f"""
            <form class="inline-pay-form" method="POST" action="/delete_invoice/{invoice_id}" onsubmit="return confirm('Delete invoice #{invoice_id}? This invoice has not been paid. This cannot be undone.');">
                <button class="danger-link" type="submit">Delete</button>
            </form>
            """
        payment_html += f"""
            <div class="timeline-item billing">
                <div class="timeline-date">{escape(str(created_at or 'Invoice'))}</div>
                <div>
                    <b>Invoice #{invoice_id} · ${escape(str(amount or '0'))}</b>
                    <p>{escape(str(charge_lessons or 0))} lesson(s) · {escape(str(invoice_type or 'invoice'))}</p>
                    {reminder_meta}
                </div>
                <div class="payment-actions">
                    <span class="pill {'ok' if status_text == 'paid' else 'amber'}">{escape(str(status_text).title())}</span>
                    {reminder_html}
                    {action_html}
                    {delete_html}
                </div>
            </div>
        """

    if payments:
        for payment in payments:
            payment_id, payment_date, amount, lessons_added, payment_method, payment_course, payment_teacher = payment
            payment_credit_note = ""
            if payment_course or payment_teacher:
                payment_credit_note = f"<p class='muted'>Credit bucket: {escape(str(payment_course or 'Course'))} · {escape(str(payment_teacher or 'Unassigned'))}</p>"
            payment_html += f"""
            <div class="timeline-item billing">
                <div class="timeline-date">{escape(payment_date or '')}</div>
                <div>
                    <b>${escape(str(amount or '0'))}</b>
                    <p>{escape(str(lessons_added or 0))} lesson(s) added · {escape(payment_method or 'Payment')}</p>
                    {payment_credit_note}
                </div>
                <div class="payment-actions">
                    <span class="pill amber">Payment</span>
                    <details class="payment-edit">
                        <summary>Edit</summary>
                        <form method="POST" action="/edit_payment/{payment_id}">
                            <label>Date</label>
                            <input type="date" name="payment_date" value="{escape(payment_date or '', quote=True)}">
                            <label>Amount</label>
                            <input type="number" step="0.01" name="amount" value="{escape(str(amount or 0), quote=True)}">
                            <label>Lessons added</label>
                            <input type="number" name="lessons_added" value="{escape(str(lessons_added or 0), quote=True)}">
                            <label>Method</label>
                            <input name="payment_method" value="{escape(payment_method or 'Payment', quote=True)}">
                            <button type="submit">Save</button>
                        </form>
                    </details>
                    <form class="inline-pay-form" method="POST" action="/delete_payment/{payment_id}" onsubmit="return confirm('Delete this payment and reverse its lesson credit change?');">
                        <button class="danger-link" type="submit">Delete</button>
                    </form>
                </div>
            </div>
            """
    if not payment_html:
        payment_html = "<div class='empty'>No payment history yet.</div>"
    if require_owner():
        payment_html = f"""
        <div class="payment-toolbar">
            <a class="button primary" href="/payment/{student_url_name}">Record payment</a>
            <a class="button" href="/create_package_invoice/{student_url_name}">Create invoice</a>
            <a class="button" href="/student_ledger/{student_url_name}">Student ledger</a>
        </div>
        {payment_html}
        """

    def lesson_count(value):
        try:
            return int(float(value or 0))
        except (TypeError, ValueError):
            return 0

    lessons_left = lesson_count(student[4])
    course_credit_count = len(course_credit_rows)
    has_empty_course_credit = any(float(row[3] or 0) <= 0 for row in course_credit_rows)
    has_low_course_credit = any(0 < float(row[3] or 0) <= 2 for row in course_credit_rows)
    family_status_class = "ok" if parent_account else "danger"
    family_status_text = "Family workspace ready" if parent_account else "Family setup needed"
    next_lesson_label = "Not scheduled"
    next_lesson_meta = "Create a recurring lesson before activating parent app use."
    if next_lesson:
        next_lesson_label = f"{next_lesson[0]} · {next_lesson[1] or ''}".strip()
        next_lesson_meta = " · ".join([x for x in [next_lesson[2], next_lesson[3], f"{next_lesson[5] or ''} min".strip()] if x])

    parent_status = "No parent app account yet"
    parent_status_class = "danger"
    family_management_html = f"""
        <div class="account-box warning">
            <div class="info-line"><span>Status</span><b>No family workspace connected</b></div>
            <div class="info-line"><span>Parent email</span><b>{escape(student[2] or 'Missing parent email')}</b></div>
            <p class="muted">Family billing, parent app access, and course credits are managed in Family Workspace.</p>
            <div class="button-grid">
                <form method="POST" action="/send_parent_welcome/{student_url_name}">
                    <button class="primary" type="submit">Create family workspace</button>
                </form>
                <a class="button" href="/edit_student/{student_url_name}">Edit student contact</a>
            </div>
        </div>
    """
    if parent_account:
        parent_status = "Active parent app account" if parent_account[4] else "Parent account inactive"
        parent_status_class = "ok" if parent_account[4] else "danger"
        must_change = "Must change password" if parent_account[5] else "Password set"
        family_management_html = f"""
        <div class="account-box">
            <div class="info-line"><span>Guardian</span><b>{escape(parent_account[1] or student[5] or 'Parent')}</b></div>
            <div class="info-line"><span>Login email</span><b>{escape(parent_account[2] or student[2] or '')}</b></div>
            <div class="info-line"><span>Family status</span><b>{must_change}</b></div>
            <p class="muted">Open Family Workspace to manage parent app access, billing, children, and course credits.</p>
            <div class="button-grid">
                <a class="button primary" href="/parent_admin/{parent_account[0]}">Open Family Workspace</a>
                <a class="button" href="/edit_student/{student_url_name}">Edit student info</a>
            </div>
        </div>
        """

    family_workspace_top_link = (
        f'<a class="button" href="/parent_admin/{parent_account[0]}">Family Workspace</a>'
        if require_owner() and parent_account else ""
    )

    owner_actions = ""
    if require_owner():
        owner_actions = f"""
        <div class="button-grid">
            <a class="button primary" href="/calendar">Create schedule</a>
            <a class="button" href="/add_lesson/{student_url_name}">Add lesson note</a>
            <a class="button" href="/generate_parent_email/{student_url_name}">Generate lesson email</a>
            <a class="button" href="/send_parent_email/{student_url_name}">Send lesson email</a>
            {family_workspace_top_link}
        </div>
        """
    elif teacher_has_access:
        owner_actions = f"""
        <div class="button-grid">
            <a class="button primary" href="/add_lesson/{student_url_name}">Add lesson note</a>
            <a class="button" href="/teacher_dashboard">Teacher dashboard</a>
        </div>
        """
    elif require_parent():
        owner_actions = '<div class="button-grid"><a class="button primary" href="/parent_dashboard">Back to Parent App</a></div>'

    teacher_list_html = f"<ul class='teacher-list'>{teacher_link_html}</ul>"

    return f"""
    <html>
    <head>
        <title>{escape(student[0])} · Student Profile</title>
        <style>
            :root {{
                --bg:#f6f7fb; --card:#ffffff; --text:#111827; --muted:#6b7280; --border:#e5e7eb;
                --blue:#1f6fb8; --blue-soft:#eaf4ff; --green:#2f855a; --green-soft:#e8f5ee;
                --amber:#9a6700; --amber-soft:#fff4d6; --red:#dc2626; --red-soft:#fee2e2;
            }}
            body {{ margin:0; font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif; background:var(--bg); color:var(--text); }}
            .page {{ padding:24px; }}
            .topbar {{ display:flex; justify-content:space-between; gap:16px; align-items:center; margin-bottom:16px; }}
            .crumb {{ color:var(--muted); font-size:13px; margin-bottom:4px; }}
            h1, h2, h3, p {{ margin:0; }}
            h1 {{ font-size:28px; }}
            h2 {{ font-size:18px; margin-bottom:12px; }}
            h3 {{ font-size:16px; }}
            .layout {{ display:grid; grid-template-columns:minmax(300px, 420px) minmax(480px, 1fr); gap:16px; align-items:start; }}
            .card {{ background:var(--card); border:1px solid var(--border); border-radius:14px; box-shadow:0 8px 24px rgba(15,23,42,.06); overflow:hidden; }}
            .section {{ padding:18px; border-bottom:1px solid var(--border); }}
            .section:last-child {{ border-bottom:0; }}
            .student-head {{ display:flex; gap:14px; align-items:flex-start; }}
            .avatar {{ width:52px; height:52px; border-radius:12px; background:var(--blue); color:white; display:grid; place-items:center; font-weight:800; font-size:18px; flex:0 0 auto; }}
            .name-row {{ display:flex; gap:8px; flex-wrap:wrap; align-items:center; }}
            .muted {{ color:var(--muted); font-size:14px; line-height:1.45; }}
            .pill {{ display:inline-flex; align-items:center; border-radius:999px; padding:4px 9px; background:#f3f4f6; color:#374151; font-size:12px; font-weight:800; }}
            .pill.ok {{ background:var(--green-soft); color:var(--green); }}
            .pill.danger {{ background:var(--red-soft); color:var(--red); }}
            .pill.amber {{ background:var(--amber-soft); color:var(--amber); }}
            .kpis {{ display:grid; grid-template-columns:repeat(3, 1fr); gap:10px; margin-top:16px; }}
            .kpi {{ border:1px solid var(--border); background:#f9fafb; border-radius:10px; padding:12px; }}
            .kpi span {{ display:block; color:var(--muted); font-size:12px; font-weight:700; text-transform:uppercase; }}
            .kpi b {{ display:block; font-size:20px; line-height:1.15; margin-top:4px; }}
            .info-list {{ display:grid; gap:10px; margin-top:12px; }}
            .info-line {{ display:grid; grid-template-columns:118px 1fr; gap:12px; align-items:start; }}
            .info-line span {{ color:var(--muted); font-size:13px; }}
            .info-line b {{ font-size:14px; word-break:break-word; }}
            .account-box {{ border:1px solid #bfdbfe; background:var(--blue-soft); border-radius:12px; padding:14px; display:grid; gap:8px; }}
            .account-box.warning {{ border-color:#fecaca; background:#fff7f7; }}
            .button-grid {{ display:grid; grid-template-columns:repeat(2, minmax(0, 1fr)); gap:10px; margin-top:12px; }}
            a.button, button {{ display:inline-flex; align-items:center; justify-content:center; min-height:42px; border:1px solid var(--border); border-radius:10px; padding:10px 12px; color:var(--text); background:white; text-decoration:none; font-weight:800; font-size:14px; box-sizing:border-box; width:100%; cursor:pointer; }}
            a.button.primary, button.primary {{ background:var(--blue); border-color:var(--blue); color:white; }}
            .tabs {{ display:flex; gap:8px; padding:14px 18px 0; flex-wrap:wrap; }}
            .tab {{ border:1px solid var(--border); border-radius:999px; padding:7px 10px; color:var(--muted); font-size:13px; font-weight:800; background:white; cursor:pointer; }}
            .tabs .tab {{ width:auto; min-height:auto; display:inline-flex; align-items:center; justify-content:center; }}
            .tab.active {{ background:var(--blue-soft); border-color:#bfdbfe; color:var(--blue); }}
            .tab-panel {{ display:none; }}
            .tab-panel.active {{ display:block; }}
            .setup-grid {{ display:grid; grid-template-columns:1fr 1fr; gap:12px; }}
            .setup-card {{ border:1px solid var(--border); border-radius:12px; padding:14px; background:#fbfdff; }}
            .timeline {{ display:grid; gap:10px; }}
            .timeline-item {{ display:grid; grid-template-columns:96px 1fr auto; gap:12px; border:1px solid var(--border); border-radius:12px; padding:12px; align-items:start; background:white; }}
            .timeline-item.billing {{ background:#fffdf6; }}
            .payment-toolbar {{ display:grid; grid-template-columns:repeat(3, minmax(0, 1fr)); gap:10px; margin-bottom:10px; }}
            .pending-fee-summary {{ display:flex; justify-content:space-between; align-items:center; gap:10px; border:1px solid #fed7aa; background:#fff7ed; color:#9a3412; border-radius:12px; padding:12px; margin-bottom:10px; }}
            .pending-fee-summary p {{ margin:3px 0 0; color:#9a3412; font-size:12px; }}
            .pending-fee {{ background:#fffbeb; border-color:#fde68a; }}
            .payment-actions {{ display:flex; gap:8px; align-items:center; justify-content:flex-end; flex-wrap:wrap; }}
            .inline-pay-form {{ margin:0; }}
            .inline-pay-form button {{ width:auto; min-height:30px; padding:6px 10px; border-radius:8px; font-size:12px; background:var(--blue); color:white; border-color:var(--blue); }}
            .inline-pay-form .danger-link {{ background:white; color:var(--red); border-color:#fecaca; }}
            .payment-edit {{ position:relative; }}
            .payment-edit summary {{ list-style:none; min-height:30px; display:inline-flex; align-items:center; justify-content:center; border:1px solid var(--border); border-radius:8px; padding:6px 10px; background:white; color:var(--blue); font-size:12px; font-weight:800; cursor:pointer; }}
            .payment-edit summary::-webkit-details-marker {{ display:none; }}
            .payment-edit form {{ position:absolute; right:0; top:36px; z-index:3; width:240px; display:grid; gap:6px; padding:12px; border:1px solid var(--border); border-radius:12px; background:white; box-shadow:0 12px 32px rgba(15,23,42,.14); }}
            .payment-edit label {{ color:var(--muted); font-size:11px; font-weight:800; }}
            .payment-edit input {{ width:100%; min-height:34px; border:1px solid var(--border); border-radius:8px; padding:0 9px; font-size:13px; }}
            .payment-edit button {{ min-height:34px; background:var(--blue); color:white; border-color:var(--blue); }}
            .timeline-date {{ color:var(--muted); font-weight:800; font-size:13px; }}
            .timeline-item p {{ margin-top:4px; line-height:1.45; }}
            .empty {{ border:1px dashed var(--border); border-radius:12px; padding:16px; color:var(--muted); background:#fafafa; }}
            .teacher-list {{ margin:10px 0 0; padding-left:18px; color:var(--text); }}
            .teacher-list li {{ margin-bottom:6px; }}
            .inline-form label {{ display:block; color:var(--muted); font-size:13px; font-weight:800; margin-bottom:8px; }}
            .inline-row {{ display:grid; grid-template-columns:1fr 96px; gap:8px; }}
            select {{ width:100%; border:1px solid var(--border); border-radius:10px; min-height:42px; padding:0 10px; font-size:14px; background:white; }}
            .top-actions {{ display:flex; gap:8px; flex-wrap:wrap; min-width:300px; }}
            .top-actions a {{ width:auto; min-height:38px; }}
            @media (max-width:900px) {{
                .layout, .setup-grid {{ grid-template-columns:1fr; }}
                .button-grid {{ grid-template-columns:1fr; }}
                .kpis {{ grid-template-columns:1fr; }}
                .timeline-item {{ grid-template-columns:1fr; }}
                .payment-toolbar {{ grid-template-columns:1fr; }}
                .topbar {{ align-items:flex-start; flex-direction:column; }}
            }}
        </style>
    </head>
    <body>
        <div class="page">
            <div class="topbar">
                <div>
                    <div class="crumb">Owner / Students / {escape(student[0])}</div>
                    <h1>Student Profile</h1>
                </div>
                <div class="top-actions">
                    <a class="button" href="/calendar">Back to Schedule</a>
                    <a class="button" href="/students">Back to Students</a>
                    {family_workspace_top_link}
                    <a class="button primary" href="/edit_student/{student_url_name}">Edit Student</a>
                </div>
            </div>

            <div class="layout">
                <div class="card">
                    <div class="section">
                        <div class="student-head">
                            <div class="avatar">{escape(''.join([part[:1] for part in student[0].split()[:2]]).upper() or 'ST')}</div>
                            <div>
                                <div class="name-row">
                                    <h2>{escape(student[0])}</h2>
                                    <span class="pill {parent_status_class}">{parent_status}</span>
                                </div>
                                <p class="muted">Primary teacher: {escape(student[1] or 'Unassigned')}</p>
                            </div>
                        </div>
                        <div class="kpis">
                            <div class="kpi"><span>Family workspace</span><b>{family_status_text}</b></div>
                            <div class="kpi"><span>Primary teacher</span><b>{escape(student[1] or 'Unassigned')}</b></div>
                            <div class="kpi"><span>Next</span><b>{'Set' if next_lesson else 'None'}</b></div>
                        </div>
                    </div>

                    <div class="section">
                        <h2>Family</h2>
                        <div class="info-list">
                            <div class="info-line"><span>Guardian</span><b>{escape(student[5] or (parent_account[1] if parent_account else '') or 'Not set')}</b></div>
                            <div class="info-line"><span>Email</span><b>{escape(student[2] or (parent_account[2] if parent_account else '') or 'Not set')}</b></div>
                            <div class="info-line"><span>Phone</span><b>{escape(student[3] or (parent_account[3] if parent_account else '') or 'Not set')}</b></div>
                        </div>
                    </div>

                    <div class="section">
                        <h2>Family Workspace</h2>
                        {family_management_html}
                    </div>

                    <div class="section">
                        <h2>Teacher Access</h2>
                        {teacher_list_html}
                        {teacher_link_form}
                        <p class="muted" style="margin-top:10px;">Teacher access is automatic through primary teacher, active enrollment, or scheduled lessons.</p>
                    </div>
                </div>

                <div class="card">
                    <div class="tabs">
                        <button class="tab active" type="button" data-student-tab="overview">Overview</button>
                        <button class="tab" type="button" data-student-tab="lessons">Lessons</button>
                        <button class="tab" type="button" data-student-tab="messages">Messages</button>
                    </div>

                    <div class="tab-panel active" data-student-panel="overview">
                        <div class="section">
                            <div class="setup-grid">
                                <div class="setup-card">
                                    <h2>Next Lesson</h2>
                                    <p><b>{escape(next_lesson_label)}</b></p>
                                    <p class="muted">{escape(next_lesson_meta)}</p>
                                </div>
                                <div class="setup-card">
                                    <h2>Setup Checklist</h2>
                                    <p class="muted">Confirm schedule, package, invoice, parent app access, and policy before family starts using the app.</p>
                                </div>
                            </div>
                        </div>

                        <div class="section">
                            <h2>Quick Actions</h2>
                            {owner_actions}
                        </div>
                    </div>

                    <div class="tab-panel" data-student-panel="lessons">
                        <div class="section">
                            <h2>Lesson History</h2>
                            <div class="timeline">{lesson_html}</div>
                        </div>
                    </div>

                    <div class="tab-panel" data-student-panel="messages">
                        <div class="section">
                            <h2>Messages</h2>
                            <div class="button-grid">
                                <a class="button primary" href="/generate_parent_email/{student_url_name}">Generate lesson email</a>
                                <a class="button" href="/send_parent_email/{student_url_name}">Send lesson email</a>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
        <script>
            (function() {{
                const tabs = Array.from(document.querySelectorAll('[data-student-tab]'));
                const panels = Array.from(document.querySelectorAll('[data-student-panel]'));
                function showStudentTab(name) {{
                    tabs.forEach(tab => tab.classList.toggle('active', tab.dataset.studentTab === name));
                    panels.forEach(panel => panel.classList.toggle('active', panel.dataset.studentPanel === name));
                    if (history.replaceState) history.replaceState(null, '', '#' + name);
                }}
                tabs.forEach(tab => tab.addEventListener('click', () => showStudentTab(tab.dataset.studentTab)));
                const initial = (window.location.hash || '').replace('#', '');
                if (initial === 'payments' && {str(bool(parent_account)).lower()}) window.location.href = "/parent_admin/{parent_account[0] if parent_account else ''}#family-billing";
                else if (['overview', 'lessons', 'messages'].includes(initial)) showStudentTab(initial);
            }})();
        </script>
    </body>
    </html>
    """



@app.route("/link_student_teacher/<name>", methods=["POST"])
def link_student_teacher(name):
    if not require_owner():
        return redirect("/owner_login")

    teacher = request.form.get("teacher")
    if not teacher:
        return f"<h1>Please select a teacher.</h1><p><a href='/student/{name}'>Back</a></p>"

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()

    cursor.execute("SELECT 1 FROM students WHERE name = ?", (name,))
    if not cursor.fetchone():
        conn.close()
        return "<h1>Student not found</h1>"

    cursor.execute("SELECT 1 FROM teachers WHERE teacher_name = ?", (teacher,))
    if not cursor.fetchone():
        conn.close()
        return "<h1>Teacher not found</h1>"

    cursor.execute("""
    UPDATE students
    SET teacher = ?
    WHERE name = ?
    """, (teacher, name))

    conn.commit()
    conn.close()
    return redirect(f"/student/{name}")


@app.route("/delete_invoice/<int:invoice_id>", methods=["POST"])
def delete_invoice(invoice_id):
    if not require_owner():
        return redirect("/owner_login")

    ensure_v321_schema()
    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    cursor.execute("""
    SELECT id, student_name, status
    FROM invoices
    WHERE id = ?
    """, (invoice_id,))
    invoice = cursor.fetchone()
    if not invoice:
        conn.close()
        return "<h1>Invoice not found</h1>"

    student_name = invoice[1]
    status = invoice[2] or "unpaid"
    if status not in ("unpaid", "payment_failed"):
        conn.close()
        return f"""
        <h1>Invoice Cannot Be Deleted</h1>
        <p>Invoice #{invoice_id} is currently {escape(status)}. Only unpaid or failed invoices can be deleted.</p>
        <p><a href="/student/{quote(student_name)}#payments">Back to Student</a></p>
        """

    cursor.execute("DELETE FROM invoices WHERE id = ?", (invoice_id,))
    conn.commit()
    conn.close()
    return redirect(f"/student/{quote(student_name)}#payments")


@app.route("/edit_invoice/<int:invoice_id>", methods=["GET", "POST"])
def edit_invoice(invoice_id):
    if not require_owner():
        return redirect("/owner_login")

    ensure_v321_schema()
    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    cursor.execute("""
    SELECT
        i.id,
        i.student_name,
        COALESCE(i.charge_lessons, 0),
        COALESCE(i.amount, 0),
        COALESCE(i.status, 'unpaid'),
        COALESCE(i.invoice_type, 'invoice'),
        COALESCE(i.created_at, ''),
        COALESCE(i.due_date, ''),
        COALESCE(i.payment_methods, ''),
        COALESCE(i.coverage_title, ''),
        COALESCE(i.coverage_class, ''),
        COALESCE(i.coverage_start, ''),
        COALESCE(i.coverage_note, ''),
        pp.id,
        COALESCE(pp.parent_name, ''),
        COALESCE(pp.email, '')
    FROM invoices i
    LEFT JOIN parent_students ps
        ON ps.student_name = i.student_name
        AND ps.active = 1
        AND ps.id = (
            SELECT ps2.id
            FROM parent_students ps2
            WHERE ps2.student_name = i.student_name
            AND ps2.active = 1
            ORDER BY ps2.id DESC
            LIMIT 1
        )
    LEFT JOIN parent_profiles pp ON pp.id = ps.parent_id
    WHERE i.id = ?
    """, (invoice_id,))
    invoice = cursor.fetchone()

    if not invoice:
        conn.close()
        return redirect("/invoices")

    (
        invoice_id,
        student_name,
        charge_lessons,
        amount,
        status,
        invoice_type,
        created_at,
        due_date,
        payment_methods,
        coverage_title,
        coverage_class,
        coverage_start,
        coverage_note,
        parent_id,
        parent_name,
        parent_email,
    ) = invoice

    status = (status or "unpaid").lower()
    return_to = request.values.get("return_to") or "/invoices?edited=1"
    if not return_to.startswith("/") or return_to.startswith("//"):
        return_to = "/invoices?edited=1"

    error = ""

    def parse_money(raw, default=0):
        try:
            return round(float(str(raw or default).replace("$", "").replace(",", "").strip()), 2)
        except Exception:
            return round(float(default or 0), 2)

    def parse_lessons(raw, default=0):
        try:
            return round(float(str(raw or default).strip()), 2)
        except Exception:
            return round(float(default or 0), 2)

    if request.method == "POST":
        new_amount = parse_money(request.form.get("amount"), amount)
        new_lessons = parse_lessons(request.form.get("charge_lessons"), charge_lessons)
        new_due_date = (request.form.get("due_date") or "").strip()
        new_coverage_title = (request.form.get("coverage_title") or "").strip()
        new_coverage_class = (request.form.get("coverage_class") or "").strip()
        new_coverage_start = (request.form.get("coverage_start") or "").strip()
        new_coverage_note = (request.form.get("coverage_note") or "").strip()
        method_order = ["ach", "zelle", "paypal"]
        selected_methods = [method for method in method_order if method in request.form.getlist("payment_methods")]
        new_payment_methods = ",".join(selected_methods) or "ach,zelle,paypal"

        if new_amount < 0:
            error = "Amount cannot be negative."
        elif new_lessons < 0:
            error = "Lessons cannot be negative."
        else:
            cursor.execute("""
            UPDATE invoices
            SET charge_lessons = ?,
                amount = ?,
                due_date = ?,
                payment_methods = ?,
                coverage_title = ?,
                coverage_class = ?,
                coverage_start = ?,
                coverage_note = ?
            WHERE id = ?
            """, (
                new_lessons,
                new_amount,
                new_due_date,
                new_payment_methods,
                new_coverage_title,
                new_coverage_class,
                new_coverage_start,
                new_coverage_note,
                invoice_id,
            ))
            cursor.execute("""
            UPDATE student_ledger
            SET amount = ?
            WHERE related_invoice_id = ?
            AND related_payment_id IS NULL
            """, (new_amount, invoice_id))
            conn.commit()
            conn.close()
            return redirect(return_to)

        amount = new_amount
        charge_lessons = new_lessons
        due_date = new_due_date
        coverage_title = new_coverage_title
        coverage_class = new_coverage_class
        coverage_start = new_coverage_start
        coverage_note = new_coverage_note
        payment_methods = new_payment_methods

    conn.close()

    methods = {item.strip().lower() for item in (payment_methods or "ach,zelle,paypal").split(",") if item.strip()}

    def checked(method):
        return "checked" if method in methods else ""

    family_name = parent_name or parent_email or "No parent linked"
    parent_link = f"/parent_admin/{parent_id}" if parent_id else "/invoices"
    error_html = f"<div class='notice warn'>{escape(error)}</div>" if error else ""

    return f"""
    <html>
    <head>
        <title>Edit Invoice #{invoice_id}</title>
        <style>
            * {{ box-sizing:border-box; }}
            body {{ margin:0; font-family: Arial, sans-serif; background:#f6f7fb; color:#111827; }}
            a {{ color:#1d65ad; font-weight:900; text-decoration:none; }}
            .page {{ max-width:940px; margin:0 auto; padding:42px 24px; }}
            .shell {{ background:#fff; border:1px solid #e5e7eb; border-radius:14px; box-shadow:0 14px 35px rgba(17,24,39,.06); overflow:hidden; }}
            .head {{ padding:26px 28px 16px; border-bottom:1px solid #edf0f5; }}
            h1 {{ margin:0; font-size:32px; letter-spacing:0; }}
            .sub {{ color:#667085; margin-top:6px; font-weight:800; }}
            .summary {{ display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:10px; padding:16px 28px; background:#fbfcff; border-bottom:1px solid #edf0f5; }}
            .summary div {{ border:1px solid #e5e7eb; border-radius:10px; padding:12px 14px; background:#fff; }}
            .summary span {{ display:block; color:#667085; font-size:12px; font-weight:900; text-transform:uppercase; letter-spacing:.04em; }}
            .summary b {{ display:block; margin-top:4px; font-size:18px; }}
            form {{ padding:22px 28px 28px; }}
            .grid {{ display:grid; grid-template-columns:1fr 1fr; gap:14px; }}
            label {{ display:block; color:#667085; font-size:12px; font-weight:900; text-transform:uppercase; letter-spacing:.04em; margin-bottom:7px; }}
            input, textarea {{ width:100%; border:1px solid #d9e1ee; border-radius:10px; min-height:44px; padding:10px 12px; font:inherit; font-weight:800; background:#fff; color:#111827; }}
            textarea {{ min-height:84px; resize:vertical; }}
            .full {{ grid-column:1 / -1; }}
            .methods {{ display:flex; gap:10px; flex-wrap:wrap; }}
            .method {{ display:inline-flex; align-items:center; gap:8px; border:1px solid #d9e1ee; border-radius:999px; padding:8px 12px; font-weight:900; color:#475467; background:#fff; }}
            .method input {{ width:auto; min-height:auto; }}
            .notice {{ margin:0 28px 0; padding:12px 14px; border-radius:10px; font-weight:900; }}
            .notice.warn {{ background:#fff7ed; color:#9a3412; border:1px solid #fed7aa; }}
            .hint {{ grid-column:1 / -1; color:#667085; font-weight:800; background:#f8fafc; border:1px solid #e5e7eb; border-radius:10px; padding:11px 12px; }}
            .actions {{ display:flex; gap:10px; align-items:center; margin-top:18px; flex-wrap:wrap; }}
            button, .button {{ min-height:42px; border:1px solid #d9e1ee; border-radius:9px; padding:10px 14px; font-weight:900; background:#fff; color:#111827; cursor:pointer; }}
            button.primary {{ background:#1d65ad; border-color:#1d65ad; color:#fff; }}
            .button.ghost {{ background:#f8fafc; }}
            @media (max-width: 760px) {{
                .page {{ padding:18px 10px; }}
                .summary,.grid {{ grid-template-columns:1fr; }}
                .summary,.head,form {{ padding-left:16px; padding-right:16px; }}
                .full {{ grid-column:auto; }}
            }}
        </style>
    </head>
    <body>
        <div class="page">
            <div class="shell">
                <div class="head">
                    <h1>Edit Invoice</h1>
                    <div class="sub">Owner can edit billing details from any billing view. Parents will see the updated amount when they open the invoice.</div>
                </div>
                <div class="summary">
                    <div><span>Invoice</span><b>#{invoice_id}</b></div>
                    <div><span>Student</span><b>{escape(str(student_name or ''))}</b></div>
                    <div><span>Family</span><b><a href="{parent_link}">{escape(str(family_name))}</a></b></div>
                </div>
                {error_html}
                <form method="POST" action="/edit_invoice/{invoice_id}">
                    <input type="hidden" name="return_to" value="{escape(return_to, quote=True)}">
                    <div class="grid">
                        <div>
                            <label>Amount due</label>
                            <input name="amount" type="number" min="0" step="0.01" value="{hmusic_money(amount)}" required>
                        </div>
                        <div>
                            <label>Package / lesson count</label>
                            <input name="charge_lessons" type="number" min="0" step="0.5" value="{float(charge_lessons or 0):g}" required>
                        </div>
                        <div>
                            <label>Due date</label>
                            <input name="due_date" type="date" value="{escape(str(due_date or '')[:10], quote=True)}">
                        </div>
                        <div>
                            <label>Payment methods</label>
                            <div class="methods">
                                <label class="method"><input type="checkbox" name="payment_methods" value="ach" {checked("ach")}> ACH</label>
                                <label class="method"><input type="checkbox" name="payment_methods" value="zelle" {checked("zelle")}> Zelle</label>
                                <label class="method"><input type="checkbox" name="payment_methods" value="paypal" {checked("paypal")}> PayPal</label>
                            </div>
                        </div>
                        <div>
                            <label>Coverage title</label>
                            <input name="coverage_title" value="{escape(str(coverage_title or ''), quote=True)}" placeholder="Fall 2026 Piano Package">
                        </div>
                        <div>
                            <label>Class / package note</label>
                            <input name="coverage_class" value="{escape(str(coverage_class or ''), quote=True)}" placeholder="Private piano">
                        </div>
                        <div>
                            <label>Coverage starts</label>
                            <input name="coverage_start" type="date" value="{escape(str(coverage_start or '')[:10], quote=True)}">
                        </div>
                        <div class="hint">Changing the amount updates the parent invoice page and future reminder emails. It does not mark payment as received.</div>
                        <div class="full">
                            <label>Parent-facing coverage note</label>
                            <textarea name="coverage_note" placeholder="Optional note shown to parent">{escape(str(coverage_note or ''))}</textarea>
                        </div>
                    </div>
                    <div class="actions">
                        <button class="primary" type="submit">Save changes</button>
                        <a class="button ghost" href="/parent_invoice/{invoice_id}">Review parent view</a>
                        <a class="button" href="/invoices">Cancel</a>
                    </div>
                </form>
            </div>
        </div>
    </body>
    </html>
    """


@app.route("/send_invoice_payment_reminder/<int:invoice_id>", methods=["POST"])
def send_invoice_payment_reminder(invoice_id):
    if not require_owner():
        return redirect("/owner_login")

    ensure_v321_schema()
    ensure_v33_schema()
    ensure_student_detail_schema()
    return_to = (request.form.get("return_to") or "/invoices").strip()
    if not return_to.startswith("/") or return_to.startswith("//"):
        return_to = "/invoices"

    def reminder_redirect(state, message=""):
        if return_to == "/invoices":
            query = {"reminder": state}
            if message:
                query["message"] = message
            return redirect(f"/invoices?{urlencode(query)}")
        return redirect(return_to)

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    cursor.execute("""
    SELECT
        id,
        student_name,
        COALESCE(charge_lessons, 0),
        COALESCE(amount, 0),
        COALESCE(status, 'unpaid'),
        COALESCE(invoice_type, 'invoice'),
        COALESCE(payment_reminder_count, 0)
    FROM invoices
    WHERE id = ?
    """, (invoice_id,))
    invoice = cursor.fetchone()
    if not invoice:
        conn.close()
        return reminder_redirect("missing")

    _, student_name, charge_lessons, amount, status, invoice_type, reminder_count = invoice
    if str(status or "unpaid").lower() == "paid":
        conn.close()
        return reminder_redirect("paid")

    cursor.execute("""
    SELECT p.id, COALESCE(p.email, '')
    FROM parent_profiles p
    JOIN parent_students ps ON ps.parent_id = p.id
    WHERE ps.student_name = ?
    AND ps.active = 1
    AND p.active = 1
    ORDER BY p.id
    LIMIT 1
    """, (student_name,))
    parent = cursor.fetchone()

    if not parent:
        cursor.execute("""
        SELECT p.id, COALESCE(p.email, '')
        FROM parent_profiles p
        JOIN students s ON LOWER(COALESCE(s.parent_email, '')) = LOWER(COALESCE(p.email, ''))
        WHERE s.name = ?
        AND p.active = 1
        ORDER BY p.id
        LIMIT 1
        """, (student_name,))
        parent = cursor.fetchone()

    if not parent or not hmusic_is_real_email(parent[1]):
        conn.close()
        return reminder_redirect("no_email")

    parent_id, parent_email = parent
    now = datetime.now().strftime("%Y-%m-%d %H:%M")
    invoice_link = public_url_for(f"/parent_invoice/{invoice_id}")
    reminder_context = {
        "parent_name": "",
        "student_name": student_name,
        "invoice_id": invoice_id,
        "amount": hmusic_money(amount),
        "due_date": "",
        "lesson_count": f"{charge_lessons:g}",
        "coverage": "",
        "payment_methods": "",
        "invoice_link": invoice_link,
    }
    title = hmusic_render_message_template(
        "invoice_payment_reminder",
        "email_subject",
        reminder_context,
        f"H-Music Payment Reminder: {student_name}"
    )
    body_fallback = (
        f"Hi, this is a friendly reminder that {student_name}'s "
        f"{invoice_type or 'tuition'} invoice #{invoice_id} for ${hmusic_money(amount)} is still open.\n\n"
        f"Package: {charge_lessons:g} lesson(s)\n"
        f"Please open the H-Music parent app to review and pay when convenient:\n{invoice_link}\n\n"
        "Thank you,\nH-Music"
    )
    body = hmusic_render_message_template(
        "invoice_payment_reminder",
        "email_body",
        reminder_context,
        body_fallback
    )
    cursor.execute("""
    INSERT INTO notification_delivery_queue (
        user_role,
        user_key,
        channel,
        destination,
        title,
        body,
        link_url,
        related_type,
        related_id,
        status,
        created_at
    )
    VALUES (?, ?, 'email', ?, ?, ?, ?, 'invoice_payment_reminder', ?, 'pending', ?)
    """, (
        "parent",
        str(parent_id),
        parent_email,
        title,
        body,
        invoice_link,
        invoice_id,
        now
    ))
    queue_id = cursor.lastrowid
    conn.commit()
    conn.close()

    sent, response = send_queued_email_now(queue_id)

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    cursor.execute("""
    UPDATE invoices
    SET payment_reminder_count = ?,
        payment_reminder_sent_at = CASE WHEN ? THEN ? ELSE payment_reminder_sent_at END
    WHERE id = ?
    """, (int(reminder_count or 0) + 1, 1 if sent else 0, now, invoice_id))
    conn.commit()
    conn.close()

    create_notification(
        "parent",
        str(parent_id),
        "H-Music payment reminder",
        f"{student_name} has a tuition invoice ready for payment.",
        f"/parent_invoice/{invoice_id}",
        related_type="invoice_payment_reminder",
        related_id=invoice_id,
        queue_delivery=False
    )

    if sent:
        return reminder_redirect("sent")
    return reminder_redirect("failed", str(response or "Unknown error"))


@app.route("/teacher_lesson_notes", methods=["GET", "POST"])
def teacher_lesson_notes():
    if not require_teacher():
        return redirect("/teacher_login")

    ensure_calendar_lesson_panel_schema()
    ensure_v321_schema()
    teacher_name = session.get("teacher_name")
    selected_date = request.values.get("lesson_date") or date.today().strftime("%Y-%m-%d")

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    cursor.execute("""
    SELECT DISTINCT student_name
    FROM schedule
    WHERE teacher = ?
    AND lesson_date = ?
    ORDER BY lesson_time, student_name
    """, (teacher_name, selected_date))
    day_students = [row[0] for row in cursor.fetchall() if row[0]]

    selected_student = request.values.get("student_name") or (day_students[0] if day_students else "")

    if request.method == "POST":
        if not selected_student or selected_student not in day_students:
            conn.close()
            return "<h1>Please choose a student scheduled for this date.</h1><p><a href='/teacher_lesson_notes'>Back</a></p>"

        lesson_content = request.form.get("lesson_content") or "Lesson note"
        performance = request.form.get("performance", "")
        homework = request.form.get("homework", "")
        now = datetime.now().strftime("%Y-%m-%d %H:%M")

        cursor.execute("""
        SELECT id, enrollment_id, course_type_id, course_type_name
        FROM schedule
        WHERE teacher = ?
        AND student_name = ?
        AND lesson_date = ?
        ORDER BY lesson_time, id
        LIMIT 1
        """, (teacher_name, selected_student, selected_date))
        schedule_row = cursor.fetchone()
        schedule_id = schedule_row[0] if schedule_row else None
        schedule_enrollment_id = schedule_row[1] if schedule_row else None
        if schedule_row and not schedule_enrollment_id:
            schedule_enrollment_id = hmusic_resolve_enrollment_id(
                cursor,
                selected_student,
                course_type_id=schedule_row[2],
                teacher_name=teacher_name,
                course_type_name=schedule_row[3]
            )

        cursor.execute("""
        INSERT INTO lessons
        (
            student_name,
            lesson_content,
            performance,
            homework,
            lesson_date,
            schedule_id,
            created_by,
            created_at,
            updated_at
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        """, (
            selected_student,
            lesson_content,
            performance,
            homework,
            selected_date,
            schedule_id,
            f"teacher:{teacher_name}",
            now,
            now
        ))

        if schedule_id:
            cursor.execute("""
            UPDATE schedule
            SET notes = ?,
                homework_assignment = ?,
                enrollment_id = COALESCE(enrollment_id, ?),
                owner_calendar_updated_at = ?
            WHERE id = ?
            """, (lesson_content, homework, schedule_enrollment_id, now, schedule_id))

        if schedule_enrollment_id:
            cursor.execute("""
            UPDATE enrollments
            SET lessons_left = lessons_left - 1,
                updated_at = ?
            WHERE id = ?
            """, (now, schedule_enrollment_id))

        conn.commit()
        conn.close()
        return redirect(f"/teacher_dashboard?view=records&lesson_date={selected_date}")

    conn.close()

    student_options = "".join(
        f'<option value="{escape(student)}" {"selected" if student == selected_student else ""}>{escape(student)}</option>'
        for student in day_students
    )
    if not student_options:
        student_options = '<option value="">No students scheduled on this date</option>'

    disabled = "disabled" if not day_students else ""

    return f"""
    <html>
    <head>
        <title>Write Lesson Notes</title>
        <style>
            body {{ font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif; background:#f7f7fb; padding:32px; color:#111827; }}
            .container {{ max-width:760px; background:white; padding:28px; border-radius:14px; box-shadow:0 2px 10px rgba(0,0,0,.08); }}
            input, select, textarea {{ width:100%; box-sizing:border-box; padding:12px 14px; margin:8px 0 18px; border:1px solid #d1d5db; border-radius:10px; font-size:16px; }}
            textarea {{ min-height:170px; }}
            textarea.homework {{ min-height:260px; }}
            button, a.button {{ display:inline-block; background:#4f46e5; color:white; border:none; padding:12px 16px; border-radius:8px; font-weight:800; text-decoration:none; margin-right:8px; }}
            a.button.secondary {{ background:#111827; }}
            .inline-form {{ margin:0 0 10px; }}
        </style>
    </head>
    <body>
        <div class="container">
            <h1>Write Lesson Notes</h1>

            <form method="GET" class="inline-form">
                Date:<br>
                <input type="date" name="lesson_date" value="{selected_date}" onchange="this.form.submit()" required>
            </form>

            <form method="POST">
                <input type="hidden" name="lesson_date" value="{selected_date}">
                Student:<br>
                <select name="student_name" required {disabled}>
                    {student_options}
                </select>
                <input type="hidden" name="lesson_content" value="Lesson note">

                Performance:<br>
                <select name="performance" required {disabled}>
                    <option value="Excellent focus and progress">Excellent focus and progress</option>
                    <option value="Strong effort with steady growth">Strong effort with steady growth</option>
                    <option value="Good participation, keep practicing">Good participation, keep practicing</option>
                    <option value="Building consistency and confidence">Building consistency and confidence</option>
                </select>

                Homework:<br>
                <textarea class="homework" name="homework" placeholder="Write homework clearly for the parent and student." {disabled}></textarea>

                <button type="submit" {disabled}>Save Notes</button>
                <a class="button secondary" href="/teacher_dashboard">Back</a>
            </form>
        </div>
    </body>
    </html>
    """

@app.route("/add_lesson/<name>", methods=["GET", "POST"])
def add_lesson(name):
    if not (require_owner() or require_teacher()):
        return redirect("/owner_login")

    if require_teacher() and not require_owner():
        conn = sqlite3.connect("hmusic.db")
        cursor = conn.cursor()
        cursor.execute("""
        SELECT id
        FROM schedule
        WHERE student_name = ?
        AND teacher = ?
        LIMIT 1
        """, (name, session.get("teacher_name")))
        teaches_student = cursor.fetchone()
        conn.close()

        if not teaches_student:
            return "<h1>Permission denied</h1>"

    if request.method == "POST":
        lesson_date = request.form["lesson_date"]
        lesson_content = request.form.get("lesson_content") or "Lesson note"
        performance = request.form.get("performance", "")
        homework = request.form.get("homework", "")

        ensure_calendar_lesson_panel_schema()
        ensure_v321_schema()
        conn = sqlite3.connect("hmusic.db")
        cursor = conn.cursor()
        schedule_params = [name, lesson_date]
        schedule_teacher_filter = ""
        if require_teacher() and not require_owner():
            schedule_teacher_filter = "AND teacher = ?"
            schedule_params.append(session.get("teacher_name"))
        cursor.execute(f"""
        SELECT id, enrollment_id, course_type_id, course_type_name, teacher
        FROM schedule
        WHERE student_name = ?
        AND lesson_date = ?
        {schedule_teacher_filter}
        ORDER BY lesson_time, id
        LIMIT 1
        """, schedule_params)
        schedule_row = cursor.fetchone()
        schedule_id = schedule_row[0] if schedule_row else None
        schedule_enrollment_id = schedule_row[1] if schedule_row and len(schedule_row) > 1 else None
        if schedule_row and not schedule_enrollment_id:
            schedule_enrollment_id = hmusic_resolve_enrollment_id(
                cursor,
                name,
                course_type_id=schedule_row[2],
                teacher_name=schedule_row[4],
                course_type_name=schedule_row[3]
            )
        now = datetime.now().strftime("%Y-%m-%d %H:%M")
        actor = f"teacher:{session.get('teacher_name')}" if require_teacher() and not require_owner() else "owner"

        cursor.execute("""
        INSERT INTO lessons
        (
            student_name,
            lesson_content,
            performance,
            homework,
            lesson_date,
            schedule_id,
            created_by,
            created_at,
            updated_at
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            name,
            lesson_content,
            performance,
            homework,
            lesson_date,
            schedule_id,
            actor,
            now,
            now
        ))

        if schedule_id:
            cursor.execute("""
            UPDATE schedule
            SET notes = ?,
                homework_assignment = ?,
                enrollment_id = COALESCE(enrollment_id, ?),
                owner_calendar_updated_at = ?
            WHERE id = ?
            """, (lesson_content, homework, schedule_enrollment_id, now, schedule_id))

        if schedule_enrollment_id:
            cursor.execute("""
            UPDATE enrollments
            SET lessons_left = lessons_left - 1,
                updated_at = ?
            WHERE id = ?
            """, (now, schedule_enrollment_id))

        conn.commit()
        conn.close()

        back_href = "/teacher_dashboard" if require_teacher() and not require_owner() else f"/student/{name}"

        return f"""
        <h1>Lesson Notes Saved!</h1>
        <p>{name}</p>
        <p><a href="{back_href}">Back</a></p>
        """

    back_href = "/teacher_dashboard" if require_teacher() and not require_owner() else f"/student/{name}"

    return f"""
    <html>
    <head>
        <title>Add Lesson Notes</title>
        <style>
            body {{ font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif; background:#f7f7fb; padding:32px; color:#111827; }}
            .container {{ max-width:760px; background:white; padding:28px; border-radius:14px; box-shadow:0 2px 10px rgba(0,0,0,.08); }}
            input, select, textarea {{ width:100%; box-sizing:border-box; padding:12px 14px; margin:8px 0 18px; border:1px solid #d1d5db; border-radius:10px; font-size:16px; }}
            textarea {{ min-height:170px; }}
            textarea.homework {{ min-height:260px; }}
            button, a.button {{ display:inline-block; background:#4f46e5; color:white; border:none; padding:12px 16px; border-radius:8px; font-weight:800; text-decoration:none; margin-right:8px; }}
            a.button.secondary {{ background:#111827; }}
        </style>
    </head>
    <body>
        <div class="container">
            <h1>Add Lesson Notes - {name}</h1>

            <form method="POST">
                Date:<br>
                <input type="date" name="lesson_date" value="{date.today().strftime('%Y-%m-%d')}" required>
                <input type="hidden" name="lesson_content" value="Lesson note">

                Performance:<br>
                <select name="performance" required>
                    <option value="Excellent focus and progress">Excellent focus and progress</option>
                    <option value="Strong effort with steady growth">Strong effort with steady growth</option>
                    <option value="Good participation, keep practicing">Good participation, keep practicing</option>
                    <option value="Building consistency and confidence">Building consistency and confidence</option>
                </select>

                Homework:<br>
                <textarea class="homework" name="homework" placeholder="Write homework clearly for the parent and student."></textarea>

                <button type="submit">Save Notes</button>
                <a class="button secondary" href="{back_href}">Back</a>
            </form>
        </div>
    </body>
    </html>
    """


@app.route("/payment/<name>", methods=["GET", "POST"])
def payment(name):
    if not require_owner():
        return redirect("/owner_login")

    ensure_v321_schema()
    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    course_credits = hmusic_student_course_credits(cursor, name)
    student_url_name = quote(name)

    if not course_credits:
        conn.close()
        return f"""
        <h1>Set up course credits first</h1>
        <p>{escape(name)} does not have course-specific credit buckets yet.</p>
        <p>Create one bucket for each course, teacher, and tuition before recording payment.</p>
        <p>
            <a href="/add_enrollment?student_name={student_url_name}">Add course</a>
            · <a href="/student/{student_url_name}">Back to Student</a>
        </p>
        """

    if request.method == "POST":
        amount = float(request.form["amount"])
        lessons_added = float(request.form["lessons_added"])
        payment_method = request.form["payment_method"]
        payment_date = request.form["payment_date"]
        enrollment_id = request.form.get("enrollment_id")
        enrollment_id_int = int(enrollment_id) if enrollment_id else None
        selected_enrollment = None
        if enrollment_id_int:
            cursor.execute("""
            SELECT id, course_type_name, teacher_name
            FROM enrollments
            WHERE id = ?
            AND student_name = ?
            """, (enrollment_id_int, name))
            selected_enrollment = cursor.fetchone()
        if not selected_enrollment:
            conn.close()
            return redirect(f"/payment/{student_url_name}?error=1")

        course_type_name = selected_enrollment[1]
        teacher_name = selected_enrollment[2]
        credit_bucket_label = f"{course_type_name} / {teacher_name}"

        cursor.execute("""
        INSERT INTO payments
        (
            student_name,
            amount,
            lessons_added,
            payment_method,
            payment_date,
            enrollment_id,
            course_type_name,
            teacher_name,
            package_name,
            visible_to_parent
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            name,
            amount,
            lessons_added,
            payment_method,
            payment_date,
            enrollment_id_int,
            course_type_name,
            teacher_name,
            f"{lessons_added:g} Lesson Package" if lessons_added else "Payment",
            1
        ))

        payment_id = cursor.lastrowid

        cursor.execute("""
        INSERT INTO student_ledger (
            student_name,
            entry_type,
            amount,
            description,
            related_invoice_id,
            related_payment_id,
            created_at
        )
        VALUES (?, ?, ?, ?, ?, ?, ?)
        """, (
            name,
            "payment",
            amount,
            "Payment received",
            None,
            payment_id,
            datetime.now().strftime("%Y-%m-%d %H:%M")
        ))

        cursor.execute("""
        UPDATE enrollments
        SET lessons_left = COALESCE(lessons_left, 0) + ?,
            updated_at = ?
        WHERE id = ?
        """, (
            lessons_added,
            datetime.now().strftime("%Y-%m-%d %H:%M"),
            enrollment_id_int
        ))

        conn.commit()
        conn.close()

        return f"""
        <h1>Payment Recorded!</h1>

        <p>Student: {name}</p>
        <p>Amount: ${amount}</p>
        <p>Lessons Added: {lessons_added}</p>
        <p>Payment Method: {payment_method}</p>
        <p>Payment Date: {payment_date}</p>
        <p>Credit bucket: {escape(credit_bucket_label)}</p>

        <p><a href="/student/{name}">Back to Student</a></p>
        """

    today = date.today().strftime("%Y-%m-%d")
    selected_enrollment_id = request.args.get("enrollment_id") or (str(course_credits[0][0]) if course_credits else "")
    error_html = ""
    if request.args.get("error") == "1":
        error_html = "<p style='color:#b42318;font-weight:800;'>Choose a valid course credit before recording payment.</p>"
    enrollment_options = ""
    for row in course_credits:
        selected = "selected" if str(row[0]) == str(selected_enrollment_id) else ""
        enrollment_options += f'<option value="{row[0]}" {selected}>{escape(hmusic_course_credit_label(row))}</option>'
    conn.close()

    return f"""
    <h1>Receive Payment - {name}</h1>
    {error_html}

    <form method="POST">
        Credit course / teacher:<br>
        <select name="enrollment_id">
            {enrollment_options}
        </select><br><br>

        Amount:<br>
        <input name="amount"><br><br>

        Lessons Added:<br>
        <input name="lessons_added"><br><br>

        Payment Method:<br>
        <input name="payment_method"><br><br>

        Payment Date:<br>
        <input type="date" name="payment_date" value="{today}"><br><br>

        <button type="submit">Save Payment</button>
    </form>

    <p><a href="/student/{name}">Back to Student</a></p>
    """


@app.route("/edit_payment/<int:payment_id>", methods=["GET", "POST"])
def edit_payment(payment_id):
    if not require_owner():
        return redirect("/owner_login")

    ensure_v321_schema()
    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    cursor.execute("""
    SELECT student_name, amount, lessons_added, payment_method, payment_date, enrollment_id
    FROM payments
    WHERE id = ?
    """, (payment_id,))
    payment_row = cursor.fetchone()

    if not payment_row:
        conn.close()
        return redirect("/students")

    student_name, old_amount, old_lessons_added, old_method, old_date, enrollment_id = payment_row
    student_url_name = quote(str(student_name or ""), safe="")

    if request.method == "GET":
        conn.close()
        return f"""
        <html>
        <head>
            <title>Edit Payment #{payment_id}</title>
            <style>
                body {{ font-family:Arial,sans-serif; background:#f7f7fb; padding:40px; color:#111827; }}
                .container {{ max-width:680px; background:#fff; padding:28px; border-radius:12px; box-shadow:0 2px 10px rgba(0,0,0,.08); }}
                label {{ display:block; font-weight:800; margin:14px 0 6px; color:#374151; }}
                input {{ width:100%; min-height:42px; border:1px solid #d1d5db; border-radius:8px; padding:0 10px; font-size:16px; box-sizing:border-box; }}
                .actions {{ display:flex; gap:10px; flex-wrap:wrap; margin-top:20px; }}
                button, a.button {{ min-height:42px; display:inline-flex; align-items:center; justify-content:center; border:1px solid #d1d5db; border-radius:8px; padding:0 14px; background:#fff; color:#111827; text-decoration:none; font-weight:800; cursor:pointer; }}
                button.primary {{ background:#1f6fb8; color:#fff; border-color:#1f6fb8; }}
                .muted {{ color:#667085; font-weight:700; }}
            </style>
        </head>
        <body>
            <div class="container">
                <h1>Edit Payment #{payment_id}</h1>
                <p class="muted">{escape(str(student_name or ''))}</p>
                <form method="POST">
                    <input type="hidden" name="return_to" value="/student_ledger/{student_url_name}">
                    <label>Date</label>
                    <input type="date" name="payment_date" value="{escape(str(old_date or ''), quote=True)}">
                    <label>Amount</label>
                    <input type="number" step="0.01" name="amount" value="{escape(str(old_amount or 0), quote=True)}">
                    <label>Lessons added</label>
                    <input type="number" step="1" name="lessons_added" value="{escape(str(old_lessons_added or 0), quote=True)}">
                    <label>Method</label>
                    <input name="payment_method" value="{escape(str(old_method or 'Payment'), quote=True)}">
                    <div class="actions">
                        <button class="primary" type="submit">Save payment</button>
                        <a class="button" href="/student_ledger/{student_url_name}">Back to ledger</a>
                        <a class="button" href="/student/{student_url_name}#billing">Student billing</a>
                    </div>
                </form>
            </div>
        </body>
        </html>
        """

    def numeric_value(raw, default=0):
        try:
            return float(raw if raw not in (None, "") else default)
        except (TypeError, ValueError):
            return float(default or 0)

    new_amount = round(numeric_value(request.form.get("amount"), old_amount), 2)
    new_lessons_added = int(numeric_value(request.form.get("lessons_added"), old_lessons_added))
    new_method = (request.form.get("payment_method") or old_method or "Payment").strip()
    new_date = request.form.get("payment_date") or old_date or date.today().strftime("%Y-%m-%d")
    old_lessons_added = int(numeric_value(old_lessons_added, 0))
    lesson_delta = new_lessons_added - old_lessons_added

    cursor.execute("""
    UPDATE payments
    SET amount = ?,
        lessons_added = ?,
        payment_method = ?,
        payment_date = ?
    WHERE id = ?
    """, (new_amount, new_lessons_added, new_method, new_date, payment_id))

    if lesson_delta and enrollment_id:
        cursor.execute("""
        UPDATE enrollments
        SET lessons_left = MAX(COALESCE(lessons_left, 0) + ?, 0),
            updated_at = ?
        WHERE id = ?
        """, (
            lesson_delta,
            datetime.now().strftime("%Y-%m-%d %H:%M"),
            enrollment_id
        ))

    cursor.execute("""
    UPDATE student_ledger
    SET amount = ?,
        description = ?,
        created_at = ?
    WHERE related_payment_id = ?
    """, (
        new_amount,
        f"Payment received · {new_method}",
        datetime.now().strftime("%Y-%m-%d %H:%M"),
        payment_id
    ))

    conn.commit()
    conn.close()
    return_to = request.form.get("return_to")
    if return_to and return_to.startswith("/") and not return_to.startswith("//"):
        return redirect(return_to)
    return redirect(f"/student/{quote(student_name)}#payments")


