@app.route("/delete_payment/<int:payment_id>", methods=["POST"])
def delete_payment(payment_id):
    if not require_owner():
        return redirect("/owner_login")

    ensure_v321_schema()
    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    cursor.execute("""
    SELECT student_name, COALESCE(lessons_added, 0), enrollment_id
    FROM payments
    WHERE id = ?
    """, (payment_id,))
    payment_row = cursor.fetchone()

    if not payment_row:
        conn.close()
        return redirect("/students")

    student_name, lessons_added, enrollment_id = payment_row

    cursor.execute("""
    SELECT related_invoice_id
    FROM student_ledger
    WHERE related_payment_id = ?
    AND related_invoice_id IS NOT NULL
    """, (payment_id,))
    invoice_ids = [row[0] for row in cursor.fetchall()]

    if enrollment_id:
        cursor.execute("""
        UPDATE enrollments
        SET lessons_left = MAX(COALESCE(lessons_left, 0) - ?, 0),
            updated_at = ?
        WHERE id = ?
        """, (
            float(lessons_added or 0),
            datetime.now().strftime("%Y-%m-%d %H:%M"),
            enrollment_id
        ))

    cursor.execute("DELETE FROM student_ledger WHERE related_payment_id = ?", (payment_id,))
    cursor.execute("DELETE FROM payments WHERE id = ?", (payment_id,))

    for invoice_id in invoice_ids:
        cursor.execute("UPDATE invoices SET status = 'unpaid' WHERE id = ?", (invoice_id,))

    conn.commit()
    conn.close()
    return redirect(f"/student/{quote(student_name)}#payments")


@app.route("/generate_parent_email/<name>")
def generate_parent_email(name):
    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()

    cursor.execute("""
    SELECT lesson_date, lesson_content, performance, homework
    FROM lessons
    WHERE student_name = ?
    ORDER BY id DESC
    LIMIT 1
    """, (name,))

    lesson = cursor.fetchone()
    conn.close()

    if not lesson:
        return f"""
        <h1>No lesson found for {name}</h1>
        <p><a href="/student/{name}">Back to Student</a></p>
        """

    visible_lesson_content = hmusic_parent_visible_lesson_note(lesson[1]) or "the lesson material"

    prompt = f"""
You are a professional piano teacher.

Write a warm, professional parent update email based on this lesson.

Student: {name}
Date: {lesson[0]}
Lesson Content: {visible_lesson_content}
Performance: {lesson[2]}
Homework: {lesson[3]}

Requirements:
- Warm and encouraging
- Clear and concise
- Mention what the student worked on
- Mention performance
- Mention homework
- End with H-Music
"""

    response = client.chat.completions.create(
        model="gpt-4o-mini",
        messages=[
            {
                "role": "user",
                "content": prompt
            }
        ]
    )

    email_text = response.choices[0].message.content

    return f"""
    <h1>Parent Email - {name}</h1>

    <pre>{email_text}</pre>

    <p><a href="/student/{name}">Back to Student</a></p>
    """


@app.route("/send_parent_email/<name>")
def send_parent_email(name):
    conn = sqlite3.connect("hmusic.db")
