@app.route("/locations_rooms", methods=["GET", "POST"])
def locations_rooms():
    if not require_owner():
        return redirect("/owner_login")

    ensure_location_room_schema()

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    message = ""
    now = datetime.now().strftime("%Y-%m-%d %H:%M")

    if request.method == "POST":
        action = request.form.get("action")
        if action == "add_location":
            location_name = (request.form.get("location_name") or "").strip()
            address = (request.form.get("address") or "").strip()
            notes = (request.form.get("notes") or "").strip()
            if location_name:
                cursor.execute("""
                INSERT OR IGNORE INTO studio_locations (
                    location_name, address, notes, active, sort_order, created_at, updated_at
                )
                VALUES (?, ?, ?, 1, ?, ?, ?)
                """, (location_name, address, notes, int(request.form.get("sort_order") or 0), now, now))
                message = "Location saved."
        elif action == "update_location":
            location_id = request.form.get("location_id")
            location_name = (request.form.get("location_name") or "").strip()
            address = (request.form.get("address") or "").strip()
            notes = (request.form.get("notes") or "").strip()
            active = 1 if request.form.get("active") == "1" else 0
            if location_id and location_name:
                cursor.execute("""
                UPDATE studio_locations
                SET location_name = ?, address = ?, notes = ?, active = ?, sort_order = ?, updated_at = ?
                WHERE id = ?
                """, (location_name, address, notes, active, int(request.form.get("sort_order") or 0), now, location_id))
                message = "Location updated."
        elif action == "add_room":
            location_id = request.form.get("location_id")
            room_name = (request.form.get("room_name") or "").strip()
            notes = (request.form.get("notes") or "").strip()
            if location_id and room_name:
                cursor.execute("""
                INSERT OR IGNORE INTO studio_rooms (
                    location_id, room_name, notes, active, sort_order, created_at, updated_at
                )
                VALUES (?, ?, ?, 1, ?, ?, ?)
                """, (location_id, room_name, notes, int(request.form.get("sort_order") or 0), now, now))
                cursor.execute("INSERT OR IGNORE INTO classrooms (room_name) VALUES (?)", (room_name,))
                message = "Room saved."
        elif action == "update_room":
            room_id = request.form.get("room_id")
            location_id = request.form.get("location_id")
            room_name = (request.form.get("room_name") or "").strip()
            notes = (request.form.get("notes") or "").strip()
            active = 1 if request.form.get("active") == "1" else 0
            if room_id and location_id and room_name:
                cursor.execute("""
                UPDATE studio_rooms
                SET location_id = ?, room_name = ?, notes = ?, active = ?, sort_order = ?, updated_at = ?
                WHERE id = ?
                """, (location_id, room_name, notes, active, int(request.form.get("sort_order") or 0), now, room_id))
                cursor.execute("INSERT OR IGNORE INTO classrooms (room_name) VALUES (?)", (room_name,))
                message = "Room updated."
        conn.commit()

    cursor.execute("""
    SELECT id, location_name, COALESCE(address, ''), COALESCE(notes, ''), active, COALESCE(sort_order, 0)
    FROM studio_locations
    ORDER BY active DESC, sort_order, location_name
    """)
    locations = cursor.fetchall()

    cursor.execute("""
    SELECT
        r.id,
        r.location_id,
        r.room_name,
        COALESCE(r.notes, ''),
        r.active,
        COALESCE(r.sort_order, 0),
        l.location_name
    FROM studio_rooms r
    LEFT JOIN studio_locations l ON l.id = r.location_id
    ORDER BY COALESCE(l.active, 0) DESC, l.sort_order, l.location_name, r.active DESC, r.sort_order, r.room_name
    """)
    rooms = cursor.fetchall()
    conn.close()

    location_options = "".join([
        f'<option value="{l[0]}">{escape(l[1])}</option>'
        for l in locations
    ])

    location_rows = ""
    for l in locations:
        checked = "checked" if l[4] == 1 else ""
        status = "Active" if l[4] == 1 else "Inactive"
        location_rows += f"""
        <form method="POST" class="row-form">
            <input type="hidden" name="action" value="update_location">
            <input type="hidden" name="location_id" value="{l[0]}">
            <div class="field name"><label>Location</label><input name="location_name" value="{escape(l[1])}" required></div>
            <div class="field"><label>Address</label><input name="address" value="{escape(l[2])}" placeholder="Full address or online link"></div>
            <div class="field"><label>Notes</label><input name="notes" value="{escape(l[3])}" placeholder="Parking, gate code, etc."></div>
            <div class="field small"><label>Sort</label><input name="sort_order" type="number" value="{l[5]}"></div>
            <label class="check"><input type="checkbox" name="active" value="1" {checked}> {status}</label>
            <button type="submit">Save</button>
        </form>
        """

    room_rows = ""
    for r in rooms:
        checked = "checked" if r[4] == 1 else ""
        status = "Active" if r[4] == 1 else "Inactive"
        room_location_options = "".join([
            f'<option value="{l[0]}" {"selected" if l[0] == r[1] else ""}>{escape(l[1])}</option>'
            for l in locations
        ])
        room_rows += f"""
        <form method="POST" class="row-form">
            <input type="hidden" name="action" value="update_room">
            <input type="hidden" name="room_id" value="{r[0]}">
            <div class="field"><label>Location</label><select name="location_id">{room_location_options}</select></div>
            <div class="field name"><label>Room</label><input name="room_name" value="{escape(r[2])}" required></div>
            <div class="field"><label>Notes</label><input name="notes" value="{escape(r[3])}" placeholder="Piano, capacity, online, etc."></div>
            <div class="field small"><label>Sort</label><input name="sort_order" type="number" value="{r[5]}"></div>
            <label class="check"><input type="checkbox" name="active" value="1" {checked}> {status}</label>
            <button type="submit">Save</button>
        </form>
        """

    return f"""
    <html>
    <head>
        <title>Locations & Rooms</title>
        <style>
            body {{ font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif; background:#f7f7fb; color:#111827; padding:32px; }}
            .shell {{ max-width:1180px; margin:0 auto; }}
            .top {{ display:flex; align-items:center; justify-content:space-between; gap:16px; margin-bottom:18px; }}
            h1 {{ margin:0; font-size:30px; }}
            h2 {{ margin:0 0 14px; font-size:20px; }}
            .muted {{ color:#6b7280; margin:6px 0 0; }}
            .nav a, button, .button {{ display:inline-block; border:none; border-radius:10px; padding:10px 14px; font-weight:800; text-decoration:none; background:#2563eb; color:white; cursor:pointer; }}
            .nav a.secondary, .button.secondary {{ background:white; color:#111827; border:1px solid #d7dce5; }}
            .grid {{ display:grid; grid-template-columns:1fr; gap:18px; }}
            .card {{ background:white; border:1px solid #e5e7eb; border-radius:14px; padding:20px; box-shadow:0 8px 24px rgba(15,23,42,.05); }}
            .row-form {{ display:grid; grid-template-columns:1.1fr 1.5fr 1.3fr 80px 110px 90px; gap:12px; align-items:end; padding:12px 0; border-top:1px solid #edf0f5; }}
            .row-form:first-of-type {{ border-top:none; }}
            label {{ display:block; font-size:12px; font-weight:800; color:#6b7280; text-transform:uppercase; letter-spacing:.02em; margin-bottom:6px; }}
            input, select {{ width:100%; box-sizing:border-box; border:1px solid #d1d5db; border-radius:10px; padding:10px 12px; font-size:14px; background:white; }}
            .field.small input {{ text-align:center; }}
            .check {{ display:flex; align-items:center; gap:8px; margin-bottom:10px; color:#374151; text-transform:none; letter-spacing:0; font-size:14px; }}
            .check input {{ width:auto; }}
            .add-form {{ display:grid; grid-template-columns:1fr 1.4fr 1.2fr 80px 100px; gap:12px; align-items:end; padding:14px; background:#f8fafc; border:1px solid #e5e7eb; border-radius:12px; margin-bottom:12px; }}
            .notice {{ background:#ecfdf5; color:#166534; border:1px solid #bbf7d0; padding:12px 14px; border-radius:12px; margin-bottom:14px; font-weight:800; }}
            .hint {{ background:#eff6ff; color:#1d4ed8; border:1px solid #bfdbfe; padding:12px 14px; border-radius:12px; margin-bottom:18px; }}
            @media (max-width:900px) {{
                body {{ padding:18px; }}
                .top, .row-form, .add-form {{ display:block; }}
                .field, .check, button {{ margin-top:10px; }}
                .nav {{ margin-top:12px; }}
            }}
        </style>
    </head>
    <body>
        <div class="shell">
            <div class="top">
                <div>
                    <h1>Locations & Rooms</h1>
                    <p class="muted">Manage teaching addresses and the rooms available under each location.</p>
                </div>
                <div class="nav">
                    <a class="secondary" href="/calendar">Calendar</a>
                    <a class="secondary" href="/room_schedule">Room Schedule</a>
                    <a href="/add_schedule">Add Schedule</a>
                </div>
            </div>
            {f'<div class="notice">{escape(message)}</div>' if message else ''}
            <div class="hint">Use Active/Inactive instead of deleting locations or rooms, so old lesson records remain readable.</div>

            <div class="grid">
                <section class="card">
                    <h2>Locations</h2>
                    <form method="POST" class="add-form">
                        <input type="hidden" name="action" value="add_location">
                        <div class="field"><label>Location</label><input name="location_name" placeholder="H-Music Cupertino" required></div>
                        <div class="field"><label>Address</label><input name="address" placeholder="123 Main St, Cupertino, CA"></div>
                        <div class="field"><label>Notes</label><input name="notes" placeholder="Parking, entry, online link"></div>
                        <div class="field small"><label>Sort</label><input name="sort_order" type="number" value="0"></div>
                        <button type="submit">Add</button>
                    </form>
                    {location_rows or '<p class="muted">No locations yet.</p>'}
                </section>

                <section class="card">
                    <h2>Rooms</h2>
                    <form method="POST" class="add-form">
                        <input type="hidden" name="action" value="add_room">
                        <div class="field"><label>Location</label><select name="location_id">{location_options}</select></div>
                        <div class="field"><label>Room</label><input name="room_name" placeholder="Room 1 / Piano Room / Online" required></div>
                        <div class="field"><label>Notes</label><input name="notes" placeholder="Piano, capacity, camera setup"></div>
                        <div class="field small"><label>Sort</label><input name="sort_order" type="number" value="0"></div>
                        <button type="submit">Add</button>
                    </form>
                    {room_rows or '<p class="muted">No rooms yet.</p>'}
                </section>
            </div>
        </div>
    </body>
    </html>
    """


@app.route("/room_availability", methods=["GET", "POST"])
def room_availability():
    ensure_calendar_lesson_panel_schema()
    is_owner = require_owner()
    is_teacher = require_teacher() and not is_owner
    if not (is_owner or is_teacher):
        return redirect("/owner_login")
    if is_teacher and not teacher_has_permission(session.get("teacher_name"), "view_room_availability"):
        content = """
        <section class="td-card">
            <h2>Room Availability Requires Owner Permission</h2>
            <p class="muted">The owner can enable this from Teacher Permissions.</p>
        </section>
        """
        return hstudio_teacher_dark_shell(
            session.get("teacher_name") or "Teacher",
            get_unread_message_count("teacher", session.get("teacher_name")),
            content,
            active="room_availability",
            missing_homework_count=get_missing_homework_count(session.get("teacher_name"))
        )

    selected_date = request.values.get("selected_date") or date.today().strftime("%Y-%m-%d")
    selected_location = (request.values.get("location_id") or "").strip()
    selected_start = (request.values.get("start_time") or "15:45").strip()
    selected_duration_raw = request.values.get("duration") or "45"
    try:
        datetime.strptime(selected_date, "%Y-%m-%d")
    except Exception:
        selected_date = date.today().strftime("%Y-%m-%d")
    try:
        selected_duration = max(5, min(240, int(float(selected_duration_raw))))
    except Exception:
        selected_duration = 45

    day_start = 9 * 60
    day_end = 21 * 60
    selected_start_minutes = minutes_from_time_text(selected_start)
    if selected_start_minutes is None:
        selected_start = "15:45"
        selected_start_minutes = 15 * 60 + 45
    selected_end_minutes = selected_start_minutes + selected_duration

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()

    cursor.execute("""
    SELECT id, location_name
    FROM studio_locations
    WHERE COALESCE(active, 1) = 1
    ORDER BY COALESCE(sort_order, 0), location_name
    """)
    locations = cursor.fetchall()

    room_params = []
    location_filter = ""
    if selected_location:
        location_filter = "AND r.location_id = ?"
        room_params.append(selected_location)
    cursor.execute(f"""
    SELECT r.id, r.location_id, r.room_name, COALESCE(l.location_name, '')
    FROM studio_rooms r
    LEFT JOIN studio_locations l ON l.id = r.location_id
    WHERE COALESCE(r.active, 1) = 1
    AND COALESCE(l.active, 1) = 1
    {location_filter}
    ORDER BY COALESCE(l.sort_order, 0), COALESCE(r.sort_order, 0), r.room_name
    """, room_params)
    rooms = cursor.fetchall()

    cursor.execute("""
    SELECT id, lesson_time, COALESCE(duration, 30), COALESCE(status, 'scheduled'),
           COALESCE(room_id, 0), COALESCE(classroom, ''), COALESCE(location_id, 0)
    FROM schedule
    WHERE lesson_date = ?
    ORDER BY lesson_time
    """, (selected_date,))
    lesson_rows = cursor.fetchall()

    conn.close()

    location_options = '<option value="">All locations</option>'
    for location_id, location_name in locations:
        location_options += f'<option value="{location_id}" {"selected" if str(location_id) == selected_location else ""}>{escape(location_name or "Location")}</option>'

    if not rooms:
        empty_content = f"""
        <div class="room-avail-empty">
            <h2>No active rooms found</h2>
            <p>Add active locations and rooms before using Room Availability.</p>
        </div>
        """
        if is_teacher:
            return hstudio_teacher_dark_shell(
                session.get("teacher_name") or "Teacher",
                get_unread_message_count("teacher", session.get("teacher_name")),
                empty_content,
                active="room_availability",
                missing_homework_count=get_missing_homework_count(session.get("teacher_name"))
            )
        return f"<html><body>{empty_content}<p><a href='/locations_rooms'>Locations & Rooms</a> <a href='/calendar'>Calendar</a></p></body></html>"

    room_count = len(rooms)
    room_headers = "".join(f'<div class="ra-room-head">{escape(room[2] or "Room")}</div>' for room in rooms)

    def room_lesson_matches(room, lesson):
        room_id, location_id, room_name = room[0], room[1], room[2] or ""
        lesson_room_id = int(lesson[4] or 0)
        lesson_location_id = int(lesson[6] or 0)
        if lesson_room_id:
            return lesson_room_id == int(room_id)
        if lesson_location_id and int(location_id or 0) != lesson_location_id:
            return False
        return (lesson[5] or "").strip().lower() == room_name.strip().lower()

    def lesson_blocks_for_room(room):
        blocks = []
        for lesson in lesson_rows:
            status = str(lesson[3] or "scheduled").strip().lower()
            if status.startswith("cancel") or status in ("excused_24h", "excused", "teacher_cancelled"):
                continue
            start = minutes_from_time_text(lesson[1])
            if start is None:
                continue
            try:
                duration = int(float(lesson[2] or 30))
            except Exception:
                duration = 30
            end = start + max(5, duration)
            if end <= day_start or start >= day_end:
                continue
            if room_lesson_matches(room, lesson):
                blocks.append({
                    "start": max(day_start, start),
                    "end": min(day_end, end),
                })
        return blocks

    room_blocks = {room[0]: lesson_blocks_for_room(room) for room in rooms}

    def block_count(room_id, start, end):
        return len([
            block for block in room_blocks.get(room_id, [])
            if max(start, block["start"]) < min(end, block["end"])
        ])

    def block_status(room_id, start, end):
        count = block_count(room_id, start, end)
        if count == 0:
            return "available"
        if count == 1:
            return "booked"
        return "conflict"

    def block_label(status):
        if status == "available":
            return "Available"
        if status == "conflict":
            return "Conflict"
        if status == "closed":
            return "Closed"
        return "Booked"

    def top_for_minute(minute):
        return max(0, min(100, ((minute - day_start) / (day_end - day_start)) * 100))

    def room_timeline_html(room):
        intervals = []
        boundaries = {day_start, day_end, selected_start_minutes, selected_end_minutes}
        for block in room_blocks.get(room[0], []):
            boundaries.add(block["start"])
            boundaries.add(block["end"])
        points = sorted(min(max(day_start, point), day_end) for point in boundaries if day_start <= point <= day_end)
        for idx in range(len(points) - 1):
            start = points[idx]
            end = points[idx + 1]
            if end <= start:
                continue
            status = block_status(room[0], start, end)
            top = top_for_minute(start)
            height = max(2.2, top_for_minute(end) - top)
            intervals.append(f"""
            <div class="ra-block {status}" style="top:{top:.3f}%;height:{height:.3f}%">
                <span>{block_label(status)}</span>
                <small>{format_display_time(time_text_from_minutes(start))}-{format_display_time(time_text_from_minutes(end))}</small>
            </div>
            """)
        selection_top = top_for_minute(selected_start_minutes)
        selection_height = max(2.2, top_for_minute(selected_end_minutes) - selection_top)
        return f"""
        <div class="ra-room-col">
            <div class="ra-selection" style="top:{selection_top:.3f}%;height:{selection_height:.3f}%"></div>
            {"".join(intervals)}
        </div>
        """

    room_columns = "".join(room_timeline_html(room) for room in rooms)
    hour_marks = "".join(
        f'<div class="ra-time-mark">{format_display_time(time_text_from_minutes(hour * 60)).replace(":00", "")}</div>'
        for hour in range(day_start // 60, day_end // 60)
    )
    selected_rows = ""
    available_count = 0
    for room in rooms:
        status = block_status(room[0], selected_start_minutes, selected_end_minutes)
        if status == "available":
            available_count += 1
        selected_rows += f"""
        <div class="ra-fit-row">
            <div class="ra-fit-room">{escape(room[2] or "Room")}</div>
            <div>
                <div>{format_lesson_time_range(selected_start, selected_duration)}</div>
                <small>{'Clear for full duration' if status == 'available' else 'Overlaps booking(s)' if status == 'booked' else 'Overlaps multiple bookings'}</small>
            </div>
            <span class="ra-fit-status {status}">{block_label(status)}</span>
        </div>
        """

    back_href = "/teacher_dashboard?view=schedule" if is_teacher else "/calendar"
    add_href = (
        f"/teacher_dashboard?view=schedule&open_add=1&prefill_date={quote(selected_date)}"
        if is_teacher else
        f"/add_schedule?{urlencode({'start_date': selected_date, 'return_to': '/room_availability'})}"
    )
    shell_class = " teacher-mode" if is_teacher else ""
    page_html = f"""
    <style>
        .room-avail{{color:#17202a}}
        .room-avail *{{box-sizing:border-box}}
        .room-avail-shell{{background:#fff;border:1px solid #e3e7ee;border-radius:10px;overflow:hidden;box-shadow:0 10px 24px rgba(15,23,42,.06)}}
        .room-avail-top{{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 14px;border-bottom:1px solid #e3e7ee;background:#fff}}
        .room-avail-title h1{{margin:0 0 3px;font-size:22px;font-weight:600}}
        .room-avail-title p{{margin:0;color:#667085;font-size:13px}}
        .room-avail-actions,.room-avail-filters,.ra-legend{{display:flex;align-items:center;gap:7px;flex-wrap:wrap}}
        .ra-btn,.room-avail-filters input,.room-avail-filters select{{height:30px;border:1px solid #d6dce6;border-radius:8px;background:#fff;color:#354052;padding:0 10px;font:inherit;font-size:12px;font-weight:650;text-decoration:none}}
        .ra-btn.primary{{background:#2563eb;border-color:#2563eb;color:#fff}}
        .room-avail-toolbar{{display:flex;justify-content:space-between;gap:10px;padding:9px 14px;background:#fbfcfd;border-bottom:1px solid #e3e7ee}}
        .ra-legend span{{height:26px;display:inline-flex;align-items:center;gap:6px;border:1px solid #d6dce6;border-radius:8px;background:#fff;padding:0 8px;color:#475467;font-size:11px;font-weight:750}}
        .ra-dot{{width:9px;height:9px;border-radius:999px;display:inline-block}}
        .ra-dot.available{{background:#16803c}}.ra-dot.booked{{background:#818b9b}}.ra-dot.conflict{{background:#b42318}}.ra-dot.closed{{background:#c7ced8}}
        .room-avail-layout{{display:grid;grid-template-columns:minmax(0,1fr) 292px;min-height:650px}}
        .ra-timeline-wrap{{overflow:auto;border-right:1px solid #e3e7ee;background:#fff}}
        .ra-timeline{{min-width:{max(760, 66 + room_count * 158)}px;display:grid;grid-template-columns:66px repeat({room_count},minmax(150px,1fr));position:relative}}
        .ra-time-head,.ra-room-head{{height:42px;position:sticky;top:0;z-index:4;background:#fff;border-bottom:1px solid #e5e9f0;border-right:1px solid #e5e9f0;padding:8px;font-size:12px;font-weight:850}}
        .ra-time-head{{left:0;z-index:5}}
        .ra-time-col{{position:sticky;left:0;z-index:2;background:#fbfcfd;border-right:1px solid #e5e9f0}}
        .ra-time-mark{{height:52px;border-bottom:1px solid #edf0f5;padding:6px 7px 0 0;text-align:right;color:#697487;font-size:11px;font-weight:750}}
        .ra-room-col{{position:relative;height:624px;border-right:1px solid #e5e9f0;background:linear-gradient(#edf0f5 1px,transparent 1px) 0 0/100% 52px,linear-gradient(#f4f6f9 1px,transparent 1px) 0 26px/100% 52px,#fff}}
        .ra-block{{position:absolute;left:7px;right:7px;border-radius:5px;border:1px solid transparent;padding:4px 7px;display:flex;flex-direction:column;justify-content:center;overflow:hidden;font-size:11px;line-height:1.14;font-weight:850;z-index:2}}
        .ra-block span,.ra-block small{{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}}
        .ra-block small{{margin-top:2px;font-size:10px;font-weight:750;opacity:.82}}
        .ra-block.available{{background:#e9f8ef;border-color:#bee8cb;color:#16803c}}
        .ra-block.booked{{background:#eef1f5;border-color:#d3dae4;color:#465163}}
        .ra-block.conflict{{background:#fff0ef;border-color:#f4aaa3;color:#b42318}}
        .ra-selection{{position:absolute;left:5px;right:5px;border:2px solid #2563eb;background:rgba(37,99,235,.08);border-radius:6px;z-index:1;pointer-events:none}}
        .ra-side{{background:#fbfcfd;padding:14px}}
        .ra-panel{{background:#fff;border:1px solid #e1e6ee;border-radius:8px;overflow:hidden;margin-bottom:12px}}
        .ra-panel-head{{padding:11px 12px;border-bottom:1px solid #e8ecf2}}
        .ra-panel-head strong{{display:block;font-size:13px}}.ra-panel-head span{{display:block;margin-top:3px;color:#667085;font-size:11px}}
        .ra-fit-row{{display:grid;grid-template-columns:46px minmax(0,1fr) auto;gap:8px;align-items:center;padding:9px 12px;border-bottom:1px solid #eef1f5;font-size:12px}}
        .ra-fit-row:last-child{{border-bottom:0}}.ra-fit-room{{font-weight:850}}.ra-fit-row small{{display:block;color:#667085;font-size:11px;margin-top:2px}}
        .ra-fit-status{{border-radius:999px;padding:3px 7px;font-size:10px;font-weight:850;text-transform:uppercase;white-space:nowrap}}
        .ra-fit-status.available{{background:#e9f8ef;color:#16803c}}.ra-fit-status.booked{{background:#eef1f5;color:#536173}}.ra-fit-status.conflict{{background:#fff0ef;color:#b42318}}
        .ra-note{{padding:10px 12px;color:#344054;font-size:12px;line-height:1.45}}.ra-note b{{color:#111827}}
        .room-avail-empty{{background:#fff;border:1px solid #e3e7ee;border-radius:10px;padding:22px}}
        @media(max-width:900px){{.room-avail-top,.room-avail-toolbar{{align-items:flex-start;flex-direction:column}}.room-avail-layout{{grid-template-columns:1fr}}.ra-timeline-wrap{{border-right:0}}}}
    </style>
    <div class="room-avail{shell_class}">
        <div class="room-avail-shell">
            <div class="room-avail-top">
                <div class="room-avail-title">
                    <h1>Room Availability</h1>
                    <p>Status-only room calendar. No student, teacher, or course details are shown.</p>
                </div>
                <div class="room-avail-actions">
                    <a class="ra-btn" href="{back_href}">Back</a>
                    <a class="ra-btn primary" href="{add_href}">Add Schedule</a>
                </div>
            </div>
            <form class="room-avail-toolbar" method="GET" action="/room_availability">
                <div class="room-avail-filters">
                    <input type="date" name="selected_date" value="{escape(selected_date)}" onchange="this.form.submit()">
                    <select name="location_id" onchange="this.form.submit()">{location_options}</select>
                    <input type="time" name="start_time" value="{escape(time_text_from_minutes(selected_start_minutes))}" onchange="this.form.submit()">
                    <select name="duration" onchange="this.form.submit()">
                        {''.join(f'<option value="{minutes}" {"selected" if minutes == selected_duration else ""}>{minutes} min</option>' for minutes in (15, 30, 45, 60, 75, 90))}
                    </select>
                    <button class="ra-btn" type="submit">View</button>
                </div>
                <div class="ra-legend">
                    <span><i class="ra-dot available"></i>Available</span>
                    <span><i class="ra-dot booked"></i>Booked</span>
                    <span><i class="ra-dot conflict"></i>Conflict</span>
                </div>
            </form>
            <div class="room-avail-layout">
                <div class="ra-timeline-wrap">
                    <div class="ra-timeline">
                        <div class="ra-time-head"></div>
                        {room_headers}
                        <div class="ra-time-col">{hour_marks}</div>
                        {room_columns}
                    </div>
                </div>
                <aside class="ra-side">
                    <section class="ra-panel">
                        <div class="ra-panel-head">
                            <strong>Selected Window</strong>
                            <span>{format_lesson_time_range(selected_start, selected_duration)} · {available_count}/{room_count} available</span>
                        </div>
                        {selected_rows}
                    </section>
                    <section class="ra-panel">
                        <div class="ra-panel-head">
                            <strong>Logic</strong>
                            <span>exact-minute overlap check</span>
                        </div>
                        <div class="ra-note">
                            <b>Available</b> means zero active lessons overlap the selected room and time range. <b>Conflict</b> means two or more active lessons overlap the same room.
                        </div>
                    </section>
                </aside>
            </div>
        </div>
    </div>
    """

    if is_teacher:
        return hstudio_teacher_dark_shell(
            session.get("teacher_name") or "Teacher",
            get_unread_message_count("teacher", session.get("teacher_name")),
            page_html,
            active="room_availability",
            missing_homework_count=get_missing_homework_count(session.get("teacher_name"))
        )

    return f"""
    <html>
    <head>
        <title>Room Availability</title>
        <meta name="viewport" content="width=device-width, initial-scale=1">
    </head>
    <body style="margin:0;background:#f6f7f9;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;padding:20px">
        {page_html}
    </body>
    </html>
    """

@app.route("/teacher_dashboard")
def teacher_dashboard():

    if session.get("user_role") != "teacher":
        return redirect("/teacher_login")

    ensure_v321_schema()
    ensure_calendar_lesson_panel_schema()
    ensure_teacher_permission_schema()
    ensure_location_room_schema()

    teacher_name = session.get("teacher_name")
    teacher_perms = get_teacher_permissions(teacher_name)
    unread_messages = get_unread_message_count("teacher", teacher_name)
    missing_homework_count = get_missing_homework_count(teacher_name)
    today_obj = hmusic_today()
    today = today_obj.strftime("%Y-%m-%d")
    selected_month = request.args.get("month", today_obj.strftime("%Y-%m"))
    view = request.args.get("view", "home")
    selected_week = request.args.get("week")
    if selected_week:
        week_start = datetime.strptime(selected_week, "%Y-%m-%d").date()
    else:
        week_start = today_obj - timedelta(days=(today_obj.weekday() + 1) % 7)
    week_end = week_start + timedelta(days=6)

    month_year = int(selected_month[:4])
    month_num = int(selected_month[5:7])
    month_start = date(month_year, month_num, 1)
    if month_num == 12:
        month_end = date(month_year + 1, 1, 1) - timedelta(days=1)
    else:
        month_end = date(month_year, month_num + 1, 1) - timedelta(days=1)

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    cursor.execute("""
    SELECT
        s.id, s.lesson_date, s.lesson_time, s.student_name, s.classroom, s.status,
        COALESCE(s.duration, 30), COALESCE(s.course_type_name, ''), COALESCE(s.is_group, 0),
        COALESCE(s.group_size, 0), COALESCE(s.schedule_type, ''), COALESCE(c.display_color, '')
    FROM schedule s
    LEFT JOIN course_types c ON s.course_type_id = c.id
    WHERE s.teacher = ?
    AND s.lesson_date LIKE ?
    ORDER BY s.lesson_date, s.lesson_time
    """, (teacher_name, selected_month + "%"))
    lessons = cursor.fetchall()

    cursor.execute("""
    SELECT
        s.id, s.lesson_date, s.lesson_time, s.student_name, s.classroom, s.status,
        COALESCE(s.duration, 30), COALESCE(s.course_type_name, ''), COALESCE(s.is_group, 0),
        COALESCE(s.group_size, 0), COALESCE(s.schedule_type, ''), COALESCE(c.display_color, '')
    FROM schedule s
    LEFT JOIN course_types c ON s.course_type_id = c.id
    WHERE s.teacher = ?
    AND s.lesson_date >= ?
    AND s.lesson_date <= ?
    ORDER BY s.lesson_date, s.lesson_time
    """, (teacher_name, week_start.strftime("%Y-%m-%d"), week_end.strftime("%Y-%m-%d")))
    week_lessons = cursor.fetchall()

    cursor.execute("""
    SELECT
        s.id, s.lesson_date, s.lesson_time, s.student_name, s.classroom, s.status,
        COALESCE(s.duration, 30), COALESCE(s.course_type_name, ''), COALESCE(s.is_group, 0),
        COALESCE(s.group_size, 0), COALESCE(s.schedule_type, ''), COALESCE(c.display_color, '')
    FROM schedule s
    LEFT JOIN course_types c ON s.course_type_id = c.id
    WHERE s.teacher = ?
    AND s.lesson_date = ?
    ORDER BY s.lesson_time
    """, (teacher_name, today))
    today_lessons = cursor.fetchall()

    cursor.execute("""
    SELECT
        COALESCE(SUM(payroll_amount), 0),
        COALESCE(SUM(teacher_pay_amount), 0),
        COUNT(*)
    FROM schedule
    WHERE teacher = ?
    AND lesson_date >= ?
    AND lesson_date <= ?
    """, (teacher_name, month_start.strftime("%Y-%m-%d"), month_end.strftime("%Y-%m-%d")))
    payroll_summary = cursor.fetchone()

    cursor.execute("SELECT COALESCE(hourly_rate, 0) FROM teachers WHERE teacher_name=?", (teacher_name,))
    rate_row = cursor.fetchone()
    teacher_rate = rate_row[0] if rate_row else 0
    cursor.execute("""
    CREATE TABLE IF NOT EXISTS classrooms (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        room_name TEXT UNIQUE
    )
    """)
    cursor.executemany("INSERT OR IGNORE INTO classrooms (room_name) VALUES (?)", [("Room 1",), ("Room 2",), ("Room 3",), ("Trial Room",)])
    conn.commit()
    cursor.execute("""
    SELECT
        r.id,
        r.location_id,
        r.room_name,
        COALESCE(l.location_name, '')
    FROM studio_rooms r
    LEFT JOIN studio_locations l ON l.id = r.location_id
    WHERE COALESCE(r.active, 1) = 1
    AND COALESCE(l.active, 1) = 1
    ORDER BY COALESCE(l.sort_order, 0), COALESCE(l.location_name, ''), COALESCE(r.sort_order, 0), r.room_name
    """)
    teacher_calendar_rooms = cursor.fetchall()
    if not teacher_calendar_rooms:
        cursor.execute("SELECT NULL, NULL, room_name, '' FROM classrooms ORDER BY room_name")
        teacher_calendar_rooms = cursor.fetchall()
    cursor.execute("SELECT id, name, duration, is_group FROM course_types WHERE active = 1 ORDER BY name, duration")
    teacher_calendar_courses = cursor.fetchall()
    teacher_calendar_students = hmusic_teacher_student_rows(cursor, teacher_name, include_all=True)
    conn.close()

    completed_count = len([lesson for lesson in lessons if lesson[5] == "present"])
    actual_payroll = round(payroll_summary[0] or 0, 2)
    projected_payroll = round(payroll_summary[1] or 0, 2)
    pending_count = unread_messages + missing_homework_count
    today_label = "No lessons scheduled today" if not today_lessons else f"{len(today_lessons)} lesson(s) today"
    homework_badge = hstudio_badge(missing_homework_count)
    teacher_calendar_room_options = ''.join(
        f'<option value="{escape(r[2] or "", quote=True)}" data-room-id="{escape(str(r[0] or ""), quote=True)}" data-location-id="{escape(str(r[1] or ""), quote=True)}" data-location-name="{escape(r[3] or "", quote=True)}">{escape(((r[3] + " - ") if r[3] else "") + (r[2] or ""))}</option>'
        for r in teacher_calendar_rooms
    )
    teacher_calendar_room_payload = json.dumps([
        {
            "id": int(r[0] or 0),
            "location_id": int(r[1] or 0),
            "room_name": r[2] or "",
            "location_name": r[3] or "",
            "label": ((r[3] + " - ") if r[3] else "") + (r[2] or ""),
        }
        for r in teacher_calendar_rooms
    ])
    def teacher_course_default_sort_key(course):
        name = (course[1] or "").lower()
        duration = safe_minutes(course[2], 0)
        is_group = int(course[3] or 0)
        private_30 = (not is_group) and duration == 30 and "private" in name
        return (0 if private_30 else 1, is_group, 0 if duration == 30 else 1, name, duration)
    teacher_calendar_courses = sorted(teacher_calendar_courses, key=teacher_course_default_sort_key)
    teacher_calendar_course_options = ''.join(
        f'<option value="{c[0]}">{escape(c[1] or "Course")} - {safe_minutes(c[2], 0)} mins - {"Group" if c[3] else "Private"}</option>'
        for c in teacher_calendar_courses
    )
    teacher_calendar_course_payload = json.dumps([
        {
            "id": int(c[0] or 0),
            "name": c[1] or "Course",
            "duration": safe_minutes(c[2], 30),
            "is_group": int(c[3] or 0),
            "label": f'{c[1] or "Course"} - {safe_minutes(c[2], 0)} mins - {"Group" if c[3] else "Private"}',
        }
        for c in teacher_calendar_courses
    ])
    teacher_calendar_student_options = ''.join(
        f'<option value="{escape(hmusic_student_parent_label(r[0], r[1]), quote=True)}"></option>'
        for r in teacher_calendar_students
    )

    def status_label(status):
        raw = (status or "").strip().lower()
        compact = raw.replace("-", "_").replace(" ", "_")
        if compact in ("excused", "excused_24h", "cancel_>_24h", "cancelled_>_24h", "canceled_>_24h"):
            return "Cancel >24h"
        if compact in ("teacher_cancel", "teacher_cancelled"):
            return "Teacher cancel"
        if compact == "last_min_cancel":
            return "Last min cancel"
        key = hstudio_status_key(status)
        if key == "present":
            return "Present"
        if key == "noshow":
            return "No show"
        if key == "cancelled":
            return "Cancelled"
        return "Scheduled"

    def lesson_row(lesson):
        key = hstudio_status_key(lesson[5])
        return f"""
        <a class="td-lesson-row {key}" href="/add_lesson/{lesson[3]}">
            <div class="td-date">{hstudio_date_short(lesson[1])}</div>
            <div>
                <div class="td-student">{escape(lesson[3] or '-')}</div>
                <div class="td-meta">{lesson[2] or '-'} · {escape(lesson[4] or '-')}</div>
            </div>
            <div class="td-status">{status_label(lesson[5])}</div>
        </a>
        """

    def status_options(current_status):
        options = [
            ("scheduled", "Scheduled"),
            ("present", "Present"),
            ("no_show", "No Show"),
            ("last_min_cancel", "Last Min Cancel"),
            ("excused_24h", "Cancel > 24h"),
            ("teacher_cancelled", "Teacher Cancel"),
            ("makeup", "Makeup"),
        ]
        current_status = current_status or "scheduled"
        return "".join(
            f'<option value="{value}" {"selected" if value == current_status else ""}>{label}</option>'
            for value, label in options
        )

    schedule_return_url = f"/teacher_dashboard?view=schedule&week={week_start.strftime('%Y-%m-%d')}"

    def lesson_color_class(lesson):
        course_name = (lesson[7] or "").lower()
        schedule_type = (lesson[10] or "").lower()
        try:
            minutes = int(float(lesson[6] or 30))
        except (TypeError, ValueError):
            minutes = 30
        try:
            group_size = int(float(lesson[9] or 0))
        except (TypeError, ValueError):
            group_size = 0
        is_group = bool(lesson[8]) or "group" in course_name
        if "trial" in course_name or "trial" in schedule_type:
            return "trial"
        if is_group:
            return "group-large" if group_size >= 4 else "group-small"
        if minutes <= 30:
            return "private-30"
        if minutes <= 45:
            return "private-45"
        if minutes <= 60:
            return "private-60"
        return "private-long"

    def teacher_time_range(time_text, duration):
        return format_lesson_time_range(time_text, duration)

    def _t_status_dot(st):
        if st == "present":   return "sd-present"
        if st == "late":      return "sd-late"
        if st in ("no_show","no-show"): return "sd-noshow"
        if st in ("excused_24h","excused"): return "sd-early-cancel"
        if st in ("last_min_cancel", "teacher_cancelled") or (st and st.startswith("cancel")): return "sd-cancelled"
        return "sd-scheduled"

    def _t_status_label(st):
        if st == "present":
            return "Present"
        if st == "late":
            return "Late"
        if st in ("no_show", "no-show"):
            return "No show"
        if st in ("excused_24h", "excused"):
            return "Canceled > 24h"
        if st and st.startswith("cancel"):
            return "Cancelled"
        return "Scheduled"

    TEACHER_CAL_CSS = """
    <style>
    :root{
        --blue:#185FA5;--blue-bg:#E6F1FB;
        --green:#3B6D11;--green-bg:#EAF3DE;
        --purple:#534AB7;--purple-bg:#EEEDFE;
        --pink:#993556;--pink-bg:#FBEAF0;
        --amber:#854F0B;--amber-bg:#FAEEDA;
        --coral:#993C1D;--coral-bg:#FAECE7;
        --s-present:#639922;--s-scheduled:#378ADD;--s-late:#D99019;
        --s-noshow:#E24B4A;--s-cancelled:#888780;--s-excused:#EF9F27;
    }
    .t-status-badge{display:inline-flex;align-items:center;gap:3px;
                    border-radius:999px;padding:1px 5px;font-size:8px;
                    line-height:1;font-weight:900;color:#fff;
                    box-shadow:0 1px 2px rgba(0,0,0,.18)}
    .t-status-badge:before{content:"";width:5px;height:5px;border-radius:50%;
                           background:currentColor;filter:brightness(0) invert(1)}
    .calendar-time-chip{display:inline-block;width:max-content;max-width:100%;
                        background:rgba(255,255,255,.88);color:#111827!important;font-weight:900;
                        border-radius:3px;padding:0 2px;
                        opacity:1!important;text-decoration:none!important}
    .event-time-wrap{display:inline-block;margin-top:0}
    .sd-present  {background:var(--s-present)}
    .sd-scheduled{background:var(--s-scheduled)}
    .sd-late     {background:var(--s-late)}
    .sd-noshow   {background:var(--s-noshow)}
    .sd-cancelled{background:var(--s-cancelled)}
    .sd-excused  {background:var(--s-excused)}
    .sd-early-cancel{background:#98A2B3}
    .calendar-event{border-left:4px solid var(--blue)}
    .calendar-event.early-cancel{background:#F1F3F6!important;border-left-color:#98A2B3!important;border-color:#D0D5DD!important;color:#667085!important;box-shadow:none!important}
    .calendar-event.early-cancel .t-status-badge{background:#E5E7EB;color:#667085;box-shadow:none;text-decoration:line-through;text-decoration-thickness:1.5px}
    .calendar-event.early-cancel .event-student,
    .calendar-event.early-cancel .event-line,
    .calendar-event.early-cancel .event-cancel-result{color:#667085!important;text-decoration:line-through;text-decoration-thickness:1.5px}
    .calendar-event.early-cancel .calendar-time-chip{background:#fff!important;color:#111827!important;font-weight:900;text-decoration:none!important}
    .calendar-event.early-cancel .event-cancel-result{display:block;font-size:8.5px;margin:1px 0 0;font-weight:800}
    .calendar-event.early-cancel .event-status-form select,
    .calendar-event.early-cancel .event-status-form button{text-decoration:none}
    .calendar-event{cursor:grab;user-select:none}
    .calendar-event.dragging{opacity:.35}
    .calendar-grid.multi-select-on .calendar-event{cursor:pointer}
    .calendar-event.multi-selected{outline:2px solid var(--blue);box-shadow:0 0 0 3px rgba(24,95,165,.14)}
    .teacher-select-box{display:none;position:absolute;right:5px;top:5px;z-index:2;background:rgba(255,255,255,.94);border:1px solid #D9DEE8;border-radius:6px;padding:2px}
    .teacher-select-input{width:15px;height:15px;margin:0;accent-color:var(--blue)}
    .calendar-grid.multi-select-on .teacher-select-box{display:flex}
    .calendar-grid.multi-select-on .event-status-form{display:none}
    .teacher-multi-toggle{border:1px solid #D9DEE8;border-radius:8px;background:#fff;color:#172033;padding:8px 10px;font:inherit;font-weight:900;cursor:pointer}
    .teacher-multi-toggle.active{background:var(--blue);border-color:var(--blue);color:#fff}
    .teacher-multi-bar{display:none;position:sticky;top:0;z-index:10;align-items:center;gap:8px;flex-wrap:wrap;margin:0 0 10px;padding:10px;border:1px solid #D9DEE8;border-radius:10px;background:#fff;box-shadow:0 8px 22px rgba(15,23,42,.08)}
    .teacher-multi-bar.show{display:flex}
    .teacher-multi-count{font-weight:900;color:#172033;margin-right:auto}
    .teacher-multi-bar select,.teacher-multi-bar button{height:36px;border:1px solid #D9DEE8;border-radius:8px;background:#fff;color:#172033;padding:0 10px;font:inherit;font-weight:800}
    .teacher-multi-apply{background:var(--blue)!important;border-color:var(--blue)!important;color:#fff!important}
    .teacher-multi-clear{color:#667085!important}
    .calendar-day.drop-active{outline:2px dashed var(--blue);outline-offset:-3px}
    .calendar-day-head strong{cursor:pointer;border-radius:999px;padding:1px 6px}
    .calendar-day-head strong:hover{background:rgba(24,95,165,.14)}
    .teacher-rs-overlay{position:fixed;inset:0;background:rgba(0,0,0,.45);display:none;align-items:center;justify-content:center;z-index:9999}
    .teacher-rs-overlay.show{display:flex}
    .teacher-rs-modal{background:#fff;color:#172033;border-radius:14px;padding:20px;width:330px;box-shadow:0 18px 60px rgba(0,0,0,.28)}
    .teacher-rs-modal h3{margin:0 0 6px;font-size:18px}
    .teacher-rs-modal p{margin:0 0 14px;color:#667085;font-size:13px;line-height:1.45}
    .teacher-rs-option{border:1px solid #D9DEE8;border-radius:10px;padding:10px;margin:8px 0;display:flex;gap:8px;cursor:pointer}
    .teacher-rs-option.sel{border-color:var(--blue);background:var(--blue-bg)}
    .teacher-rs-buttons{display:flex;gap:8px;margin-top:14px}
    .teacher-rs-buttons button{flex:1;border:1px solid #D9DEE8;border-radius:10px;padding:9px 10px;font-weight:700;cursor:pointer}
    .teacher-rs-ok{background:var(--blue);border-color:var(--blue)!important;color:white}
    .teacher-add-overlay{position:fixed;inset:0;background:rgba(15,23,42,.42);display:none;align-items:center;justify-content:center;z-index:1200;padding:18px}
    .teacher-add-overlay.show{display:flex}
    .teacher-add-modal{width:min(760px,calc(100vw - 28px));max-height:calc(100vh - 44px);overflow:auto;background:#fff;color:#172033;border:1px solid #E5E7EB;border-radius:14px;box-shadow:0 24px 72px rgba(15,23,42,.24)}
    .teacher-add-head{display:flex;align-items:flex-start;gap:14px;justify-content:space-between;padding:20px 22px 16px;border-bottom:1px solid #E5E7EB;background:#fff}
    .teacher-add-head h2{margin:0 0 4px;font-size:24px;line-height:1.15;color:#172033}
    .teacher-add-head p{margin:0;color:#667085;font-weight:700}
    .teacher-add-close{width:38px;height:38px;border:1px solid #D9DEE8;border-radius:8px;background:#fff;color:#667085;font-size:22px;cursor:pointer}
    .teacher-add-body{padding:18px 22px 22px}
    .teacher-add-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}
    .teacher-add-full{grid-column:1 / -1}
    .teacher-add-label{display:block;color:#667085;font-weight:900;font-size:12px;text-transform:uppercase;letter-spacing:0;margin-bottom:6px}
    .teacher-add-input,.teacher-add-select,.teacher-add-textarea{width:100%;border:1px solid #D9DEE8;border-radius:8px;background:#fff;color:#172033;font:inherit;font-weight:800;padding:11px 12px}
    .teacher-add-student-tools{display:flex;gap:8px;align-items:center;margin-top:8px;flex-wrap:wrap}.teacher-add-secondary{border:1px solid #B8CCE3;background:#EFF6FF;color:var(--blue);border-radius:8px;padding:8px 10px;font:inherit;font-size:12px;font-weight:900;cursor:pointer}.teacher-add-secondary.active{background:var(--blue);border-color:var(--blue);color:#fff}.teacher-add-mode-note{display:none;margin-top:8px;border:1px solid #BFDBFE;background:#EFF6FF;color:#1D4ED8;border-radius:8px;padding:8px 10px;font-size:12px;font-weight:800;line-height:1.35}.teacher-add-mode-note.show{display:block}
    .teacher-course-duration-action{display:flex;align-items:center;justify-content:center;gap:7px;width:100%;margin-top:9px;border:1px dashed #B8CCE3;background:#F8FBFF;color:var(--blue);border-radius:8px;padding:10px 12px;font:inherit;font-weight:900;cursor:pointer}.teacher-course-duration-action:hover{background:var(--blue-bg)}.teacher-duration-quick{display:none;margin-top:10px;padding:12px;border:1px solid #D9DEE8;border-radius:8px;background:#F8FAFC}.teacher-duration-quick.show{display:block}
    .teacher-add-textarea{min-height:92px;resize:vertical;font-weight:700}
    .teacher-add-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:18px;padding-top:16px;border-top:1px solid #E5E7EB}
    .teacher-add-actions button,.teacher-add-actions a{border:1px solid #D9DEE8;border-radius:8px;padding:11px 16px;font:inherit;font-weight:900;text-decoration:none;cursor:pointer}
    .teacher-add-cancel{background:#fff;color:#172033}
    .teacher-add-submit{background:var(--blue);border-color:var(--blue)!important;color:#fff}
    .teacher-add-note{border:1px solid #BFDBFE;background:#EFF6FF;color:#1D4ED8;border-radius:10px;padding:10px 12px;font-weight:800;line-height:1.4}
    @media(max-width:780px){.teacher-add-grid{grid-template-columns:1fr}.teacher-add-full{grid-column:auto}.teacher-add-actions{display:grid}.teacher-add-actions button,.teacher-add-actions a{width:100%;text-align:center}}
    .lesson-scrim{position:fixed;inset:0;background:rgba(17,24,39,.42);display:none;z-index:1100}.lesson-scrim.show{display:block}
    .lesson-panel{position:fixed;top:0;right:0;bottom:0;width:min(560px,100vw);background:#fff;color:#172033;z-index:1101;transform:translateX(104%);transition:transform .18s ease;box-shadow:-22px 0 46px rgba(15,23,42,.18);display:flex;flex-direction:column;border-left:1px solid #E5E7EB}.lesson-panel.show{transform:translateX(0)}
    .lesson-panel-scroll{overflow:auto;padding-bottom:16px;background:#fff}.lesson-panel-head{padding:24px 28px 18px;border-bottom:1px solid #E5E7EB;position:relative;background:#fff}.lesson-panel-close{position:absolute;right:20px;top:18px;width:40px;height:40px;border-radius:8px;border:1px solid #E5E7EB;background:#fff;color:#667085;font-size:22px;cursor:pointer}.lesson-panel-close:hover{background:#F3F6FA;color:#172033}
    .panel-status{display:inline-flex;align-items:center;border-radius:999px;padding:5px 11px;background:var(--s-scheduled);color:#fff;font-weight:900;font-size:12px;line-height:1;margin-bottom:10px}.panel-status.scheduled{background:var(--s-scheduled)}.panel-status.present{background:var(--s-present)}.panel-status.late{background:#D99019}.panel-status.no_show{background:var(--s-noshow)}.panel-status.excused{background:var(--s-excused)}.panel-status.early_cancel{background:#98A2B3}.panel-status.cancelled{background:var(--s-cancelled)}
    .lesson-panel h2{font-size:26px;margin:0 0 6px;color:#172033}.panel-sub{font-size:15px;color:#667085;font-weight:700}.panel-grid{display:grid;grid-template-columns:1fr 1fr;border-bottom:1px solid #E5E7EB;background:#fff}.panel-cell{padding:15px 28px;border-right:1px solid #E5E7EB;border-bottom:1px solid #E5E7EB}.panel-cell:nth-child(2n){border-right:0}.panel-label{display:block;color:#667085;font-size:12px;text-transform:uppercase;font-weight:900;margin-bottom:6px;letter-spacing:0}.panel-value{font-size:18px;font-weight:900;color:#172033}
    .panel-section{padding:18px 28px;border-bottom:1px solid #E5E7EB;background:#fff}.panel-section h3{font-size:13px;text-transform:uppercase;color:#667085;margin:0 0 12px;font-weight:900;letter-spacing:0}.att-row{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.att-btn{border:1px solid #D9DEE8;background:#fff;color:#172033;border-radius:8px;min-height:46px;font:inherit;font-weight:900;cursor:pointer;box-shadow:0 1px 2px rgba(15,23,42,.04)}.att-btn:hover{background:#F7FAFD;border-color:#C8D3E2}.att-btn.active{color:#fff;border-color:transparent;box-shadow:0 6px 14px rgba(15,23,42,.12)}.att-btn[data-status="present"].active{background:var(--s-present)}.att-btn[data-status="last_min_cancel"].active{background:var(--s-cancelled)}.att-btn[data-status="no_show"].active{background:var(--s-noshow)}.att-btn[data-status="excused_24h"].active{background:var(--s-excused)}.panel-field{width:100%;border:1px solid #D9DEE8;background:#fff;color:#172033;border-radius:8px;padding:11px 12px;font:inherit;font-size:15px;box-shadow:0 1px 2px rgba(15,23,42,.03)}.panel-field:focus{outline:2px solid rgba(24,95,165,.18);border-color:var(--blue)}.panel-field::placeholder{color:#98A2B3}textarea.panel-field{min-height:86px;resize:vertical;line-height:1.45}.panel-row{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px}.panel-inline-link{margin-top:10px;border:0;background:transparent;color:var(--blue);font:inherit;font-size:13px;font-weight:900;padding:0;cursor:pointer}.teacher-duration-request{display:none;margin-top:10px;padding:12px;border:1px solid #D9DEE8;border-radius:8px;background:#F8FAFC}.teacher-duration-request.show{display:block}.panel-scope-row{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px}.panel-scope-option{display:flex;gap:9px;align-items:flex-start;border:1px solid #D9DEE8;border-radius:8px;background:#fff;padding:10px 11px;cursor:pointer}.panel-scope-option.active{border-color:#B8CCE3;background:var(--blue-bg);box-shadow:inset 3px 0 0 var(--blue)}.panel-scope-option input{margin-top:2px;accent-color:var(--blue)}.panel-scope-option span{display:block;line-height:1.25}.panel-scope-option b{display:block;color:#172033;font-size:13px}.panel-scope-option small{display:block;color:#667085;font-size:11px;margin-top:3px}.panel-toggle{display:flex;align-items:center;justify-content:space-between;gap:16px}.panel-toggle strong{color:#172033}.panel-toggle small{color:#667085}.panel-toggle input{width:42px;height:24px;accent-color:var(--blue)}.panel-actions{display:grid;grid-template-columns:1fr 1fr;gap:10px}.panel-action{min-height:54px;border:1px solid #D9DEE8;background:#fff;color:#172033;border-radius:8px;font:inherit;font-weight:900;cursor:pointer}.panel-action:hover{background:var(--blue-bg);border-color:#B8CCE3;color:var(--blue)}.owner-strip{margin-top:12px;border:1px solid #D7E8C4;border-radius:8px;padding:10px 12px;color:#27500A;background:#EAF3DE;font-size:12px;line-height:1.45}.panel-footer{margin-top:auto;display:grid;grid-template-columns:1fr 1fr;gap:12px;padding:17px 28px;border-top:1px solid #E5E7EB;background:#fff;box-shadow:0 -8px 18px rgba(15,23,42,.06)}.panel-footer button{height:48px;border-radius:8px;font:inherit;font-weight:900;font-size:16px;cursor:pointer}.panel-footer button:disabled{opacity:.65;cursor:not-allowed}.panel-discard{background:#fff;color:#172033;border:1px solid #D9DEE8}.panel-discard:hover{background:#F3F6FA}.panel-save{background:var(--blue);color:#fff;border:0}.panel-save:hover{background:#0C447C}.panel-save:disabled:hover{background:var(--blue)}.panel-toast{display:none;margin:0 28px 14px;padding:10px 12px;border-radius:8px;background:#EAF3DE;color:#27500A;font-weight:800;border:1px solid #D7E8C4}.panel-toast.show{display:block}
    .reminder-pill{display:inline-flex;border-radius:999px;background:#EAF3DE;color:#27500A;padding:5px 9px;font-size:11px;font-weight:900;margin-top:8px}.reminder-pill.off{background:#FEE2E2;color:#991B1B}
    </style>
    """

    def calendar_event(lesson):
        time_range = teacher_time_range(lesson[2], lesson[6])
        lesson_status = lesson[5] or "scheduled"
        is_early_cancel = lesson_status in ("excused_24h", "excused")
        event_class = " early-cancel" if is_early_cancel else ""
        cancel_result = '<div class="event-cancel-result">No credit deducted · No fee</div>' if is_early_cancel else ""
        dot = _t_status_dot(lesson_status)
        status_text = _t_status_label(lesson_status)
        course_color = course_calendar_color(lesson[11], lesson[7], lesson[6], lesson[8])
        course_style = course_calendar_style(course_color)
        return f"""
        <div class="calendar-event{event_class}"
             draggable="true" style="border-left-width:3px;{course_style}" onclick="openTeacherLessonPanel({lesson[0]}); event.stopPropagation();"
             data-id="{lesson[0]}" data-date="{escape(str(lesson[1] or ''))}"
             data-time="{escape(str(lesson[2] or ''))}"
            data-student="{escape(str(lesson[3] or ''))}"
            data-teacher="{escape(str(teacher_name or ''))}">
            <label class="teacher-select-box" onclick="event.stopPropagation();">
                <input type="checkbox" class="teacher-select-input" value="{lesson[0]}" onchange="teacherMultiUpdate()">
            </label>
            <div class="event-top">
                <span class="event-time">
                  <span class="t-status-badge {dot}" data-teacher-status-badge>{status_text}</span>
                  <span class="event-time-wrap"><span class="calendar-time-chip">{time_range}</span></span>
                </span>
            </div>
            <button type="button" class="event-student" style="border:0;background:transparent;padding:0;text-align:left;cursor:pointer" onclick="openTeacherLessonPanel({lesson[0]}); event.stopPropagation();">{escape(lesson[3] or '-')}</button>
            <div class="event-line">{escape(lesson[4] or '-')} · {escape(lesson[7] or '')}</div>
            {cancel_result}
            <form method="POST" action="/update_lesson_status" class="event-status-form" data-teacher-status-form onclick="event.stopPropagation();" onmousedown="event.stopPropagation();">
                <input type="hidden" name="schedule_id" value="{lesson[0]}">
                <input type="hidden" name="return_to" value="{schedule_return_url}">
                <input type="hidden" name="ajax" value="1">
                <select name="status" aria-label="Attendance status">{status_options(lesson[5])}</select>
                <button type="submit">Save</button>
            </form>
        </div>
        """

    if view == "messages":
        content = teacher_dashboard_messages_content(teacher_name or "")
        return hstudio_teacher_dark_shell(
            teacher_name or "Teacher",
            unread_messages,
            content,
            active="messages",
            missing_homework_count=missing_homework_count
        )

    if view == "records":
        content = teacher_dashboard_records_content(teacher_name or "")
        return hstudio_teacher_dark_shell(
            teacher_name or "Teacher",
            unread_messages,
            content,
            active="records",
            missing_homework_count=missing_homework_count
        )

    if view == "add_schedule":
        if not teacher_perms.get("add_own_schedule"):
            content = """
            <section class='td-card'>
                <h2>Add Schedule Requires Owner Permission</h2>
                <p class='muted'>The owner can enable this from Teacher Permissions.</p>
            </section>
            """
        else:
            content = teacher_dashboard_add_schedule_content(teacher_name or "")
        return hstudio_teacher_dark_shell(
            teacher_name or "Teacher",
            unread_messages,
            content,
            active="add_schedule",
            missing_homework_count=missing_homework_count
        )

    if view == "time_off":
        content = teacher_dashboard_time_off_content(teacher_name or "")
        return hstudio_teacher_dark_shell(
            teacher_name or "Teacher",
            unread_messages,
            content,
            active="time_off",
            missing_homework_count=missing_homework_count
        )

    if view in ("schedule", "week"):
        schedule_mode = request.args.get("mode", "month")
        if schedule_mode not in ("week", "month"):
            schedule_mode = "week"

        if schedule_mode == "month":
            month_grid_start = month_start - timedelta(days=(month_start.weekday() + 1) % 7)
            month_grid_end = month_end + timedelta(days=(5 - month_end.weekday()) % 7)
            by_date = {}
            for lesson in lessons:
                by_date.setdefault(lesson[1], []).append(lesson)
            day_columns = ""
            current_day = month_grid_start
            while current_day <= month_grid_end:
                day_key = current_day.strftime("%Y-%m-%d")
                day_events = "".join(calendar_event(lesson) for lesson in by_date.get(day_key, []))
                if not day_events:
                    day_events = "<div class='calendar-empty'>No lessons</div>"
                day_columns += f"""
                <section class="calendar-day {'today' if day_key == today else ''}" data-date="{day_key}">
                    <div class="calendar-day-head"><span>{current_day.strftime('%a')}</span><strong onclick="teacherAddOnDate('{day_key}')">{hstudio_date_short(day_key)}</strong></div>
                    {day_events}
                </section>
                """
                current_day += timedelta(days=1)
            prev_month_date = (month_start - timedelta(days=1)).strftime("%Y-%m")
            next_month_date = (month_end + timedelta(days=1)).strftime("%Y-%m")
            controls = f"""
                <a href="/teacher_dashboard?view=schedule&mode=month&month={prev_month_date}">Previous</a>
                <a href="/teacher_dashboard?view=schedule&mode=month&month={next_month_date}">Next</a>
                <form method="GET" class="schedule-controls">
                    <input type="hidden" name="view" value="schedule">
                    <input type="hidden" name="mode" value="month">
                    <input type="month" name="month" value="{selected_month}">
                    <button type="submit">View</button>
                </form>
            """
        else:
            by_date = {}
            for lesson in week_lessons:
                by_date.setdefault(lesson[1], []).append(lesson)
            day_columns = ""
            for offset in range(7):
                current_day = week_start + timedelta(days=offset)
                day_key = current_day.strftime("%Y-%m-%d")
                day_events = "".join(calendar_event(lesson) for lesson in by_date.get(day_key, []))
                if not day_events:
                    day_events = "<div class='calendar-empty'>No lessons</div>"
                day_columns += f"""
                <section class="calendar-day {'today' if day_key == today else ''}" data-date="{day_key}">
                    <div class="calendar-day-head"><span>{current_day.strftime('%a')}</span><strong onclick="teacherAddOnDate('{day_key}')">{hstudio_date_short(day_key)}</strong></div>
                    {day_events}
                </section>
                """
            prev_week = (week_start - timedelta(days=7)).strftime("%Y-%m-%d")
            next_week = (week_start + timedelta(days=7)).strftime("%Y-%m-%d")
            controls = f"""
                <a href="/teacher_dashboard?view=schedule&mode=week&week={prev_week}">Previous</a>
                <a href="/teacher_dashboard?view=schedule&mode=week&week={next_week}">Next</a>
                <form method="GET" class="schedule-controls">
                    <input type="hidden" name="view" value="schedule">
                    <input type="hidden" name="mode" value="week">
                    <input type="date" name="week" value="{week_start.strftime('%Y-%m-%d')}">
                    <button type="submit">View</button>
                </form>
            """

        week_active = "active" if schedule_mode == "week" else ""
        month_active = "active" if schedule_mode == "month" else ""
        schedule_grid_class = "month-view" if schedule_mode == "month" else "week-view"
        direct_reschedule = bool(teacher_perms.get("direct_reschedule"))
        direct_cancel = bool(teacher_perms.get("direct_cancel"))
        delete_allowed = bool(teacher_perms.get("delete_lessons"))
        sub_allowed = bool(teacher_perms.get("sub_request"))
        reminder_allowed = bool(teacher_perms.get("schedule_reminders"))
        reschedule_label = "Reschedule" if direct_reschedule else "Request reschedule"
        cancel_label = "Cancel lesson" if direct_cancel else "Cancel request"
        delete_button_html = '<button class="panel-action danger" onclick="teacherDeleteLesson()">Delete lesson</button>' if delete_allowed else ''
        owner_policy_copy = "Schedule changes are enabled for your own lessons. Billing and student profile changes stay owner-managed." if direct_reschedule else "Owner approval required for final reschedule. Parents are notified only after owner confirmation."
        sub_button_html = '<button class="panel-action" onclick="teacherSubRequest()">Sub request</button>' if sub_allowed else ''
        reminder_note_html = '<span class="reminder-pill">Schedule reminders on</span>' if reminder_allowed else '<span class="reminder-pill off">Schedule reminders off</span>'
        teacher_schedule_return_url = request.full_path if request.query_string else "/teacher_dashboard?view=schedule"
        teacher_schedule_return_url_attr = escape(teacher_schedule_return_url, quote=True)
        content = f"""
            <div class="schedule-head">
                <div class="schedule-title">
                    <h1>My Calendar</h1>
                    <p>Daily lessons, class time, and attendance status.</p>{reminder_note_html}
                </div>
                <div class="schedule-controls">
                    <div class="schedule-tabs">
                        <a class="{week_active}" href="/teacher_dashboard?view=schedule&mode=week&week={week_start.strftime('%Y-%m-%d')}">This Week</a>
                        <a class="{month_active}" href="/teacher_dashboard?view=schedule&mode=month&month={selected_month}">This Month</a>
                    </div>
                    <button type="button" class="teacher-multi-toggle" id="teacherMultiToggle" onclick="teacherMultiToggle()">Multi-Select</button>
                    {controls}
                </div>
            </div>
            {TEACHER_CAL_CSS}
        <div class="teacher-multi-bar" id="teacherMultiBar">
            <div class="teacher-multi-count"><span id="teacherMultiCount">0</span> selected</div>
            <select id="teacherMultiAction">
                <option value="set_status">Set status</option>
                <option value="cancel_lessons">Cancel lessons</option>
            </select>
            <select id="teacherMultiStatus">
                <option value="scheduled">Scheduled</option>
                <option value="present">Present</option>
                <option value="no_show">No Show</option>
                <option value="last_min_cancel">Last Min Cancel</option>
                <option value="excused_24h">Cancel &gt; 24h</option>
                <option value="teacher_cancelled">Teacher Cancel</option>
            </select>
            <button class="teacher-multi-apply" type="button" onclick="teacherMultiApply()">Apply</button>
            <button class="teacher-multi-clear" type="button" onclick="teacherMultiClear()">Clear</button>
        </div>
        <div class="calendar-grid {schedule_grid_class}" id="teacherCalendarGrid">{day_columns}</div>

        <div class="teacher-add-overlay" id="teacherAddOverlay" onclick="teacherCloseAddSchedule(event)">
            <div class="teacher-add-modal" role="dialog" aria-modal="true" aria-labelledby="teacherAddTitle" onclick="event.stopPropagation()">
                <form method="POST" action="/add_schedule" id="teacherInlineAddScheduleForm">
                    <input type="hidden" name="return_to" value="{teacher_schedule_return_url_attr}">
                    <input type="hidden" name="action" id="teacherAddAction" value="">
                    <input type="hidden" name="temporary_schedule_note" id="teacherAddTempNote" value="">
                    <input type="hidden" name="teacher" value="{escape(teacher_name or '', quote=True)}">
                    <input type="hidden" name="weekday" id="teacherAddWeekday">
                    <input type="hidden" name="location_id" id="teacherAddLocationId">
                    <input type="hidden" name="room_id" id="teacherAddRoomId">
                    <input type="hidden" name="location" id="teacherAddLocationName">
                    <input type="hidden" name="billing_decision" value="existing_credits">
                    <div class="teacher-add-head">
                        <div>
                            <h2 id="teacherAddTitle">Add lesson</h2>
                            <p id="teacherAddSub">Create a lesson without leaving the calendar.</p>
                        </div>
                        <button class="teacher-add-close" type="button" onclick="teacherCloseAddSchedule()"><i class="ti ti-x"></i></button>
                    </div>
                    <div class="teacher-add-body">
                        <div class="teacher-add-grid">
                            <label>
                                <span class="teacher-add-label">Date</span>
                                <input class="teacher-add-input" type="date" name="start_date" id="teacherAddDate" required>
                            </label>
                            <label>
                                <span class="teacher-add-label">Time</span>
                                <input class="teacher-add-input" type="time" name="lesson_time" required>
                            </label>
                            <label class="teacher-add-full" id="teacherAddStudentField">
                                <span class="teacher-add-label">Student</span>
                                <input class="teacher-add-input student-picker-compact" id="teacherAddStudent" name="student_name" list="teacherInlineStudentList" placeholder="Search existing or type full student name" autocomplete="off" required>
                                <datalist id="teacherInlineStudentList">{teacher_calendar_student_options}</datalist>
                                <div class="teacher-add-student-tools">
                                    <button class="teacher-add-secondary" id="teacherUseTypedStudentButton" type="button" onclick="teacherUseTypedStudentName()">Use typed student name</button>
                                </div>
                                <div class="teacher-add-mode-note" id="teacherTypedStudentNote">This lesson will be created for the typed student name and manager will be notified to review or add the student record.</div>
                            </label>
                            <label>
                                <span class="teacher-add-label">Course</span>
                                <select class="teacher-add-select" name="course_type_id" id="teacherInlineCourseSelect" onchange="syncTeacherInlineAddFormat()" required>{teacher_calendar_course_options}</select>
                                <button class="teacher-course-duration-action" type="button" onclick="toggleTeacherQuickDuration('teacherInlineDurationBox', 'teacherInlineCourseSelect', 'teacherInlineNewDurationFormat')">+ Add a new duration to this course</button>
                                <div class="teacher-duration-quick" id="teacherInlineDurationBox">
                                    <div class="panel-row">
                                        <input class="panel-field" type="number" id="teacherInlineNewDuration" min="15" max="240" step="5" placeholder="New duration">
                                        <select class="panel-field" id="teacherInlineNewDurationFormat"><option value="private">Private</option><option value="group">Group</option></select>
                                    </div>
                                    <button class="panel-action" style="margin-top:10px;width:100%;min-height:44px" type="button" onclick="teacherAddCourseDuration('teacherInlineCourseSelect', 'teacherInlineNewDuration', 'teacherInlineNewDurationFormat')">Add to course catalog</button>
                                </div>
                            </label>
                            <label>
                                <span class="teacher-add-label">Room</span>
                                <select class="teacher-add-select" name="classroom" id="teacherInlineRoomSelect" onchange="syncTeacherInlineRoom()" required>{teacher_calendar_room_options}</select>
                            </label>
                            <label>
                                <span class="teacher-add-label">Format</span>
                                <select class="teacher-add-select" name="lesson_format" id="teacherInlineLessonFormat" onchange="syncTeacherInlineAddFormat()">
                                    <option value="private">Private</option>
                                    <option value="group">Group</option>
                                </select>
                            </label>
                            <label>
                                <span class="teacher-add-label">Schedule Type</span>
                                <select class="teacher-add-select" name="schedule_type">
                                    <option value="weekly">Weekly</option>
                                    <option value="one_time">One time</option>
                                </select>
                            </label>
                            <label>
                                <span class="teacher-add-label">Package</span>
                                <select class="teacher-add-select" name="package_type" id="teacherInlinePackageType" onchange="syncTeacherInlinePackage()">
                                    <option value="10">10 lessons</option>
                                    <option value="12">12 lessons</option>
                                    <option value="24">24 lessons</option>
                                    <option value="custom">Custom count</option>
                                    <option value="unlimited">Ongoing no package</option>
                                </select>
                            </label>
                            <label>
                                <span class="teacher-add-label">Custom Count</span>
                                <input class="teacher-add-input" type="number" name="custom_lesson_count" id="teacherInlineCustomCount" min="1" max="260" placeholder="Only if custom" disabled>
                            </label>
                            <label class="teacher-add-full" id="teacherInlineGroupStudentsField" style="display:none">
                                <span class="teacher-add-label">Group Students</span>
                                <textarea class="teacher-add-textarea" id="teacherInlineGroupStudents" name="group_student_names" placeholder="For group classes, list at least two student names separated by commas."></textarea>
                            </label>
                            <div class="teacher-add-full teacher-add-note">Billing stays owner-managed. This adds the schedule from the teacher calendar and uses existing credits unless owner changes billing later.</div>
                        </div>
                        <div class="teacher-add-actions">
                            <a class="teacher-add-cancel" href="/teacher_dashboard?view=add_schedule">Full Add Schedule page</a>
                            <button class="teacher-add-cancel" type="button" onclick="teacherCloseAddSchedule()">Cancel</button>
                            <button class="teacher-add-submit" type="submit">Create lesson</button>
                        </div>
                    </div>
                </form>
            </div>
        </div>

        <div class="lesson-scrim" id="teacherLessonScrim" onclick="closeTeacherLessonPanel()"></div>
        <aside class="lesson-panel" id="teacherLessonPanel" aria-hidden="true">
          <div class="lesson-panel-scroll">
            <div class="lesson-panel-head"><button class="lesson-panel-close" type="button" onclick="closeTeacherLessonPanel()"><i class="ti ti-x"></i></button><div class="panel-status" id="tPanelStatus">Scheduled</div><h2 id="tPanelStudent">Student</h2><div class="panel-sub" id="tPanelCourse">Course</div></div>
            <div class="panel-grid"><div class="panel-cell"><span class="panel-label">Date</span><div class="panel-value" id="tPanelDate"></div></div><div class="panel-cell"><span class="panel-label">Time</span><div class="panel-value" id="tPanelTime"></div></div><div class="panel-cell"><span class="panel-label">Room</span><div class="panel-value" id="tPanelRoom"></div></div><div class="panel-cell"><span class="panel-label">Type</span><div class="panel-value" id="tPanelType"></div></div></div>
            <div class="panel-section"><h3>Location & room</h3><select class="panel-field" id="tPanelRoomSelect" onchange="syncTeacherPanelRoom()">{teacher_calendar_room_options}</select></div>
            <div class="panel-section"><h3>Course & duration</h3><select class="panel-field" id="tPanelCourseType" onchange="syncTeacherPanelCourse()">{teacher_calendar_course_options}</select><button class="teacher-course-duration-action" type="button" onclick="toggleTeacherQuickDuration('tPanelDurationRequest', 'tPanelCourseType', 'tPanelRequestedFormat')">+ Add a new duration to this course</button><div class="teacher-duration-quick" id="tPanelDurationRequest"><div class="panel-row"><input class="panel-field" type="number" id="tPanelRequestedDuration" min="15" max="240" step="5" placeholder="New duration"><select class="panel-field" id="tPanelRequestedFormat"><option value="private">Private</option><option value="group">Group</option></select></div><button class="panel-action" style="margin-top:10px;width:100%;min-height:44px" type="button" onclick="teacherAddCourseDuration('tPanelCourseType', 'tPanelRequestedDuration', 'tPanelRequestedFormat')">Add to course catalog</button></div></div>
        <div class="panel-section"><h3>Attendance</h3><div class="att-row"><button class="att-btn" data-status="present" onclick="setTeacherPanelStatus('present')">Present</button><button class="att-btn" data-status="no_show" onclick="setTeacherPanelStatus('no_show')">No show</button><button class="att-btn" data-status="last_min_cancel" onclick="setTeacherPanelStatus('last_min_cancel')">Last min</button><button class="att-btn" data-status="excused_24h" onclick="setTeacherPanelStatus('excused_24h')">Cancel >24h</button></div></div>
            <div class="panel-section"><h3>Lesson note</h3><textarea class="panel-field" id="tPanelLessonNote" placeholder="Parent-visible lesson note"></textarea></div>
            <div class="panel-section"><h3>Private note</h3><textarea class="panel-field" id="tPanelPrivateNote" placeholder="Only teacher and owner can see this."></textarea></div>
            <div class="panel-section"><h3>Homework assignments</h3><textarea class="panel-field" id="tPanelHomework" placeholder="One homework item per line"></textarea><label class="panel-toggle" style="margin-top:12px"><span><strong>Practice reminder</strong><br><small>Send homework list to parent after lesson</small></span><input type="checkbox" id="tPanelPracticeReminder"></label></div>
            <div class="panel-section"><h3>Actions</h3><div class="panel-actions"><button class="panel-action" onclick="teacherRequestReschedule()">{reschedule_label}</button>{sub_button_html}<button class="panel-action" onclick="teacherLessonHistory()">Lesson history</button><button class="panel-action" onclick="teacherCancelRequest()">{cancel_label}</button>{delete_button_html}</div><div class="panel-row"><input class="panel-field" type="date" id="tPanelNewDate"><input class="panel-field" type="time" id="tPanelNewTime"></div><div class="panel-scope-row"><label class="panel-scope-option active" id="tPanelScopeOnce" onclick="setTeacherRescheduleScope('once')"><input type="radio" name="tPanelRescheduleScope" value="once" checked><span><b>Only this lesson</b><small>Apply changes only to this class.</small></span></label><label class="panel-scope-option" id="tPanelScopeFollowing" onclick="setTeacherRescheduleScope('following')"><input type="radio" name="tPanelRescheduleScope" value="following"><span><b>This and following lessons</b><small>Apply to this recurring series forward.</small></span></label></div><input class="panel-field" style="margin-top:10px" id="tPanelReason" placeholder="Reason / note for owner"><div class="owner-strip">{owner_policy_copy}</div></div>
            <div class="panel-toast" id="tPanelToast"></div>
          </div><div class="panel-footer"><button class="panel-discard" onclick="closeTeacherLessonPanel()">Discard</button><button class="panel-save" id="tPanelSaveButton" onclick="saveTeacherLessonPanel(false, true)">Save changes</button></div>
        </aside>
        <div class="teacher-rs-overlay" id="teacherRsOverlay">
            <div class="teacher-rs-modal">
                <h3>Move lesson</h3>
                <p id="teacherRsText">Choose how to apply this schedule change.</p>
                <label class="teacher-rs-option sel" id="teacherOptOnce" onclick="teacherScope('once')">
                    <input type="radio" name="teacher_scope" value="once" checked>
                    <span><b>This lesson only</b><br><small>Move just this class.</small></span>
                </label>
                <label class="teacher-rs-option" id="teacherOptForward" onclick="teacherScope('forward')">
                    <input type="radio" name="teacher_scope" value="forward">
                    <span><b>This and all future lessons</b><br><small>Shift this lesson and future recurring lessons.</small></span>
                </label>
                <div class="teacher-rs-buttons">
                    <button type="button" onclick="teacherCloseRs()">Cancel</button>
                    <button type="button" class="teacher-rs-ok" onclick="teacherConfirmRs()">Confirm</button>
                </div>
            </div>
        </div>
        <script>

        const TEACHER_CAN_DIRECT_RESCHEDULE = {str(direct_reschedule).lower()};
        const TEACHER_CAN_DIRECT_CANCEL = {str(direct_cancel).lower()};
        const TEACHER_CAN_DELETE = {str(delete_allowed).lower()};
        const TEACHER_CAN_ADD_SCHEDULE = {str(bool(teacher_perms.get("add_own_schedule"))).lower()};
        const TEACHER_ROOMS = {teacher_calendar_room_payload};
        const TEACHER_COURSES = {teacher_calendar_course_payload};
        let activeTeacherLesson = null;
        let activeTeacherStatus = 'scheduled';
        let teacherRescheduleScope = 'once';
        let teacherPanelSaving = false;
        let teacherMultiOn = false;
        let teacherPanelCourseChanged = false;
        let teacherPanelRoomChanged = false;
        function teacherStatusLabel(st) {{ return st === 'present' ? 'Present' : st === 'no_show' ? 'No show' : st === 'last_min_cancel' ? 'Last min cancel' : (st === 'excused_24h' || st === 'excused') ? 'Canceled > 24h' : st === 'teacher_cancelled' ? 'Teacher cancel' : 'Scheduled'; }}
        function teacherStatusClass(st) {{ return st === 'present' ? 'present' : st === 'no_show' ? 'no_show' : (st === 'excused_24h' || st === 'excused') ? 'early_cancel' : st === 'teacher_cancelled' ? 'excused' : (st === 'last_min_cancel' || (st && st.startsWith('cancel'))) ? 'cancelled' : 'scheduled'; }}
        function teacherStatusDotClass(st) {{ return st === 'present' ? 'sd-present' : st === 'late' ? 'sd-late' : st === 'no_show' ? 'sd-noshow' : (st === 'excused_24h' || st === 'excused') ? 'sd-early-cancel' : (st === 'last_min_cancel' || st === 'teacher_cancelled' || (st && st.startsWith('cancel'))) ? 'sd-cancelled' : 'sd-scheduled'; }}
        function repaintTeacherScheduleEvent(scheduleId, status) {{
            const st = status || 'scheduled';
            const isEarlyCancel = st === 'excused_24h' || st === 'excused';
            document.querySelectorAll('.calendar-event[data-id]').forEach(card => {{
                if (card.dataset.id !== String(scheduleId)) return;
                card.classList.toggle('early-cancel', isEarlyCancel);
                const badge = card.querySelector('[data-teacher-status-badge]');
                if (badge) {{
                    badge.textContent = teacherStatusLabel(st);
                    badge.className = 't-status-badge ' + teacherStatusDotClass(st);
                }}
                const select = card.querySelector('select[name="status"]');
                if (select) select.value = st;
                let cancelResult = card.querySelector('.event-cancel-result');
                if (isEarlyCancel && !cancelResult) {{
                    cancelResult = document.createElement('div');
                    cancelResult.className = 'event-cancel-result';
                    cancelResult.textContent = 'No credit deducted · No fee';
                    const line = card.querySelector('.event-line');
                    if (line) line.insertAdjacentElement('afterend', cancelResult);
                }} else if (!isEarlyCancel && cancelResult) {{
                    cancelResult.remove();
                }}
            }});
        }}
        function bindTeacherStatusForms() {{
            document.querySelectorAll('.event-status-form[data-teacher-status-form]').forEach(form => {{
                form.addEventListener('submit', e => {{
                    e.preventDefault();
                    e.stopPropagation();
                    const button = form.querySelector('button[type="submit"]');
                    const originalText = button ? button.textContent : '';
                    if (button) {{ button.disabled = true; button.textContent = 'Saving'; }}
                    fetch(form.action, {{
                        method: 'POST',
                        headers: {{'Accept':'application/json','X-CSRFToken':window.HMUSIC_CSRF_TOKEN || ''}},
                        body: new FormData(form)
                    }}).then(async r => {{
                        const text = await r.text();
                        let d = null;
                        try {{ d = text ? JSON.parse(text) : {{ok:false,error:'Empty response from server.'}}; }}
                        catch (_) {{ d = {{ok:false,error:'Server returned an unreadable response. Please refresh and try again.'}}; }}
                        if (!r.ok || !d.ok) throw new Error(d.error || 'Status was not saved');
                        repaintTeacherScheduleEvent(d.schedule_id || form.querySelector('input[name="schedule_id"]').value, d.status || form.querySelector('select[name="status"]').value);
                        if (button) button.textContent = 'Saved';
                        setTimeout(() => {{ if (button) button.textContent = originalText || 'Save'; }}, 900);
                    }}).catch(err => {{
                        alert(err.message);
                    }}).finally(() => {{
                        if (button) setTimeout(() => {{ button.disabled = false; }}, 250);
                    }});
                }});
            }});
        }}
        function teacherInputTime(timeText) {{ if (!timeText) return ''; const m = String(timeText).trim().match(/^(\\d{{1,2}}):(\\d{{2}})\\s*(AM|PM)?$/i); if (!m) return timeText; let h = parseInt(m[1], 10); const ap = (m[3] || '').toUpperCase(); if (ap === 'PM' && h < 12) h += 12; if (ap === 'AM' && h === 12) h = 0; return String(h).padStart(2, '0') + ':' + m[2]; }}
        function paintTeacherStatus(st) {{ activeTeacherStatus = st || 'scheduled'; const badge = document.getElementById('tPanelStatus'); badge.textContent = teacherStatusLabel(activeTeacherStatus); badge.className = 'panel-status ' + teacherStatusClass(activeTeacherStatus); document.querySelectorAll('#teacherLessonPanel .att-btn').forEach(b => b.classList.toggle('active', b.dataset.status === activeTeacherStatus)); }}
        function teacherPanelToast(msg) {{ const t = document.getElementById('tPanelToast'); t.textContent = msg; t.classList.add('show'); setTimeout(() => t.classList.remove('show'), 2600); }}
        function setTeacherRescheduleScope(scope) {{ teacherRescheduleScope = scope === 'following' ? 'following' : 'once'; const once = document.getElementById('tPanelScopeOnce'); const following = document.getElementById('tPanelScopeFollowing'); if (once) once.classList.toggle('active', teacherRescheduleScope === 'once'); if (following) following.classList.toggle('active', teacherRescheduleScope === 'following'); document.querySelectorAll('[name="tPanelRescheduleScope"]').forEach(input => input.checked = input.value === teacherRescheduleScope); }}
        function selectedTeacherPanelRoom() {{ const select = document.getElementById('tPanelRoomSelect'); const option = select && select.selectedOptions ? select.selectedOptions[0] : null; const roomId = Number(option ? option.dataset.roomId || 0 : 0); const roomName = select ? select.value || '' : ''; return TEACHER_ROOMS.find(room => Number(room.id || 0) === roomId && room.room_name === roomName) || TEACHER_ROOMS.find(room => room.room_name === roomName) || null; }}
        function teacherPanelRoomPayload() {{ const select = document.getElementById('tPanelRoomSelect'); const option = select && select.selectedOptions ? select.selectedOptions[0] : null; const room = selectedTeacherPanelRoom(); const currentRoom = activeTeacherLesson || {{}}; return {{classroom: room ? room.room_name : ((select && select.value) ? select.value : (currentRoom.classroom || '')), room_id: room ? room.id : Number(option ? option.dataset.roomId || 0 : (currentRoom.room_id || 0)), location_id: room ? room.location_id : Number(option ? option.dataset.locationId || 0 : (currentRoom.location_id || 0)), location: room ? room.location_name : (option ? option.dataset.locationName || '' : (currentRoom.location || ''))}}; }}
        function syncTeacherPanelRoom() {{ const room = teacherPanelRoomPayload(); if (activeTeacherLesson) {{ teacherPanelRoomChanged = teacherPanelRoomChanged || String(activeTeacherLesson.classroom || '') !== String(room.classroom || '') || Number(activeTeacherLesson.room_id || 0) !== Number(room.room_id || 0); activeTeacherLesson.classroom = room.classroom; activeTeacherLesson.room_id = room.room_id; activeTeacherLesson.location_id = room.location_id; activeTeacherLesson.location = room.location; }} const label = room.location ? room.location + ' - ' + room.classroom : (room.classroom || '-'); const display = document.getElementById('tPanelRoom'); if (display) display.textContent = label; }}
        function selectedTeacherPanelCourse() {{ const select = document.getElementById('tPanelCourseType'); const id = Number(select ? select.value : 0); return TEACHER_COURSES.find(course => Number(course.id) === id) || null; }}
        function syncTeacherPanelCourse() {{ const course = selectedTeacherPanelCourse(); if (!course) return; if (activeTeacherLesson) {{ teacherPanelCourseChanged = teacherPanelCourseChanged || Number(activeTeacherLesson.course_type_id || 0) !== Number(course.id || 0); activeTeacherLesson.course_type_id = course.id; activeTeacherLesson.course_name = course.name; activeTeacherLesson.duration = course.duration; activeTeacherLesson.is_group = course.is_group; }} document.getElementById('tPanelCourse').textContent = (course.name || 'Lesson') + ' · ' + ((activeTeacherLesson && activeTeacherLesson.teacher) || ''); document.getElementById('tPanelType').textContent = course.is_group ? 'Group lesson' : 'Private lesson'; if (typeof renderTeacherGroupRoster === 'function' && activeTeacherLesson) renderTeacherGroupRoster(activeTeacherLesson); }}
        function teacherSelectedCourse(selectId) {{ const select = document.getElementById(selectId); const id = Number(select ? select.value : 0); return TEACHER_COURSES.find(course => Number(course.id) === id) || null; }}
        function toggleTeacherQuickDuration(boxId, courseSelectId, formatId) {{ const box = document.getElementById(boxId); if (!box) return; box.classList.toggle('show'); const course = teacherSelectedCourse(courseSelectId); const format = document.getElementById(formatId); if (course && format) format.value = course.is_group ? 'group' : 'private'; }}
        function teacherAddCourseDuration(courseSelectId, durationInputId, formatId) {{ const course = teacherSelectedCourse(courseSelectId); const durationInput = document.getElementById(durationInputId); const duration = Number(durationInput ? durationInput.value : 0); const lessonFormat = (document.getElementById(formatId) || {{value:'private'}}).value; if (!course || !duration) {{ alert('Choose a course and enter the new duration.'); if (durationInput) durationInput.focus(); return; }} fetch('/add_course_duration_quick', {{method:'POST', headers:{{'Content-Type':'application/json','Accept':'application/json','X-CSRFToken':window.HMUSIC_CSRF_TOKEN || ''}}, body:JSON.stringify({{course_type_id:course.id, duration:duration, lesson_format:lessonFormat}})}}).then(async r => {{ const d = await r.json().catch(() => ({{ok:false,error:'Server returned an unreadable response.'}})); if (!r.ok || !d.ok) throw new Error(d.error || 'Could not add duration.'); teacherPanelToast('Added ' + (d.label || 'new duration') + '.'); setTimeout(() => location.reload(), 800); }}).catch(e => alert(e.message)); }}
        function teacherLessonAction(payload) {{ return fetch('/calendar_lesson_action', {{method:'POST', headers:{{'Content-Type':'application/json','Accept':'application/json','X-CSRFToken':window.HMUSIC_CSRF_TOKEN || ''}}, body:JSON.stringify(payload)}}).then(async r => {{ const text = await r.text(); let d = null; try {{ d = text ? JSON.parse(text) : {{ok:false,error:'Empty response from server.'}}; }} catch (_) {{ const looksLoggedOut = text.includes('owner_login') || text.includes('teacher_login') || text.includes('<html'); d = {{ok:false,error: looksLoggedOut ? 'Session expired. Please refresh this page, then log in again.' : 'Server returned an unreadable response. Please refresh and try again.'}}; }} if (!r.ok || !d.ok) {{ const msg = d.error || d.message || 'Action failed'; if (r.status === 403 && msg.toLowerCase().includes('csrf')) throw new Error('Session expired. Please refresh this page, then save again.'); throw new Error(msg); }} return d; }}); }}
        function openTeacherLessonPanel(scheduleId) {{ if (teacherMultiOn) return; fetch('/calendar_lesson_detail/' + scheduleId).then(r => r.json()).then(d => {{ if (!d.ok) throw new Error(d.error || 'Lesson not found'); activeTeacherLesson = d.lesson; teacherPanelCourseChanged = false; teacherPanelRoomChanged = false; document.getElementById('tPanelStudent').textContent = d.lesson.student || 'Student'; document.getElementById('tPanelCourse').textContent = (d.lesson.course_name || 'Lesson') + ' · ' + (d.lesson.teacher || ''); document.getElementById('tPanelDate').textContent = d.lesson.date || ''; document.getElementById('tPanelTime').textContent = d.lesson.time_range || d.lesson.time || ''; document.getElementById('tPanelRoom').textContent = d.lesson.location ? d.lesson.location + ' - ' + (d.lesson.classroom || '') : (d.lesson.classroom || '-'); document.getElementById('tPanelType').textContent = d.lesson.is_group ? 'Group lesson' : (d.lesson.schedule_type || 'Lesson'); document.getElementById('tPanelLessonNote').value = d.lesson.lesson_note || ''; document.getElementById('tPanelPrivateNote').value = d.lesson.private_note || ''; document.getElementById('tPanelHomework').value = d.lesson.homework || ''; document.getElementById('tPanelPracticeReminder').checked = !!d.lesson.practice_reminder_enabled; const roomSelect = document.getElementById('tPanelRoomSelect'); if (roomSelect) {{ let matched = false; Array.from(roomSelect.options).forEach(opt => {{ const byId = Number(d.lesson.room_id || 0) && Number(opt.dataset.roomId || 0) === Number(d.lesson.room_id || 0); const byName = !matched && opt.value === (d.lesson.classroom || ''); if (!matched && (byId || byName)) {{ opt.selected = true; matched = true; }} }}); if (!matched && d.lesson.classroom) {{ const opt = document.createElement('option'); opt.value = d.lesson.classroom || ''; opt.textContent = d.lesson.location ? d.lesson.location + ' - ' + d.lesson.classroom : d.lesson.classroom; opt.dataset.roomId = d.lesson.room_id || ''; opt.dataset.locationId = d.lesson.location_id || ''; opt.dataset.locationName = d.lesson.location || ''; roomSelect.insertBefore(opt, roomSelect.firstChild); opt.selected = true; }} }} const courseSelect = document.getElementById('tPanelCourseType'); if (courseSelect) courseSelect.value = String(d.lesson.course_type_id || ''); if (courseSelect && !courseSelect.value && TEACHER_COURSES.length) {{ const fallback = TEACHER_COURSES.find(course => Number(course.duration || 0) === Number(d.lesson.duration || 0) && Number(course.is_group || 0) === Number(d.lesson.is_group || 0)); if (fallback) courseSelect.value = String(fallback.id); }} document.getElementById('tPanelNewDate').value = d.lesson.date || ''; document.getElementById('tPanelNewTime').value = teacherInputTime(d.lesson.time || ''); document.getElementById('tPanelReason').value = ''; setTeacherRescheduleScope('once'); paintTeacherStatus(d.lesson.status || 'scheduled'); document.getElementById('teacherLessonScrim').classList.add('show'); document.getElementById('teacherLessonPanel').classList.add('show'); }}).catch(e => alert(e.message)); }}
        function closeTeacherLessonPanel() {{ document.getElementById('teacherLessonScrim').classList.remove('show'); document.getElementById('teacherLessonPanel').classList.remove('show'); activeTeacherLesson = null; }}
        function teacherPayload() {{ const course = selectedTeacherPanelCourse(); const room = teacherPanelRoomPayload(); return {{action:'save', schedule_id:activeTeacherLesson.id, change_scope:teacherRescheduleScope, status:activeTeacherStatus, course_type_id:course ? course.id : (activeTeacherLesson.course_type_id || ''), duration:course ? course.duration : (activeTeacherLesson.duration || 30), lesson_format:(course && course.is_group) ? 'group' : 'private', location_id:room.location_id, room_id:room.room_id, location:room.location, classroom:room.classroom, lesson_note:document.getElementById('tPanelLessonNote').value, private_note:document.getElementById('tPanelPrivateNote').value, homework:document.getElementById('tPanelHomework').value, practice_reminder_enabled:document.getElementById('tPanelPracticeReminder').checked}}; }}
        function teacherPanelTimeChanged() {{ if (!activeTeacherLesson) return false; const newDate = document.getElementById('tPanelNewDate').value || ''; const newTime = document.getElementById('tPanelNewTime').value || ''; const oldDate = activeTeacherLesson.date || ''; const oldTime = teacherInputTime(activeTeacherLesson.time || ''); return newDate !== oldDate || newTime !== oldTime; }}
        function setTeacherSaveBusy(isBusy) {{ teacherPanelSaving = isBusy; const btn = document.getElementById('tPanelSaveButton'); if (btn) {{ btn.disabled = isBusy; btn.textContent = isBusy ? 'Saving...' : 'Save changes'; }} }}
        function saveTeacherLessonPanel(quiet, includeTimeChange) {{ if (!activeTeacherLesson || teacherPanelSaving) return Promise.resolve(); setTeacherSaveBusy(true); const shouldMove = !!includeTimeChange && teacherPanelTimeChanged(); const room = teacherPanelRoomPayload(); return teacherLessonAction(teacherPayload()).then(d => {{ activeTeacherLesson.status = activeTeacherStatus; repaintTeacherScheduleEvent(activeTeacherLesson.id, activeTeacherStatus); if (!shouldMove) {{ if (!quiet) teacherPanelToast(d.message || 'Saved.'); if (teacherRescheduleScope === 'following' || teacherPanelCourseChanged || teacherPanelRoomChanged) setTimeout(() => location.reload(), 700); return d; }} return teacherLessonAction({{action:'reschedule', schedule_id:activeTeacherLesson.id, new_date:document.getElementById('tPanelNewDate').value, new_time:document.getElementById('tPanelNewTime').value, reschedule_scope:teacherRescheduleScope, reason:document.getElementById('tPanelReason').value, location_id:room.location_id, room_id:room.room_id, location:room.location, classroom:room.classroom}}).then(moveData => {{ if (!quiet) teacherPanelToast(moveData.message || 'Lesson moved.'); if (TEACHER_CAN_DIRECT_RESCHEDULE) setTimeout(() => location.reload(), 700); return moveData; }}); }}).catch(e => {{ teacherPanelToast(e.message); if (!quiet) alert(e.message); throw e; }}).finally(() => setTeacherSaveBusy(false)); }}
        function setTeacherPanelStatus(st) {{ paintTeacherStatus(st); saveTeacherLessonPanel(true).catch(() => {{}}); }}
        function teacherRequestReschedule() {{ if (!activeTeacherLesson) return; const room = teacherPanelRoomPayload(); teacherLessonAction({{action:'reschedule', schedule_id:activeTeacherLesson.id, new_date:document.getElementById('tPanelNewDate').value, new_time:document.getElementById('tPanelNewTime').value, reschedule_scope:teacherRescheduleScope, reason:document.getElementById('tPanelReason').value, location_id:room.location_id, room_id:room.room_id, location:room.location, classroom:room.classroom}}).then(d => teacherPanelToast(d.message || 'Request sent.')).catch(e => alert(e.message)); }}
        function teacherSubRequest() {{ if (!activeTeacherLesson) return; teacherLessonAction({{action:'sub_request', schedule_id:activeTeacherLesson.id, reason:document.getElementById('tPanelReason').value}}).then(d => teacherPanelToast(d.message || 'Request sent.')).catch(e => alert(e.message)); }}
        function teacherCancelRequest() {{ if (!activeTeacherLesson) return; const msg = TEACHER_CAN_DIRECT_CANCEL ? (teacherRescheduleScope === 'following' ? 'Cancel this and following lessons now?' : 'Cancel this lesson now?') : 'Send cancellation request to owner?'; if (!confirm(msg)) return; teacherLessonAction({{action:'cancel_request', schedule_id:activeTeacherLesson.id, cancel_scope:teacherRescheduleScope, reason:document.getElementById('tPanelReason').value}}).then(d => {{ teacherPanelToast(d.message || 'Saved.'); if (TEACHER_CAN_DIRECT_CANCEL) setTimeout(() => location.reload(), 700); }}).catch(e => alert(e.message)); }}
        function teacherDeleteLesson() {{ if (!activeTeacherLesson || !TEACHER_CAN_DELETE) return; const msg = teacherRescheduleScope === 'following' ? 'Delete this and following lessons from your calendar?' : 'Delete this lesson from your calendar?'; if (!confirm(msg)) return; teacherLessonAction({{action:'delete', schedule_id:activeTeacherLesson.id, delete_scope:teacherRescheduleScope}}).then(d => {{ teacherPanelToast(d.message || 'Deleted.'); setTimeout(() => location.reload(), 700); }}).catch(e => alert(e.message)); }}
        function teacherLessonHistory() {{ if (activeTeacherLesson) window.location.href = '/add_lesson/' + encodeURIComponent(activeTeacherLesson.student || ''); }}

        let teacherDrag = null;
        function teacherMultiSelectedIds() {{
            return Array.from(document.querySelectorAll('.teacher-select-input:checked')).map(cb => cb.value);
        }}
        function teacherMultiUpdate() {{
            const ids = teacherMultiSelectedIds();
            const count = document.getElementById('teacherMultiCount');
            const bar = document.getElementById('teacherMultiBar');
            if (count) count.textContent = ids.length;
            if (bar) bar.classList.toggle('show', teacherMultiOn && ids.length > 0);
            document.querySelectorAll('.calendar-event[data-id]').forEach(card => {{
                const cb = card.querySelector('.teacher-select-input');
                card.classList.toggle('multi-selected', !!cb && cb.checked);
            }});
        }}
        function teacherMultiToggle() {{
            teacherMultiOn = !teacherMultiOn;
            const grid = document.getElementById('teacherCalendarGrid');
            const toggle = document.getElementById('teacherMultiToggle');
            if (grid) grid.classList.toggle('multi-select-on', teacherMultiOn);
            if (toggle) toggle.classList.toggle('active', teacherMultiOn);
            if (!teacherMultiOn) teacherMultiClear();
            teacherMultiUpdate();
        }}
        function teacherMultiClear() {{
            document.querySelectorAll('.teacher-select-input').forEach(cb => cb.checked = false);
            teacherMultiUpdate();
        }}
        function teacherMultiApply() {{
            const ids = teacherMultiSelectedIds();
            if (!ids.length) return;
            const action = document.getElementById('teacherMultiAction').value;
            const payload = {{action, schedule_ids: ids}};
            if (action === 'set_status') payload.status = document.getElementById('teacherMultiStatus').value;
            if (action === 'cancel_lessons' && !confirm('Cancel selected lessons?')) return;
            fetch('/teacher_multi_select_action', {{
                method:'POST',
                headers:{{'Content-Type':'application/json','Accept':'application/json','X-CSRFToken':window.HMUSIC_CSRF_TOKEN || ''}},
                body:JSON.stringify(payload)
            }}).then(async r => {{
                const text = await r.text();
                let d = null;
                try {{ d = text ? JSON.parse(text) : {{ok:false,error:'Empty response from server.'}}; }}
                catch (_) {{
                    const looksLoggedOut = text.includes('teacher_login') || text.includes('<html');
                    d = {{ok:false,error: looksLoggedOut ? 'Session expired. Please refresh and log in again.' : 'Server returned an unreadable response. Please refresh and try again.'}};
                }}
                if (!r.ok || !d.ok) throw new Error(d.error || d.message || 'Action failed');
                location.reload();
            }}).catch(e => alert(e.message));
        }}
        function teacherWeekdayFromDate(dateStr) {{
            const names = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
            const d = new Date(dateStr + 'T12:00:00');
            return names[d.getDay()] || '';
        }}
        function teacherInlineCourseIsGroup() {{
            const select = document.getElementById('teacherInlineCourseSelect');
            if (!select || !select.options[select.selectedIndex]) return false;
            return select.options[select.selectedIndex].text.toLowerCase().includes('group');
        }}
        function teacherInlineIsGroupLesson() {{
            const format = document.getElementById('teacherInlineLessonFormat');
            return teacherInlineCourseIsGroup() || (format && format.value === 'group');
        }}
        function syncTeacherInlineAddFormat() {{
            const format = document.getElementById('teacherInlineLessonFormat');
            const groupField = document.getElementById('teacherInlineGroupStudentsField');
            const groupNames = document.getElementById('teacherInlineGroupStudents');
            const studentField = document.getElementById('teacherAddStudentField');
            const student = document.getElementById('teacherAddStudent');
            if (format && teacherInlineCourseIsGroup()) format.value = 'group';
            const isGroup = teacherInlineIsGroupLesson();
            if (groupField) groupField.style.display = isGroup ? 'block' : 'none';
            if (studentField) studentField.style.display = isGroup ? 'none' : 'block';
            if (student) {{
                student.required = !isGroup;
                if (isGroup) student.value = '';
            }}
            if (isGroup) teacherResetTypedStudentMode();
            if (groupNames && !isGroup) groupNames.value = '';
        }}
        function syncTeacherInlinePackage() {{
            const packageType = document.getElementById('teacherInlinePackageType');
            const customCount = document.getElementById('teacherInlineCustomCount');
            if (!packageType || !customCount) return;
            const isCustom = packageType.value === 'custom';
            customCount.disabled = !isCustom;
            customCount.required = isCustom;
            if (!isCustom) customCount.value = '';
        }}
        function teacherUseTypedStudentName() {{
            const student = document.getElementById('teacherAddStudent');
            const action = document.getElementById('teacherAddAction');
            const note = document.getElementById('teacherAddTempNote');
            const button = document.getElementById('teacherUseTypedStudentButton');
            const noteBox = document.getElementById('teacherTypedStudentNote');
            const studentName = student ? student.value.trim() : '';
            if (!studentName) {{
                alert('Please type the full student name first.');
                if (student) student.focus();
                return;
            }}
            if (action) action.value = 'create_unassigned_teacher_schedule';
            if (note) note.value = 'Teacher entered a walk-in / outside-system student from quick add: ' + studentName;
            if (button) {{
                button.classList.add('active');
                button.textContent = 'Typed name selected';
            }}
            if (noteBox) noteBox.classList.add('show');
        }}
        function teacherResetTypedStudentMode() {{
            const action = document.getElementById('teacherAddAction');
            const note = document.getElementById('teacherAddTempNote');
            const button = document.getElementById('teacherUseTypedStudentButton');
            const noteBox = document.getElementById('teacherTypedStudentNote');
            if (action) action.value = '';
            if (note) note.value = '';
            if (button) {{
                button.classList.remove('active');
                button.textContent = 'Use typed student name';
            }}
            if (noteBox) noteBox.classList.remove('show');
        }}
        function syncTeacherInlineRoom() {{
            const roomSelect = document.getElementById('teacherInlineRoomSelect');
            if (!roomSelect || !roomSelect.options[roomSelect.selectedIndex]) return;
            const option = roomSelect.options[roomSelect.selectedIndex];
            const locationId = document.getElementById('teacherAddLocationId');
            const roomId = document.getElementById('teacherAddRoomId');
            const locationName = document.getElementById('teacherAddLocationName');
            if (locationId) locationId.value = option.dataset.locationId || '';
            if (roomId) roomId.value = option.dataset.roomId || '';
            if (locationName) locationName.value = option.dataset.locationName || '';
        }}
        function teacherOpenAddSchedule(dateStr) {{
            if (!TEACHER_CAN_ADD_SCHEDULE) {{
                alert('Add Schedule requires owner permission.');
                return;
            }}
            const overlay = document.getElementById('teacherAddOverlay');
            const dateInput = document.getElementById('teacherAddDate');
            const weekdayInput = document.getElementById('teacherAddWeekday');
            const sub = document.getElementById('teacherAddSub');
            if (dateInput) dateInput.value = dateStr || '';
            if (weekdayInput) weekdayInput.value = teacherWeekdayFromDate(dateStr || '');
            if (sub) sub.textContent = 'Create a lesson on ' + (dateStr || 'this date') + ' without leaving the calendar.';
            teacherResetTypedStudentMode();
            syncTeacherInlineAddFormat();
            syncTeacherInlinePackage();
            syncTeacherInlineRoom();
            if (overlay) overlay.classList.add('show');
            setTimeout(() => {{
                const first = document.getElementById('teacherAddStudent');
                const time = document.querySelector('#teacherInlineAddScheduleForm input[name="lesson_time"]');
                if (first && first.offsetParent !== null) first.focus();
                else if (time) time.focus();
            }}, 50);
        }}
        function teacherCloseAddSchedule(event) {{
            if (event && event.target !== document.getElementById('teacherAddOverlay')) return;
            const overlay = document.getElementById('teacherAddOverlay');
            if (overlay) overlay.classList.remove('show');
        }}
        function teacherAddOnDate(dateStr) {{
            teacherOpenAddSchedule(dateStr);
        }}
        const teacherInlineAddScheduleForm = document.getElementById('teacherInlineAddScheduleForm');
        const teacherAddStudentInput = document.getElementById('teacherAddStudent');
        if (teacherAddStudentInput) teacherAddStudentInput.addEventListener('input', teacherResetTypedStudentMode);
        if (teacherInlineAddScheduleForm) teacherInlineAddScheduleForm.addEventListener('submit', function(e) {{
            if (!teacherInlineIsGroupLesson()) return;
            const namesInput = document.getElementById('teacherInlineGroupStudents');
            const names = (namesInput ? namesInput.value : '').split(',').map(name => name.trim()).filter(Boolean);
            if (Array.from(new Set(names)).length < 2) {{
                e.preventDefault();
                alert('Group class needs at least two different students.');
            }}
        }});
        syncTeacherInlineAddFormat();
        syncTeacherInlinePackage();
        syncTeacherInlineRoom();
        bindTeacherStatusForms();
        document.querySelectorAll(".calendar-event[data-id]").forEach(card => {{
            card.addEventListener("click", e => {{
                if (!teacherMultiOn) return;
                if (e.target.closest('select,button,form,input,label')) return;
                const cb = card.querySelector('.teacher-select-input');
                if (cb) {{
                    cb.checked = !cb.checked;
                    teacherMultiUpdate();
                }}
                e.preventDefault();
                e.stopPropagation();
            }});
            card.addEventListener("dragstart", e => {{
                if (teacherMultiOn) {{
                    e.preventDefault();
                    return;
                }}
                teacherDrag = {{
                    id: card.dataset.id,
                    from: card.dataset.date,
                    student: card.dataset.student
                }};
                card.classList.add("dragging");
                e.dataTransfer.effectAllowed = "move";
            }});
            card.addEventListener("dragend", () => {{
                card.classList.remove("dragging");
                document.querySelectorAll(".calendar-day.drop-active").forEach(day => day.classList.remove("drop-active"));
            }});
        }});
        document.querySelectorAll(".calendar-day[data-date]").forEach(day => {{
            day.addEventListener("dragover", e => {{
                if (!teacherDrag) return;
                e.preventDefault();
                day.classList.add("drop-active");
            }});
            day.addEventListener("dragleave", () => day.classList.remove("drop-active"));
            day.addEventListener("drop", e => {{
                e.preventDefault();
                day.classList.remove("drop-active");
                if (!teacherDrag || teacherDrag.from === day.dataset.date) return;
                teacherDrag.to = day.dataset.date;
                document.getElementById("teacherRsText").innerHTML = `Moving <b>${{teacherDrag.student}}</b><br>${{teacherDrag.from}} &rarr; ${{teacherDrag.to}}`;
                teacherScope("once");
                document.getElementById("teacherRsOverlay").classList.add("show");
            }});
        }});
        function teacherScope(scope) {{
            document.getElementById("teacherOptOnce").classList.toggle("sel", scope === "once");
            document.getElementById("teacherOptForward").classList.toggle("sel", scope === "forward");
            document.querySelector('[name="teacher_scope"][value="once"]').checked = scope === "once";
            document.querySelector('[name="teacher_scope"][value="forward"]').checked = scope === "forward";
        }}
        function teacherCloseRs() {{
            document.getElementById("teacherRsOverlay").classList.remove("show");
            teacherDrag = null;
        }}
        function teacherConfirmRs() {{
            if (!teacherDrag) return;
            const scope = document.querySelector('[name="teacher_scope"]:checked').value;
            fetch("/reschedule_schedule", {{
                method: "POST",
                headers: {{"Content-Type": "application/json", "Accept": "application/json", "X-CSRFToken": window.HMUSIC_CSRF_TOKEN || ""}},
                body: JSON.stringify({{
                    schedule_id: teacherDrag.id,
                    new_date: teacherDrag.to,
                    scope
                }})
            }})
            .then(async r => {{
                const text = await r.text();
                let data = null;
                try {{ data = text ? JSON.parse(text) : {{ok:false,error:"Empty response from server."}}; }}
                catch (_) {{
                    const looksLoggedOut = text.includes("teacher_login") || text.includes("<html");
                    data = {{ok:false,error: looksLoggedOut ? "Session expired. Please refresh and log in again." : "Server returned an unreadable response. Please refresh and try again."}};
                }}
                if (!r.ok || !data.ok) throw new Error(data.error || data.message || "Could not move lesson.");
                location.reload();
            }})
            .catch(e => alert(e.message));
        }}
        </script>
        """
        return hstudio_teacher_dark_shell(
            teacher_name or "Teacher",
            unread_messages,
            content,
            active="schedule",
            missing_homework_count=missing_homework_count
        )

