# =========================
# V27 Parent Pro
# Parent profiles, multi-student access, and parent activity logs
# =========================

def ensure_v27_schema():
    global _v27_schema_ready
    if _v27_schema_ready:
        return

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()

    cursor.execute("""
    CREATE TABLE IF NOT EXISTS parent_profiles (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        parent_name TEXT,
        email TEXT UNIQUE,
        phone TEXT,
        password TEXT DEFAULT '',
        password_hash TEXT,
        must_change_password INTEGER DEFAULT 0,
        active INTEGER DEFAULT 1,
        created_at TEXT,
        updated_at TEXT
    )
    """)

    for column_name, column_sql in [
        ("parent_name", "parent_name TEXT"),
        ("email", "email TEXT"),
        ("phone", "phone TEXT"),
        ("password", "password TEXT DEFAULT ''"),
        ("password_hash", "password_hash TEXT"),
        ("must_change_password", "must_change_password INTEGER DEFAULT 0"),
        ("active", "active INTEGER DEFAULT 1"),
        ("created_at", "created_at TEXT"),
        ("updated_at", "updated_at TEXT"),
    ]:
        add_column_if_missing(cursor, "parent_profiles", column_name, column_sql)

    cursor.execute("""
    CREATE TABLE IF NOT EXISTS parent_students (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        parent_id INTEGER,
        student_name TEXT,
        relationship TEXT DEFAULT 'Parent',
        active INTEGER DEFAULT 1,
        created_at TEXT
    )
    """)

    for column_name, column_sql in [
        ("parent_id", "parent_id INTEGER"),
        ("student_name", "student_name TEXT"),
        ("relationship", "relationship TEXT DEFAULT 'Parent'"),
        ("active", "active INTEGER DEFAULT 1"),
        ("created_at", "created_at TEXT"),
    ]:
        add_column_if_missing(cursor, "parent_students", column_name, column_sql)

    try:
        cursor.execute("""
        CREATE UNIQUE INDEX IF NOT EXISTS idx_parent_students_unique
        ON parent_students(parent_id, student_name)
        """)
    except sqlite3.IntegrityError:
        pass

    cursor.execute("""
    CREATE TABLE IF NOT EXISTS parent_activity_logs (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        parent_id INTEGER,
        student_name TEXT,
        action_type TEXT,
        description TEXT,
        related_schedule_id INTEGER,
        created_at TEXT
    )
    """)

    cursor.execute("PRAGMA table_info(students)")
    student_columns = [row[1] for row in cursor.fetchall()]
    if "parent_phone" not in student_columns:
        cursor.execute("ALTER TABLE students ADD COLUMN parent_phone TEXT")

    now = datetime.now().strftime("%Y-%m-%d %H:%M")

    cursor.execute("""
    SELECT name, parent_name, parent_email, parent_phone
    FROM students
    WHERE (
        parent_email IS NOT NULL
        AND parent_email != ''
    )
    OR (
        parent_phone IS NOT NULL
        AND parent_phone != ''
    )
    """)

    students = cursor.fetchall()
    default_parent_password_hash = hmusic_password_hash("1234") if students else ""

    for student in students:
        student_name = student[0]
        parent_name = student[1] or (student[2].split("@")[0] if student[2] and "@" in student[2] else "Parent")
        parent_email = student[2] or f"phone-{student[3]}@hmusic.local"
        parent_phone = student[3]

        cursor.execute("""
        INSERT OR IGNORE INTO parent_profiles (
            parent_name,
            email,
            phone,
            password,
            password_hash,
            must_change_password,
            active,
            created_at,
            updated_at
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        """, (
            parent_name,
            parent_email,
            parent_phone,
            "",
            default_parent_password_hash,
            1,
            1,
            now,
            now
        ))

        cursor.execute("""
        UPDATE parent_profiles
        SET parent_name = COALESCE(NULLIF(parent_name, ''), ?),
            phone = COALESCE(NULLIF(phone, ''), ?),
            updated_at = ?
        WHERE email = ?
        """, (
            parent_name,
            parent_phone,
            now,
            parent_email
        ))

        cursor.execute("""
        SELECT id
        FROM parent_profiles
        WHERE email = ?
        """, (parent_email,))

        parent = cursor.fetchone()

        if parent:
            cursor.execute("""
            INSERT OR IGNORE INTO parent_students (
                parent_id,
                student_name,
                relationship,
                active,
                created_at
            )
            VALUES (?, ?, ?, ?, ?)
            """, (
                parent[0],
                student_name,
                "Parent",
                1,
                now
            ))

    migrate_legacy_passwords(cursor, "parent_profiles", limit=5)

    conn.commit()
    conn.close()
    _v27_schema_ready = True


def sync_parent_profile_for_student(cursor, student_name, parent_name=None, parent_email=None, parent_phone=None):
    if not parent_email and not parent_phone:
        return

    now = datetime.now().strftime("%Y-%m-%d %H:%M")
    email_key = parent_email or f"phone-{parent_phone}@hmusic.local"
    display_name = parent_name or (email_key.split("@")[0] if "@" in email_key else "Parent")

    if hmusic_is_real_email(parent_email):
        cursor.execute("""
        SELECT pp.id, pp.email
        FROM parent_students ps
        JOIN parent_profiles pp ON pp.id = ps.parent_id
        WHERE ps.student_name = ?
        AND COALESCE(ps.active, 1) = 1
        AND lower(COALESCE(pp.email, '')) LIKE '%@hmusic.local'
        ORDER BY pp.id
        LIMIT 1
        """, (student_name,))
        legacy_parent = cursor.fetchone()

        cursor.execute("SELECT id FROM parent_profiles WHERE email = ?", (parent_email,))
        existing_real_parent = cursor.fetchone()

        if legacy_parent and not existing_real_parent:
            cursor.execute("""
            UPDATE parent_profiles
            SET email = ?,
                parent_name = ?,
                phone = ?,
                updated_at = ?
            WHERE id = ?
            """, (
                parent_email,
                display_name,
                parent_phone,
                now,
                legacy_parent[0]
            ))
        elif legacy_parent and existing_real_parent:
            cursor.execute("""
            INSERT OR IGNORE INTO parent_students (
                parent_id,
                student_name,
                relationship,
                active,
                created_at
            )
            VALUES (?, ?, ?, ?, ?)
            """, (
                existing_real_parent[0],
                student_name,
                "Parent",
                1,
                now
            ))
            cursor.execute("""
            UPDATE parent_students
            SET active = 0
            WHERE student_name = ?
            AND parent_id = ?
            """, (
                student_name,
                legacy_parent[0]
            ))

    cursor.execute("""
    INSERT OR IGNORE INTO parent_profiles (
        parent_name,
        email,
        phone,
        password,
        password_hash,
        must_change_password,
        active,
        created_at,
        updated_at
    )
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
    """, (
        display_name,
        email_key,
        parent_phone,
        "",
        hmusic_password_hash("1234"),
        1,
        1,
        now,
        now
    ))

    cursor.execute("""
    UPDATE parent_profiles
    SET parent_name = ?,
        phone = ?,
        updated_at = ?
    WHERE email = ?
    """, (
        display_name,
        parent_phone,
        now,
        email_key
    ))

    cursor.execute("SELECT id FROM parent_profiles WHERE email = ?", (email_key,))
    parent = cursor.fetchone()
    if not parent:
        return

    cursor.execute("""
    INSERT OR IGNORE INTO parent_students (
        parent_id,
        student_name,
        relationship,
        active,
        created_at
    )
    VALUES (?, ?, ?, ?, ?)
    """, (
        parent[0],
        student_name,
        "Parent",
        1,
        now
    ))


def teacher_can_access_student_record(cursor, student_name, teacher_name):
    if not student_name or not teacher_name:
        return False

    cursor.execute("""
    SELECT 1
    FROM students
    WHERE LOWER(TRIM(name)) = LOWER(?)
    AND LOWER(TRIM(teacher)) = LOWER(?)
    LIMIT 1
    """, (student_name, teacher_name))
    if cursor.fetchone():
        return True

    cursor.execute("""
    SELECT 1
    FROM enrollments
    WHERE LOWER(TRIM(student_name)) = LOWER(?)
    AND LOWER(TRIM(teacher_name)) = LOWER(?)
    AND COALESCE(LOWER(TRIM(status)), 'active') NOT IN ('inactive', 'cancelled', 'canceled', 'archived', 'deleted')
    LIMIT 1
    """, (student_name, teacher_name))
    if cursor.fetchone():
        return True

    cursor.execute("""
    SELECT 1
    FROM schedule
    WHERE LOWER(TRIM(student_name)) = LOWER(?)
    AND LOWER(TRIM(teacher)) = LOWER(?)
    LIMIT 1
    """, (student_name, teacher_name))
    return cursor.fetchone() is not None


def auto_link_student_teacher(cursor, student_name, teacher_name):
    if not student_name or not teacher_name:
        return

    cursor.execute("""
    SELECT teacher
    FROM students
    WHERE name = ?
    """, (student_name,))
    row = cursor.fetchone()
    if not row:
        return

    current_teacher = (row[0] or "").strip()
    if not current_teacher:
        cursor.execute("""
        UPDATE students
        SET teacher = ?
        WHERE name = ?
        """, (teacher_name, student_name))


def get_parent_students(parent_id):
    ensure_v27_schema()

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()

    cursor.execute("""
    SELECT
        s.name,
        s.teacher,
        s.parent_email,
        s.lessons_left
    FROM parent_students ps
    JOIN students s
        ON ps.student_name = s.name
    WHERE ps.parent_id = ?
    AND ps.active = 1
    ORDER BY s.name
    """, (parent_id,))

    students = cursor.fetchall()
    conn.close()

    return students


def parent_can_access_student(parent_id, student_name):
    if not parent_id:
        return session.get("parent_student_name") == student_name

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()

    cursor.execute("""
    SELECT id
    FROM parent_students
    WHERE parent_id = ?
    AND student_name = ?
    AND active = 1
    """, (parent_id, student_name))

    row = cursor.fetchone()
    conn.close()

    return row is not None


def log_parent_activity(parent_id, student_name, action_type, description, related_schedule_id=None):
    if not parent_id:
        return

    ensure_v27_schema()

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()

    cursor.execute("""
    INSERT INTO parent_activity_logs (
        parent_id,
        student_name,
        action_type,
        description,
        related_schedule_id,
        created_at
    )
    VALUES (?, ?, ?, ?, ?, ?)
    """, (
        parent_id,
        student_name,
        action_type,
        description,
        related_schedule_id,
        datetime.now().strftime("%Y-%m-%d %H:%M")
    ))

    conn.commit()
    conn.close()


