def handle_child_os_confirmed_intent(parent_id, parent_name, student_name, request_text, confirmed_intent):
    response_lang = "en"
    language = child_os_detect_language(request_text)
    related_schedule_id = None

    direct_delegate = {
        "cancel_one_lesson": "Please cancel my next lesson.",
        "change_one_lesson": "Please reschedule one lesson.",
    }
    if confirmed_intent in direct_delegate:
        return handle_child_os_request(parent_id, parent_name, student_name, direct_delegate[confirmed_intent] + " Original request: " + request_text)

    mapped = {
        "withdraw_enrollment": ("withdraw_enrollment", "red", "owner", "owner_only", "I've notified the studio owner. They will follow up with you within 24 hours."),
        "refund_request": ("refund_request", "red", "owner", "owner_only", "Your refund request has been sent to the studio owner. They will review it and reply within 24 hours."),
        "withdraw_previous_request": ("withdraw_previous_request", "teal", "auto", "executed", "Done. I withdrew your previous request and updated the record."),
        "cancel_all_future": ("cancel_all_future", "red", "owner", "owner_only", "I've notified the studio owner that you want to cancel all future lessons. They will follow up within 24 hours."),
        "cancel_previous_request": ("cancel_previous_request", "teal", "auto", "executed", "Done. I cancelled your previous request and updated the record."),
        "change_future_schedule": ("reschedule_future", "amber", "teacher", "needs_confirmation", "This recurring schedule change needs teacher confirmation. We will update you after it is approved."),
        "change_teacher": ("change_teacher", "red", "owner", "owner_only", "Changing teacher requires studio owner help. I've sent this to the owner for follow-up within 24 hours."),
        "change_program": ("change_program", "red", "owner", "owner_only", "Changing program or instrument requires studio review. I've sent this to the owner for follow-up."),
        "general_schedule": ("schedule_question", "amber", "teacher", "needs_confirmation", "I can help with that. Please share the lesson date/time, or use Reschedule so we can make sure the change is accurate."),
        "general_billing": ("billing_question", "amber", "owner", "needs_confirmation", "I’ll check this with the studio/admin team and reply after they confirm."),
        "general_teacher": ("teacher_program_question", "red", "owner", "owner_only", "I’ll ask the studio owner to review this teacher/program question and follow up with you."),
        "general_owner": ("owner_question", "red", "owner", "owner_only", "I’ll pass this to the studio owner. They will follow up with you within 24 hours."),
        "trial_another_child": ("trial_request_another_child", "teal", "auto", "guided", "Sure — please complete this short trial request form. I’ll link it to your H-Music family account."),
        "trial_another_instrument": ("trial_request_another_instrument", "teal", "auto", "guided", "Sure — please complete this trial request form for the new instrument. I’ll link it to your H-Music family account."),
    }

    intent, risk_level, route_to, status, outcome = mapped.get(
        confirmed_intent,
        ("owner_question", "red", "owner", "owner_only", "I sent this to the studio owner for follow-up.")
    )
    request_id = create_child_os_request(
        parent_id,
        parent_name,
        student_name,
        request_text,
        language,
        intent,
        risk_level,
        route_to,
        status,
        outcome,
        related_schedule_id
    )
    create_notification(
        "owner",
        "owner",
        "Child OS request",
        f"{risk_level.upper()} · {intent} · {student_name}: {request_text}",
        "/owner_child_os"
    )
    return {
        "id": request_id,
        "language": language,
        "intent": intent,
        "risk_level": risk_level,
        "route_to": route_to,
        "status": status,
        "outcome": outcome,
        "action_href": "/parent_dashboard",
        "action_label": "Dashboard",
    }



def child_os_classify(text):
    raw = (text or "").strip()
    lower = raw.lower()
    lang = child_os_detect_language(raw)

    red_words = ["换老师", "更换老师", "停课", "停止所有", "stop all", "stop lessons", "change teacher", "switch teacher"]
    amber_money = ["续费", "renew", "package", "付款", "refund", "退课", "退费", "invoice"]
    stop_renewal_words = ["stop renew", "stop renewal", "stop auto renew", "stop auto-renew", "cancel renewal", "cancel auto renew", "cancel auto-renew", "do not renew", "don't renew", "not renew", "停止续费", "取消续费"]
    amber_schedule = ["以后都", "所有后续", "future", "recurring", "every week", "all future"]
    cancel_words = ["取消", "请假", "缺席", "cancel", "absence", "absent", "miss class"]
    reschedule_words = ["改课", "调课", "换时间", "reschedule", "move lesson", "change time"]
    balance_words = [
        "还剩", "几节", "课次", "余额",
        "balance", "lessons left", "lesson left", "classes left", "class left",
        "how many lessons", "how many lesson", "how many classes", "how many class",
        "remaining lessons", "remaining lesson", "lessons remaining", "lesson remaining",
    ]
    reminder_words = ["提醒", "下一节", "下节课", "什么时候上课", "reminder", "next lesson", "when is"]
    receipt_words = ["收据", "receipt"]
    trial_words = ["trial", "try lesson", "try a class", "book a trial", "schedule a trial", "试课", "体验课", "试听"]

    def is_balance_question():
        if any(w in lower or w in raw for w in balance_words):
            return True
        asks_count = any(w in lower for w in ["how many", "how much", "number of", "left", "remaining"])
        mentions_lesson = any(w in lower for w in ["lesson", "lessons", "class", "classes", "package"])
        return asks_count and mentions_lesson

    if any(w in lower or w in raw for w in trial_words):
        return lang, "trial_request", "teal", "auto"
    if any(w in lower or w in raw for w in red_words):
        return lang, "owner_only", "red", "owner"
    if any(w in lower or w in raw for w in stop_renewal_words):
        return lang, "stop_renewal", "amber", "owner"
    if any(w in lower or w in raw for w in amber_money):
        return lang, "renewal_or_money", "amber", "owner"
    if any(w in lower or w in raw for w in amber_schedule):
        return lang, "reschedule_future", "amber", "teacher"
    if any(w in lower or w in raw for w in cancel_words):
        return lang, "cancel_once", "teal", "auto"
    if any(w in lower or w in raw for w in reschedule_words):
        return lang, "reschedule_once", "teal", "auto"
    if is_balance_question():
        return lang, "balance_query", "teal", "auto"
    if any(w in lower or w in raw for w in reminder_words):
        return lang, "lesson_reminder", "teal", "auto"
    if any(w in lower or w in raw for w in receipt_words):
        return lang, "receipt", "teal", "auto"
    return lang, "general", "teal", "auto"


def create_child_os_request(parent_id, parent_name, student_name, request_text, language, intent, risk_level, route_to, status, outcome, related_schedule_id=None):
    ensure_child_os_schema()
    now = datetime.now().strftime("%Y-%m-%d %H:%M")
    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    cursor.execute("""
    INSERT INTO child_os_requests (
        parent_id,
        parent_name,
        student_name,
        request_text,
        language,
        intent,
        risk_level,
        route_to,
        status,
        outcome,
        related_schedule_id,
        owner_status,
        created_at,
        updated_at
    )
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'watching', ?, ?)
    """, (
        parent_id,
        parent_name,
        student_name,
        request_text,
        language,
        intent,
        risk_level,
        route_to,
        status,
        outcome,
        related_schedule_id,
        now,
        now
    ))
    request_id = cursor.lastrowid
    conn.commit()
    conn.close()
    return request_id


def child_os_next_lesson(cursor, student_name):
    today = date.today().strftime("%Y-%m-%d")
    cursor.execute("""
    SELECT id, lesson_date, lesson_time, teacher, classroom, COALESCE(duration, 30), COALESCE(status, 'scheduled')
    FROM schedule
    WHERE student_name = ?
    AND lesson_date >= ?
    AND (status IS NULL OR status = '' OR status = 'scheduled')
    ORDER BY lesson_date, lesson_time
    LIMIT 1
    """, (student_name, today))
    return cursor.fetchone()


def handle_child_os_request(parent_id, parent_name, student_name, request_text):
    ensure_child_os_schema()
    lang, intent, risk_level, route_to = child_os_classify(request_text)

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    cursor.execute("SELECT lessons_left FROM students WHERE name = ?", (student_name,))
    student = cursor.fetchone()
    lessons_left = student[0] if student else 0
    next_lesson = child_os_next_lesson(cursor, student_name)
    conn.close()

    response_lang = "en"
    status = "logged"
    outcome = child_os_copy(response_lang, "fallback")
    related_schedule_id = None
    action_href = "/parent_dashboard"
    action_label = "Dashboard"

    if intent == "balance_query":
        key = "low_balance" if float(lessons_left or 0) <= 2 else "balance"
        outcome = child_os_copy(response_lang, key, student=student_name, lessons_left=lessons_left)
        status = "executed"
        action_href = "/parent_billing" if float(lessons_left or 0) <= 2 else "/parent_dashboard"
        action_label = "Renew / Billing"
    elif intent == "lesson_reminder":
        if next_lesson:
            related_schedule_id = next_lesson[0]
            outcome = child_os_copy(
                response_lang,
                "reminder",
                date=next_lesson[1],
                time=format_lesson_time_range(next_lesson[2], next_lesson[5]),
                teacher=next_lesson[3] or "",
                room=next_lesson[4] or ""
            )
        else:
            outcome = child_os_copy(response_lang, "no_lesson")
        status = "executed"
    elif intent == "cancel_once":
        if next_lesson:
            related_schedule_id = next_lesson[0]
            cancel_status = get_parent_cancel_status(next_lesson[1], next_lesson[2])
            result = apply_lesson_status(
                next_lesson[0],
                cancel_status,
                actor="child_os_agent",
                reason=request_text,
                allowed_student_name=student_name
            )
            if result["ok"]:
                status = "executed"
                outcome = child_os_copy(
                    response_lang,
                    "cancel_done",
                    student=student_name,
                    date=next_lesson[1],
                    time=next_lesson[2],
                    status=result["status"]
                )
                log_parent_activity(parent_id, student_name, "child_os_cancel", outcome, next_lesson[0])
            else:
                status = "needs_owner"
                risk_level = "amber"
                route_to = "owner"
                outcome = result["error"]
        else:
            status = "executed"
            outcome = child_os_copy(response_lang, "no_lesson")
    elif intent == "reschedule_once":
        status = "guided"
        outcome = child_os_copy(response_lang, "reschedule_once")
        action_href = "/parent_reschedule"
        action_label = "Choose new time"
    elif intent == "receipt":
        status = "guided"
        outcome = child_os_copy(response_lang, "receipt")
        action_href = "/parent_billing"
        action_label = "Billing / Receipts"
    elif intent == "trial_request":
        status = "guided"
        outcome = "Sure — I can help you request a trial for another child or another instrument. Please open the trial request form, and I’ll link it to your family account."
        action_href = "/trial?from_parent_app=1"
        action_label = "Open trial request form"
    elif intent == "stop_renewal":
        status = "needs_confirmation"
        outcome = "Got it. I’ll check this with the studio/admin team before making any billing changes. We’ll reply after it is confirmed."
        action_href = "/parent_billing"
        action_label = "Billing"
    elif risk_level == "amber":
        status = "needs_confirmation"
        outcome = child_os_copy(response_lang, "amber")
        action_href = "/parent_billing" if intent == "renewal_or_money" else "/parent_reschedule"
        action_label = "Open form"
    elif risk_level == "red":
        status = "owner_only"
        outcome = child_os_copy(response_lang, "red")

    request_id = create_child_os_request(
        parent_id,
        parent_name,
        student_name,
        request_text,
        lang,
        intent,
        risk_level,
        route_to,
        status,
        outcome,
        related_schedule_id
    )

    create_notification(
        "owner",
        "owner",
        "Child OS request",
        f"{risk_level.upper()} · {intent} · {student_name}: {request_text}",
        "/owner_child_os"
    )

    return {
        "id": request_id,
        "language": lang,
        "intent": intent,
        "risk_level": risk_level,
        "route_to": route_to,
        "status": status,
        "outcome": outcome,
        "action_href": action_href,
        "action_label": action_label,
    }


def get_or_create_message_thread(subject, student_name=None, parent_id=None, teacher_name=None, thread_type="general", related_type=None, related_id=None, participants=None, is_group=0, owner_observer=1):
    ensure_v29_schema()

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()

    if related_type and related_id:
        cursor.execute("""
        SELECT id
        FROM message_threads
        WHERE related_type = ?
        AND related_id = ?
        LIMIT 1
        """, (related_type, related_id))
        existing = cursor.fetchone()

        if existing:
            sync_thread_default_participants(cursor, existing[0], parent_id, teacher_name, owner_observer=owner_observer)
            if participants:
                for p in participants:
                    ensure_message_participant(cursor, existing[0], p["role"], p["key"], p.get("display_name"), p.get("is_observer", 0))
            conn.commit()
            conn.close()
            return existing[0]

    now = datetime.now().strftime("%Y-%m-%d %H:%M")

    cursor.execute("""
    INSERT INTO message_threads (
        subject,
        student_name,
        parent_id,
        teacher_name,
        thread_type,
        is_group,
        owner_observer,
        related_type,
        related_id,
        status,
        created_at,
        updated_at
    )
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    """, (
        subject,
        student_name,
        parent_id,
        teacher_name,
        thread_type,
        1 if is_group else 0,
        1 if owner_observer else 0,
        related_type,
        related_id,
        "open",
        now,
        now
    ))

    thread_id = cursor.lastrowid
    sync_thread_default_participants(cursor, thread_id, parent_id, teacher_name, owner_observer=owner_observer)
    if participants:
        for p in participants:
            ensure_message_participant(cursor, thread_id, p["role"], p["key"], p.get("display_name"), p.get("is_observer", 0))
    conn.commit()
    conn.close()

    return thread_id


def add_message(thread_id, sender_role, sender_name, recipient_role, body):
    ensure_v29_schema()

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    now = datetime.now().strftime("%Y-%m-%d %H:%M")

    cursor.execute("""
    INSERT INTO messages (
        thread_id,
        sender_role,
        sender_name,
        recipient_role,
        body,
        channel,
        created_at
    )
    VALUES (?, ?, ?, ?, ?, ?, ?)
    """, (
        thread_id,
        sender_role,
        sender_name,
        recipient_role,
        body,
        "in_app",
        now
    ))

    message_id = cursor.lastrowid

    cursor.execute("""
    UPDATE message_threads
    SET updated_at = ?
    WHERE id = ?
    """, (now, thread_id))

    conn.commit()
    conn.close()

    return message_id


def safe_upload_filename(filename):
    safe = ""
    for ch in filename:
        if ch.isalnum() or ch in ("-", "_", "."):
            safe += ch
        else:
            safe += "_"
    return safe or "attachment"


ALLOWED_UPLOAD_MIME_TYPES = {
    "image/jpeg",
    "image/png",
    "image/gif",
    "image/webp",
    "application/pdf",
    "text/plain",
    "application/msword",
    "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
}


def save_message_attachments(message_id, files):
    ensure_v29_schema()

    if not files:
        return

    os.makedirs(HMUSIC_UPLOAD_DIR, exist_ok=True)

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    now = datetime.now().strftime("%Y-%m-%d %H:%M")

    for file in files:
        if not file or not file.filename:
            continue
        if file.mimetype not in ALLOWED_UPLOAD_MIME_TYPES:
            continue

        original_filename = file.filename
        safe_name = safe_upload_filename(original_filename)
        stored_filename = f"{message_id}_{datetime.now().strftime('%Y%m%d%H%M%S%f')}_{safe_name}"
        file_path = os.path.join(HMUSIC_UPLOAD_DIR, stored_filename)
        file.save(file_path)
        file_size = os.path.getsize(file_path)

        cursor.execute("""
        INSERT INTO message_attachments (
            message_id,
            original_filename,
            stored_filename,
            mime_type,
            file_size,
            created_at
        )
        VALUES (?, ?, ?, ?, ?, ?)
        """, (
            message_id,
            original_filename,
            stored_filename,
            file.mimetype,
            file_size,
            now
        ))

    conn.commit()
    conn.close()


def create_notification(user_role, user_key, title, body, link_url, related_type=None, related_id=None, queue_delivery=True):
    ensure_v29_schema()

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    existing_id = None
    if related_type and related_id is not None:
        cursor.execute("""
        SELECT id
        FROM notifications
        WHERE user_role = ?
        AND user_key = ?
        AND title = ?
        AND related_type = ?
        AND related_id = ?
        ORDER BY id DESC
        LIMIT 1
        """, (
            user_role,
            str(user_key),
            title,
            related_type,
            int(related_id)
        ))
        existing = cursor.fetchone()
        existing_id = existing[0] if existing else None

    if existing_id:
        cursor.execute("""
        UPDATE notifications
        SET body = ?,
            link_url = ?,
            read_at = NULL,
            created_at = ?
        WHERE id = ?
        """, (
            body,
            link_url,
            datetime.now().strftime("%Y-%m-%d %H:%M"),
            existing_id
        ))
        conn.commit()
        conn.close()
        return existing_id

    cursor.execute("""
    INSERT INTO notifications (
        user_role,
        user_key,
        title,
        body,
        link_url,
        related_type,
        related_id,
        created_at
    )
    VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    """, (
        user_role,
        str(user_key),
        title,
        body,
        link_url,
        related_type,
        related_id,
        datetime.now().strftime("%Y-%m-%d %H:%M")
    ))
    notification_id = cursor.lastrowid

    conn.commit()
    conn.close()

    if not queue_delivery:
        return notification_id

    queue_notification_delivery(
        user_role,
        user_key,
        title,
        body,
        link_url,
        "push",
        related_type=related_type,
        related_id=related_id
    )
    queue_notification_delivery(
        user_role,
        user_key,
        title,
        body,
        link_url,
        "email",
        related_type=related_type,
        related_id=related_id
    )
    if should_queue_sms_notification(title):
        queue_sms_if_available(
            user_role,
            user_key,
            title,
            body,
            link_url,
            related_type=related_type,
            related_id=related_id
        )
    return notification_id


def ensure_v33_schema():
    ensure_v29_schema()

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()

    cursor.execute("""
    CREATE TABLE IF NOT EXISTS notification_delivery_queue (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_role TEXT,
        user_key TEXT,
        channel TEXT,
        destination TEXT,
        title TEXT,
        body TEXT,
        link_url TEXT,
        related_type TEXT,
        related_id INTEGER,
        status TEXT DEFAULT 'pending',
        provider_response TEXT,
        created_at TEXT,
        sent_at TEXT
    )
    """)

    conn.commit()
    conn.close()


def should_queue_sms_notification(title):
    title = (title or "").lower()
    important_keywords = [
        "message",
        "lesson reminder",
        "practice reminder",
        "payment",
        "invoice",
        "reschedule",
        "student setup"
    ]
    return any(keyword in title for keyword in important_keywords)


def hmusic_is_real_email(email):
    email = (email or "").strip().lower()
    if not email or email.count("@") != 1 or any(ch.isspace() for ch in email):
        return False
    local_part, domain = email.rsplit("@", 1)
    if not local_part or not domain or "." not in domain:
        return False
    placeholder_domains = {"hmusic.local", "example.com", "example.org", "example.net", "test.com"}
    if domain in placeholder_domains or domain.endswith(".local"):
        return False
    if not re.match(r"^[a-z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-z0-9-]+(?:\.[a-z0-9-]+)+$", email):
        return False
    tld = domain.rsplit(".", 1)[-1]
    return len(tld) >= 2 and tld.isalpha()


def hmusic_normalize_email(email):
    return (email or "").strip().lower()


def hmusic_ensure_email_suppression_schema(cursor):
    cursor.execute("""
    CREATE TABLE IF NOT EXISTS email_suppression (
        email TEXT PRIMARY KEY COLLATE NOCASE,
        reason TEXT,
        source TEXT,
        created_at TEXT
    )
    """)


def hmusic_seed_known_bounced_emails(cursor):
    known_bounced = {"mailiangli@gmail.com"}
    env_bounced = os.environ.get("HMUSIC_SUPPRESSED_EMAILS", "")
    known_bounced.update(email.strip().lower() for email in env_bounced.split(",") if email.strip())
    if not known_bounced:
        return
    hmusic_ensure_email_suppression_schema(cursor)
    now = datetime.now().strftime("%Y-%m-%d %H:%M")
    cursor.executemany("""
    INSERT OR IGNORE INTO email_suppression (email, reason, source, created_at)
    VALUES (?, ?, ?, ?)
    """, [
        (email, "Known Gmail hard bounce; owner must verify the correct parent email.", "known_bounce_seed", now)
        for email in sorted(known_bounced)
    ])


def hmusic_is_email_suppressed(cursor, email):
    normalized = hmusic_normalize_email(email)
    if not normalized:
        return True
    hmusic_ensure_email_suppression_schema(cursor)
    hmusic_seed_known_bounced_emails(cursor)
    cursor.execute("SELECT 1 FROM email_suppression WHERE email = ? LIMIT 1", (normalized,))
    return cursor.fetchone() is not None


def hmusic_suppress_email(cursor, email, reason, source):
    normalized = hmusic_normalize_email(email)
    if not normalized:
        return False
    hmusic_ensure_email_suppression_schema(cursor)
    cursor.execute("""
    INSERT INTO email_suppression (email, reason, source, created_at)
    VALUES (?, ?, ?, ?)
    ON CONFLICT(email) DO UPDATE SET
        reason = excluded.reason,
        source = excluded.source,
        created_at = excluded.created_at
    """, (
        normalized,
        reason or "Suppressed after delivery failure.",
        source or "email_delivery",
        datetime.now().strftime("%Y-%m-%d %H:%M")
    ))
    return True


def hmusic_is_hard_bounce_response(provider_response):
    text = (provider_response or "").lower()
    hard_bounce_markers = [
        "550 5.1.1",
        "nosuchuser",
        "address not found",
        "does not exist",
        "couldn't be found",
        "domain name not found",
        "badrcptdomain",
        "recipient address rejected",
    ]
    return any(marker in text for marker in hard_bounce_markers)


def hmusic_scan_failed_email_suppressions(cursor):
    hmusic_ensure_email_suppression_schema(cursor)
    hmusic_seed_known_bounced_emails(cursor)
    cursor.execute("""
    SELECT destination, provider_response
    FROM notification_delivery_queue
    WHERE channel = 'email'
    AND status = 'failed'
    AND COALESCE(destination, '') != ''
    AND COALESCE(provider_response, '') != ''
    """)
    suppressed = 0
    for destination, provider_response in cursor.fetchall():
        if hmusic_is_hard_bounce_response(provider_response):
            suppressed += int(hmusic_suppress_email(
                cursor,
                destination,
                provider_response[:240],
                "notification_delivery_queue"
            ))
    return suppressed


def get_parent_lesson_reminder_email(cursor, parent_id, schedule_id):
    hmusic_scan_failed_email_suppressions(cursor)
    candidates = []
    if schedule_id:
        cursor.execute("""
        SELECT COALESCE(st.parent_email, '')
        FROM schedule s
        LEFT JOIN students st ON st.name = s.student_name
        WHERE s.id = ?
        LIMIT 1
        """, (schedule_id,))
        row = cursor.fetchone()
        if row:
            candidates.append(row[0])

    cursor.execute("SELECT email FROM parent_profiles WHERE id = ?", (parent_id,))
    row = cursor.fetchone()
    if row:
        candidates.append(row[0])

    seen = set()
    for candidate in candidates:
        normalized = hmusic_normalize_email(candidate)
        if normalized in seen:
            continue
        seen.add(normalized)
        if hmusic_is_real_email(normalized) and not hmusic_is_email_suppressed(cursor, normalized):
            return normalized
    return None


def get_notification_destination(cursor, user_role, user_key, channel, related_type=None, related_id=None):
    if channel == "push":
        return f"{user_role}:{user_key}"

    if channel == "email":
        if user_role == "parent":
            if related_type == "lesson_reminder":
                return get_parent_lesson_reminder_email(cursor, user_key, related_id)
            cursor.execute("SELECT email FROM parent_profiles WHERE id = ?", (user_key,))
            row = cursor.fetchone()
            return row[0] if row and hmusic_is_real_email(row[0]) and not hmusic_is_email_suppressed(cursor, row[0]) else None
        if user_role == "teacher":
            cursor.execute("SELECT email FROM teachers WHERE teacher_name = ?", (user_key,))
            row = cursor.fetchone()
            return row[0] if row and hmusic_is_real_email(row[0]) and not hmusic_is_email_suppressed(cursor, row[0]) else None
        if user_role == "owner":
            cursor.execute("SELECT value FROM settings WHERE key = 'owner_email'")
            row = cursor.fetchone()
            return row[0] if row and hmusic_is_real_email(row[0]) and not hmusic_is_email_suppressed(cursor, row[0]) else None

    if channel == "sms":
        if user_role == "parent":
            cursor.execute("SELECT phone FROM parent_profiles WHERE id = ?", (user_key,))
            row = cursor.fetchone()
            return row[0] if row and row[0] else None
        if user_role == "teacher":
            cursor.execute("SELECT phone FROM teachers WHERE teacher_name = ?", (user_key,))
            row = cursor.fetchone()
            return row[0] if row and row[0] else None
        if user_role == "owner":
            cursor.execute("SELECT value FROM settings WHERE key = 'owner_phone'")
            row = cursor.fetchone()
            return row[0] if row and row[0] else None

    return None


def queue_notification_delivery(user_role, user_key, title, body, link_url, channel="push", related_type=None, related_id=None):
    ensure_v33_schema()

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    destination = get_notification_destination(cursor, user_role, user_key, channel, related_type, related_id)

    if not destination:
        conn.close()
        return None
    if channel == "email":
        destination = hmusic_normalize_email(destination)
        if not hmusic_is_real_email(destination) or hmusic_is_email_suppressed(cursor, destination):
            conn.close()
            return None

    cursor.execute("""
    SELECT id
    FROM notification_delivery_queue
    WHERE user_role = ?
    AND user_key = ?
    AND channel = ?
    AND destination = ?
    AND title = ?
    AND COALESCE(related_type, '') = COALESCE(?, '')
    AND COALESCE(related_id, -1) = COALESCE(?, -1)
    AND status IN ('pending', 'sent')
    ORDER BY id DESC
    LIMIT 1
    """, (user_role, str(user_key), channel, destination, title, related_type, related_id))
    existing = cursor.fetchone()
    if existing:
        conn.close()
        return existing[0]

    cursor.execute("""
    INSERT INTO notification_delivery_queue (
        user_role,
        user_key,
        channel,
        destination,
        title,
        body,
        link_url,
        related_type,
        related_id,
        status,
        created_at
    )
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    """, (
        user_role,
        str(user_key),
        channel,
        destination,
        title,
        body,
        link_url,
        related_type,
        related_id,
        "pending",
        datetime.now().strftime("%Y-%m-%d %H:%M")
    ))

    queue_id = cursor.lastrowid
    conn.commit()
    conn.close()
    return queue_id


def queue_sms_if_available(user_role, user_key, title, body, link_url, related_type=None, related_id=None):
    return queue_notification_delivery(
        user_role,
        user_key,
        title,
        body,
        link_url,
        "sms",
        related_type=related_type,
        related_id=related_id
    )


def queue_direct_delivery(channel, destination, title, body, link_url, related_type=None, related_id=None):
    ensure_v33_schema()
    destination = (destination or "").strip()
    if not destination:
        return None
    if channel == "email" and not hmusic_is_real_email(destination):
        return None

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    if channel == "email":
        destination = hmusic_normalize_email(destination)
        if hmusic_is_email_suppressed(cursor, destination):
            conn.close()
            return None
    cursor.execute("""
    SELECT id
    FROM notification_delivery_queue
    WHERE channel = ?
    AND destination = ?
    AND related_type = ?
    AND related_id = ?
    AND title = ?
    AND status IN ('pending', 'sent')
    LIMIT 1
    """, (channel, destination, related_type, related_id, title))
    existing = cursor.fetchone()
    if existing:
        conn.close()
        return existing[0]

    cursor.execute("""
    INSERT INTO notification_delivery_queue (
        user_role,
        user_key,
        channel,
        destination,
        title,
        body,
        link_url,
        related_type,
        related_id,
        status,
        created_at
    )
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'pending', ?)
    """, (
        "trial_parent",
        destination,
        channel,
        destination,
        title,
        body,
        link_url,
        related_type,
        related_id,
        datetime.now().strftime("%Y-%m-%d %H:%M")
    ))
    queue_id = cursor.lastrowid
    conn.commit()
    conn.close()
    return queue_id


def send_email_delivery(destination, title, body, link_url):
    if not hmusic_is_real_email(destination):
        return False, "Email not sent: destination is missing or is an internal placeholder address."
    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    suppressed = hmusic_is_email_suppressed(cursor, destination)
    conn.close()
    if suppressed:
        return False, "Email not sent: address is suppressed after a previous delivery failure."

    smtp_host = os.environ.get("HMUSIC_SMTP_HOST")
    smtp_port = int(os.environ.get("HMUSIC_SMTP_PORT", "587"))
    smtp_user = os.environ.get("HMUSIC_SMTP_USER")
    smtp_password = os.environ.get("HMUSIC_SMTP_PASSWORD")
    from_email = os.environ.get("HMUSIC_FROM_EMAIL") or smtp_user

    if not smtp_host or not smtp_user or not smtp_password or not from_email:
        return False, "SMTP not configured. Add HMUSIC_SMTP_HOST, HMUSIC_SMTP_USER, HMUSIC_SMTP_PASSWORD, and HMUSIC_FROM_EMAIL."

    message = EmailMessage()
    message["Subject"] = title or "H-Music Notification"
    message["From"] = from_email
    message["To"] = destination
    footer = f"\n\nOpen: {link_url}\n\nH-Music" if link_url else "\n\nH-Music"
    message.set_content(f"{body or ''}{footer}")

    with smtplib.SMTP(smtp_host, smtp_port) as server:
        server.starttls()
        server.login(smtp_user, smtp_password)
        server.send_message(message)

    return True, "Email sent via SMTP."


def smtp_config_status():
    required = [
        "HMUSIC_SMTP_HOST",
        "HMUSIC_SMTP_USER",
        "HMUSIC_SMTP_PASSWORD",
        "HMUSIC_FROM_EMAIL",
    ]
    missing = [name for name in required if not os.environ.get(name)]
    return len(missing) == 0, missing


def mark_delivery_status(queue_id, status, provider_response=None):
    ensure_v33_schema()
    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    cursor.execute("SELECT destination FROM notification_delivery_queue WHERE id = ?", (queue_id,))
    row = cursor.fetchone()
    cursor.execute("""
    UPDATE notification_delivery_queue
    SET status = ?,
        provider_response = ?,
        sent_at = CASE WHEN ? = 'sent' THEN ? ELSE sent_at END
    WHERE id = ?
    """, (
        status,
        provider_response,
        status,
        datetime.now().strftime("%Y-%m-%d %H:%M"),
        queue_id
    ))
    if row and status == "failed" and hmusic_is_hard_bounce_response(provider_response):
        hmusic_suppress_email(cursor, row[0], provider_response[:240], f"queue:{queue_id}")
    conn.commit()
    conn.close()


def send_queued_email_now(queue_id):
    ensure_v33_schema()
    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    cursor.execute("""
    SELECT channel, destination, title, body, link_url, status
    FROM notification_delivery_queue
    WHERE id = ?
    """, (queue_id,))
    row = cursor.fetchone()
    conn.close()

    if not row:
        return False, "Queue item not found."

    channel, destination, title, body, link_url, status = row
    if channel != "email":
        return False, "Queue item is not an email."
    if status != "pending":
        return False, f"Queue item already {status}."

    try:
        sent, response = send_email_delivery(destination, title, body, link_url)
    except Exception as exc:
        sent = False
        response = f"Email send failed: {exc}"

    mark_delivery_status(queue_id, "sent" if sent else "failed", response)
    return sent, response


def send_parent_email_notice_now(parent_id, title, body, link_url, related_type=None, related_id=None):
    if not parent_id:
        return None

    ensure_v33_schema()
    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    cursor.execute("SELECT email FROM parent_profiles WHERE id = ?", (parent_id,))
    row = cursor.fetchone()
    conn.close()

    if not row or not hmusic_is_real_email(row[0]):
        return None

    queue_id = queue_direct_delivery(
        "email",
        row[0],
        title,
        body,
        link_url,
        related_type=related_type,
        related_id=related_id
    )
    if queue_id:
        send_queued_email_now(queue_id)
    return queue_id


def queue_parent_lesson_reminder(parent_id, title, body, link_url, schedule_id):
    parent_key = str(parent_id)
    create_notification(
        "parent",
        parent_key,
        title,
        body,
        link_url,
        related_type="lesson_reminder",
        related_id=schedule_id,
        queue_delivery=False
    )

    email_queue_id = queue_notification_delivery(
        "parent",
        parent_key,
        title,
        body,
        link_url,
        "email",
        related_type="lesson_reminder",
        related_id=schedule_id
    )
    if email_queue_id:
        send_queued_email_now(email_queue_id)
        return email_queue_id

    return queue_sms_if_available(
        "parent",
        parent_key,
        title,
        body,
        link_url,
        related_type="lesson_reminder",
        related_id=schedule_id
    )


def hmusic_public_app_url(path="/parent_dashboard"):
    base = (os.environ.get("HMUSIC_PUBLIC_URL") or "https://hmusic-crm.onrender.com").rstrip("/")
    clean_path = "/" + str(path or "").lstrip("/")
    return base + clean_path


def hmusic_lesson_reminder_date_label(lesson_date):
    try:
        parsed = datetime.strptime(str(lesson_date or ""), "%Y-%m-%d")
        return parsed.strftime("%A, %B %-d, %Y")
    except Exception:
        return str(lesson_date or "Date TBD")


def hmusic_lesson_reminder_time_label(lesson_time):
    return format_display_time(lesson_time) if lesson_time else "Time TBD"


def hmusic_lesson_reminder_title(student_name, lesson_date, lesson_time):
    name = str(student_name or "Student").strip() or "Student"
    try:
        date_part = datetime.strptime(str(lesson_date or ""), "%Y-%m-%d").strftime("%b %-d")
    except Exception:
        date_part = str(lesson_date or "Date TBD")
    return f"H-Music Lesson Reminder: {name} - {date_part} at {hmusic_lesson_reminder_time_label(lesson_time)}"


def hmusic_lesson_reminder_body(student_name, lesson_date, lesson_time, teacher, location_name, location_address=""):
    name = str(student_name or "your student").strip() or "your student"
    first_name = name.split()[0] if name else "your student"
    location = str(location_name or "H-Music Studio").strip() or "H-Music Studio"
    address = str(location_address or "").strip()
    address_line = f"\nAddress: {address}" if address else ""
    return f"""Hi,

This is a reminder that {first_name} has a lesson tomorrow.

Student: {name}
Date: {hmusic_lesson_reminder_date_label(lesson_date)}
Time: {hmusic_lesson_reminder_time_label(lesson_time)}
Teacher: {teacher or 'H-Music teacher'}
Location: {location}{address_line}

Please open the H-Music Parent App to view schedule details.

Thank you,
H-Music
"""


def create_lesson_reminders_for_date(target_date):
    ensure_v33_schema()
    ensure_parent_portal_feature_schema()
    ensure_location_room_schema()

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()

    cursor.execute("""
    SELECT
        s.id,
        s.student_name,
        s.teacher,
        s.lesson_date,
        s.lesson_time,
        COALESCE(l.location_name, s.location, 'H-Music Studio'),
        COALESCE(l.address, '')
    FROM schedule s
    LEFT JOIN studio_locations l
        ON s.location_id = l.id
    WHERE lesson_date = ?
    AND COALESCE(s.status, 'scheduled') = 'scheduled'
    AND COALESCE(s.parent_lesson_reminder_enabled, 0) = 1
    ORDER BY s.lesson_time
    """, (target_date,))
    lessons = cursor.fetchall()

    created = 0
    for lesson in lessons:
        schedule_id, student_name, teacher, lesson_date, lesson_time, location_name, location_address = lesson

        cursor.execute("""
        SELECT parent_id
        FROM parent_students
        WHERE student_name = ?
        AND active = 1
        """, (student_name,))
        parent_rows = cursor.fetchall()

        for parent_row in parent_rows:
            parent_id = parent_row[0]
            cursor.execute("""
            SELECT COALESCE(lesson_reminders, 1)
            FROM parent_notification_preferences
            WHERE parent_id = ?
            """, (parent_id,))
            pref_row = cursor.fetchone()
            if pref_row and int(pref_row[0] or 0) != 1:
                continue

            cursor.execute("""
            SELECT id
            FROM notification_delivery_queue
            WHERE user_role = 'parent'
            AND user_key = ?
            AND related_type = 'lesson_reminder'
            AND related_id = ?
            AND channel IN ('email', 'sms')
            AND status IN ('pending', 'sent')
            LIMIT 1
            """, (str(parent_id), schedule_id))
            existing = cursor.fetchone()
            if existing:
                continue

            title = hmusic_lesson_reminder_title(student_name, lesson_date, lesson_time)
            body = hmusic_lesson_reminder_body(student_name, lesson_date, lesson_time, teacher, location_name, location_address)
            link = hmusic_public_app_url("/parent_dashboard")
            conn.commit()
            queue_id = queue_parent_lesson_reminder(parent_id, title, body, link, schedule_id)
            if queue_id:
                created += 1

    conn.close()
    return created


def maybe_run_daily_lesson_reminders():
    if os.environ.get("HMUSIC_DISABLE_AUTO_REMINDERS") == "1":
        return

    today = date.today().isoformat()
    target_date = (date.today() + timedelta(days=1)).strftime("%Y-%m-%d")

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    cursor.execute("SELECT value FROM settings WHERE key = 'last_auto_lesson_reminder_date'")
    row = cursor.fetchone()
    if row and row[0] == today:
        conn.close()
        return

    cursor.execute("""
    INSERT OR REPLACE INTO settings (key, value)
    VALUES ('last_auto_lesson_reminder_date', ?)
    """, (today,))
    cursor.execute("""
    INSERT OR REPLACE INTO settings (key, value)
    VALUES ('last_auto_lesson_reminder_target_date', ?)
    """, (target_date,))
    conn.commit()
    conn.close()

    try:
        parent_created = create_lesson_reminders_for_date(target_date)
        teacher_created = create_teacher_lesson_reminders_for_date(target_date)
        conn = sqlite3.connect("hmusic.db")
        cursor = conn.cursor()
        cursor.execute("""
        INSERT OR REPLACE INTO settings (key, value)
        VALUES ('last_auto_lesson_reminder_result', ?)
        """, (f"{datetime.now().strftime('%Y-%m-%d %H:%M')} | {target_date} | parents {parent_created} | teachers {teacher_created}",))
        conn.commit()
        conn.close()
    except Exception as exc:
        print(f"[reminders] automatic lesson reminder run failed: {exc}")


def create_autopay_due_notifications(target_date=None):
    ensure_v321_schema()
    ensure_billing_schema()
    target_date = target_date or date.today().strftime("%Y-%m-%d")

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    cursor.execute("""
    SELECT
        e.id,
        e.student_name,
        e.autopay_pending_invoice_id,
        e.autopay_charge_due_date,
        i.amount,
        i.status
    FROM enrollments e
    JOIN invoices i
        ON e.autopay_pending_invoice_id = i.id
    WHERE e.auto_renew_enabled = 1
    AND e.autopay_charge_status = 'pending'
    AND e.autopay_charge_due_date <= ?
    AND COALESCE(i.status, 'unpaid') != 'paid'
    ORDER BY e.autopay_charge_due_date, e.student_name
    """, (target_date,))
    rows = cursor.fetchall()

    processed = 0
    for row in rows:
        enrollment_id, student_name, invoice_id, due_date, amount, invoice_status = row
        parent_id = get_primary_parent_for_student(cursor, student_name)

        def mark_for_review(status, invoice_autopay_status, parent_title, parent_body, owner_title, owner_body):
            now = datetime.now().strftime("%Y-%m-%d %H:%M")
            cursor.execute("""
            UPDATE enrollments
            SET autopay_charge_status = ?,
                updated_at = ?
            WHERE id = ?
            """, (status, now, enrollment_id))
            cursor.execute("""
            UPDATE invoices
            SET autopay_status = ?
            WHERE id = ?
            AND status != 'paid'
            """, (invoice_autopay_status, invoice_id))
            conn.commit()

            if parent_id and parent_title:
                create_notification(
                    "parent",
                    str(parent_id),
                    parent_title,
                    parent_body,
                    f"/parent_invoice/{invoice_id}",
                    related_type="invoice",
                    related_id=invoice_id
                )
            create_notification(
                "owner",
                "owner",
                owner_title,
                owner_body,
                f"/pay_invoice/{invoice_id}",
                related_type="invoice",
                related_id=invoice_id
            )

        if not parent_id:
            mark_for_review(
                "pending_owner_review",
                "missing_parent",
                None,
                None,
                "AutoPay needs review",
                f"{student_name}'s AutoPay invoice #{invoice_id} is due, but no linked parent was found."
            )
            processed += 1
            continue

        if not configure_stripe():
            mark_for_review(
                "pending_owner_review",
                "stripe_missing",
                "AutoPay setup needs attention",
                f"{student_name}'s next package invoice is ready, but Stripe is not configured yet.",
                "AutoPay Stripe configuration missing",
                f"{student_name}'s AutoPay invoice #{invoice_id} cannot be charged until Stripe is configured."
            )
            processed += 1
            continue

        payment_method_id, billing_autopay_enabled, saved_customer_id, billing_status = get_saved_stripe_payment_method(cursor, parent_id)
        if not payment_method_id or billing_autopay_enabled != 1:
            mark_for_review(
                "pending_owner_review",
                "needs_payment_method",
                "AutoPay payment method needed",
                f"{student_name}'s next package is ready. Please connect or confirm your bank payment method for AutoPay.",
                "AutoPay payment method missing",
                f"{student_name}'s AutoPay invoice #{invoice_id} is due, but the parent does not have a saved payment method."
            )
            processed += 1
            continue

        customer_id = get_or_create_stripe_customer(cursor, parent_id)
        conn.commit()

        if not customer_id:
            mark_for_review(
                "pending_owner_review",
                "customer_missing",
                "AutoPay setup needs attention",
                f"{student_name}'s next package is ready, but Stripe could not confirm your customer profile.",
                "AutoPay customer missing",
                f"{student_name}'s AutoPay invoice #{invoice_id} is due, but Stripe customer creation failed."
            )
            processed += 1
            continue

        if saved_customer_id and customer_id != saved_customer_id:
            now = datetime.now().strftime("%Y-%m-%d %H:%M")
            cursor.execute("""
            UPDATE parent_billing_profiles
            SET stripe_payment_method_id = NULL,
                status = 'needs_reconnect_test',
                updated_at = ?
            WHERE parent_id = ?
            """, (now, parent_id))
            conn.commit()
            mark_for_review(
                "pending_owner_review",
                "needs_payment_method",
                "Please reconnect AutoPay",
                f"{student_name}'s saved bank setup needs to be reconnected before AutoPay can run.",
                "AutoPay reconnect needed",
                f"{student_name}'s AutoPay invoice #{invoice_id} could not run because the saved Stripe customer changed."
            )
            processed += 1
            continue

        now = datetime.now().strftime("%Y-%m-%d %H:%M")
        cursor.execute("""
        UPDATE enrollments
        SET autopay_charge_status = 'processing',
            updated_at = ?
        WHERE id = ?
        """, (now, enrollment_id))
        cursor.execute("""
        UPDATE invoices
        SET status = 'stripe_processing',
            autopay_status = 'autopay_attempting'
        WHERE id = ?
        AND status != 'paid'
        """, (invoice_id,))

        conn.commit()

        try:
            payment_intent = stripe.PaymentIntent.create(
                amount=int(round(float(amount or 0) * 100)),
                currency="usd",
                customer=customer_id,
                payment_method=payment_method_id,
                confirm=True,
                off_session=True,
                description=f"H-Music AutoPay - {student_name} invoice #{invoice_id}",
                metadata={
                    "invoice_id": str(invoice_id),
                    "parent_id": str(parent_id),
                    "enrollment_id": str(enrollment_id),
                    "source": "autopay"
                }
            )
            payment_status = payment_intent.get("status")

            if payment_status == "succeeded":
                cursor.execute("""
                UPDATE enrollments
                SET autopay_charge_status = 'charged',
                    updated_at = ?
                WHERE id = ?
                """, (datetime.now().strftime("%Y-%m-%d %H:%M"), enrollment_id))
                cursor.execute("""
                UPDATE invoices
                SET stripe_payment_intent_id = ?,
                    autopay_status = 'paid_test'
                WHERE id = ?
                """, (payment_intent.get("id"), invoice_id))
                conn.commit()
                finalize_stripe_invoice_payment(
                    invoice_id,
                    payment_intent_id=payment_intent.get("id"),
                    source="autopay_due_check"
                )
                create_notification(
                    "parent",
                    str(parent_id),
                    "AutoPay processed",
                    f"{student_name}'s next package AutoPay payment of ${amount} was processed.",
                    f"/parent_invoice/{invoice_id}",
                    related_type="invoice",
                    related_id=invoice_id
                )
                create_notification(
                    "owner",
                    "owner",
                    "AutoPay processed",
                    f"{student_name}'s AutoPay invoice #{invoice_id} was charged successfully.",
                    f"/pay_invoice/{invoice_id}",
                    related_type="invoice",
                    related_id=invoice_id
                )
            elif payment_status in ("processing", "requires_capture"):
                cursor.execute("""
                UPDATE invoices
                SET stripe_payment_intent_id = ?,
                    autopay_status = ?
                WHERE id = ?
                """, (payment_intent.get("id"), payment_status, invoice_id))
                conn.commit()
                create_notification(
                    "owner",
                    "owner",
                    "AutoPay processing",
                    f"{student_name}'s AutoPay invoice #{invoice_id} is processing in Stripe.",
                    f"/pay_invoice/{invoice_id}",
                    related_type="invoice",
                    related_id=invoice_id
                )
            else:
                mark_for_review(
                    "pending_owner_review",
                    f"autopay_{payment_status}",
                    "AutoPay needs confirmation",
                    f"{student_name}'s AutoPay could not finish automatically. H-Music will review the payment.",
                    "AutoPay needs review",
                    f"{student_name}'s AutoPay invoice #{invoice_id} returned Stripe status: {payment_status}."
                )
        except Exception as exc:
            error_text = str(exc)[:240]
            mark_for_review(
                "pending_owner_review",
                "autopay_failed",
                "AutoPay needs confirmation",
                f"{student_name}'s AutoPay could not finish automatically. H-Music will review the payment.",
                "AutoPay failed",
                f"{student_name}'s AutoPay invoice #{invoice_id} failed: {error_text}"
            )

        processed += 1

    conn.close()
    return processed


def create_autopay_due_notifications_legacy(target_date=None):
    ensure_v321_schema()
    target_date = target_date or date.today().strftime("%Y-%m-%d")

    conn = sqlite3.connect("hmusic.db")
