def get_message_identity():
    if require_owner():
        return "owner", "owner"
    if require_parent():
        return "parent", str(session.get("parent_id"))
    if require_teacher():
        return "teacher", session.get("teacher_name")
    return None, None


def get_unread_message_count(viewer_role, viewer_key):
    ensure_v29_schema()

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    cursor.execute("""
    SELECT COUNT(*)
    FROM messages m
    JOIN message_participants mp
        ON mp.thread_id = m.thread_id
        AND mp.active = 1
    WHERE mp.participant_role = ?
    AND mp.participant_key = ?
    AND NOT (
        m.sender_role = ?
        AND m.sender_name = mp.display_name
    )
    AND (
        mp.last_read_at IS NULL
        OR m.created_at > mp.last_read_at
    )
    """, (viewer_role, str(viewer_key), viewer_role))
    count = cursor.fetchone()[0] or 0

    if count == 0:
        if viewer_role == "teacher":
            cursor.execute("""
            SELECT COUNT(*)
            FROM messages m
            JOIN message_threads t
                ON m.thread_id = t.id
            WHERE m.recipient_role = 'teacher'
            AND m.read_at IS NULL
            AND t.teacher_name = ?
            """, (viewer_key,))
        elif viewer_role == "parent":
            cursor.execute("""
            SELECT COUNT(*)
            FROM messages m
            JOIN message_threads t
                ON m.thread_id = t.id
            WHERE m.recipient_role = 'parent'
            AND m.read_at IS NULL
            AND t.parent_id = ?
            """, (viewer_key,))
        else:
            cursor.execute("""
            SELECT COUNT(*)
            FROM messages
            WHERE recipient_role = ?
            AND read_at IS NULL
            """, (viewer_role,))
        count = cursor.fetchone()[0] or 0

    conn.close()
    return count


def get_unread_notification_count(user_role, user_key):
    ensure_v29_schema()

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    cursor.execute("""
    SELECT COUNT(*)
    FROM notifications
    WHERE user_role = ?
    AND user_key = ?
    AND read_at IS NULL
    """, (user_role, str(user_key)))
    count = cursor.fetchone()[0] or 0
    conn.close()
    return count


def mark_notifications_read(user_role, user_key):
    ensure_v29_schema()

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    cursor.execute("""
    UPDATE notifications
    SET read_at = ?
    WHERE user_role = ?
    AND user_key = ?
    AND read_at IS NULL
    """, (
        datetime.now().strftime("%Y-%m-%d %H:%M"),
        user_role,
        str(user_key)
    ))
    conn.commit()
    conn.close()


def ensure_parent_portal_feature_schema():
    ensure_v321_schema()

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    cursor.execute("""
    CREATE TABLE IF NOT EXISTS parent_notification_preferences (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        parent_id INTEGER UNIQUE,
        lesson_reminders INTEGER DEFAULT 1,
        practice_reminders INTEGER DEFAULT 1,
        billing_alerts INTEGER DEFAULT 1,
        event_updates INTEGER DEFAULT 1,
        schedule_changes INTEGER DEFAULT 1,
        message_alerts INTEGER DEFAULT 1,
        quiet_hours_start TEXT,
        quiet_hours_end TEXT,
        updated_at TEXT
    )
    """)
    cursor.execute("""
    CREATE TABLE IF NOT EXISTS student_credit_wallets (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        student_name TEXT UNIQUE,
        service_credits REAL DEFAULT 0,
        makeup_credits REAL DEFAULT 0,
        monetary_credits REAL DEFAULT 0,
        notes TEXT,
        updated_at TEXT
    )
    """)
    cursor.execute("""
    CREATE TABLE IF NOT EXISTS parent_booking_requests (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        parent_id INTEGER,
        student_name TEXT,
        request_type TEXT,
        preferred_date TEXT,
        preferred_time TEXT,
        preferred_teacher TEXT,
        preferred_room TEXT,
        notes TEXT,
        status TEXT DEFAULT 'pending_owner_review',
        created_at TEXT,
        updated_at TEXT
    )
    """)
    cursor.execute("""
    CREATE TABLE IF NOT EXISTS guardian_invites (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        parent_id INTEGER,
        guardian_name TEXT,
        guardian_email TEXT,
        guardian_phone TEXT,
        relationship TEXT,
        status TEXT DEFAULT 'pending_owner_review',
        created_at TEXT,
        updated_at TEXT
    )
    """)
    cursor.execute("""
    CREATE TABLE IF NOT EXISTS studio_events (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        title TEXT,
        event_date TEXT,
        event_time TEXT,
        location TEXT,
        description TEXT,
        status TEXT DEFAULT 'published',
        created_at TEXT,
        updated_at TEXT
    )
    """)
    cursor.execute("""
    CREATE TABLE IF NOT EXISTS event_rsvps (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        event_id INTEGER,
        parent_id INTEGER,
        student_name TEXT,
        rsvp_status TEXT,
        notes TEXT,
        created_at TEXT,
        updated_at TEXT,
        UNIQUE(event_id, parent_id, student_name)
    )
    """)

    for table_name, column_name, column_sql in [
        ("parent_notification_preferences", "quiet_hours_start", "quiet_hours_start TEXT"),
        ("parent_notification_preferences", "quiet_hours_end", "quiet_hours_end TEXT"),
        ("student_credit_wallets", "makeup_credits", "makeup_credits REAL DEFAULT 0"),
        ("parent_booking_requests", "preferred_room", "preferred_room TEXT"),
        ("parent_booking_requests", "owner_note", "owner_note TEXT"),
        ("parent_booking_requests", "confirmed_schedule_id", "confirmed_schedule_id INTEGER"),
        ("guardian_invites", "guardian_phone", "guardian_phone TEXT"),
        ("studio_events", "status", "status TEXT DEFAULT 'published'"),
        ("event_rsvps", "notes", "notes TEXT"),
    ]:
        add_column_if_missing(cursor, table_name, column_name, column_sql)

    conn.commit()
    conn.close()


