def ensure_billing_schema():
    ensure_v27_schema()

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    cursor.execute("""
    CREATE TABLE IF NOT EXISTS parent_billing_profiles (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        parent_id INTEGER UNIQUE,
        stripe_customer_id TEXT,
        stripe_setup_session_id TEXT,
        stripe_setup_intent_id TEXT,
        stripe_payment_method_id TEXT,
        autopay_enabled INTEGER DEFAULT 0,
        ach_enabled INTEGER DEFAULT 0,
        status TEXT DEFAULT 'not_connected',
        notes TEXT,
        created_at TEXT,
        updated_at TEXT
    )
    """)

    def add_column_if_missing(table_name, column_name, column_sql):
        cursor.execute(f"PRAGMA table_info({table_name})")
        columns = [row[1] for row in cursor.fetchall()]
        if column_name not in columns:
            cursor.execute(f"ALTER TABLE {table_name} ADD COLUMN {column_sql}")

    add_column_if_missing("parent_billing_profiles", "stripe_setup_session_id", "stripe_setup_session_id TEXT")
    add_column_if_missing("parent_billing_profiles", "stripe_setup_intent_id", "stripe_setup_intent_id TEXT")
    add_column_if_missing("parent_billing_profiles", "stripe_payment_method_id", "stripe_payment_method_id TEXT")
    cursor.execute("""
    CREATE TABLE IF NOT EXISTS stripe_webhook_events (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        stripe_event_id TEXT,
        event_type TEXT,
        related_invoice_id INTEGER,
        related_parent_id INTEGER,
        status TEXT,
        message TEXT,
        created_at TEXT
    )
    """)

    conn.commit()
    conn.close()


def record_stripe_webhook_event(event_id, event_type, status, message="", invoice_id=None, parent_id=None):
    ensure_billing_schema()
    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    cursor.execute("""
    INSERT INTO stripe_webhook_events (
        stripe_event_id,
        event_type,
        related_invoice_id,
        related_parent_id,
        status,
        message,
        created_at
    )
    VALUES (?, ?, ?, ?, ?, ?, ?)
    """, (
        event_id,
        event_type,
        invoice_id,
        parent_id,
        status,
        message,
        datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    ))
    conn.commit()
    conn.close()


def get_stripe_secret_key():
    return os.environ.get("STRIPE_SECRET_KEY")


def stripe_is_configured():
    return stripe is not None and bool(get_stripe_secret_key())


def configure_stripe():
    if not stripe_is_configured():
        return False
    stripe.api_key = get_stripe_secret_key()
    return True


def get_or_create_stripe_customer(cursor, parent_id):
    cursor.execute("""
    SELECT parent_name, email, phone
    FROM parent_profiles
    WHERE id = ?
    """, (parent_id,))
    parent = cursor.fetchone()

    if not parent:
        return None

    cursor.execute("""
    SELECT stripe_customer_id
    FROM parent_billing_profiles
    WHERE parent_id = ?
    """, (parent_id,))
    row = cursor.fetchone()

    if not configure_stripe():
        return None

    if row and row[0]:
        try:
            existing_customer = stripe.Customer.retrieve(row[0])
            if not existing_customer.get("deleted"):
                return row[0]
        except Exception:
            # A saved live-mode customer cannot be reused with a test-mode key.
            # Create a fresh customer for the currently configured Stripe mode.
            pass

    customer = stripe.Customer.create(
        name=parent[0] or None,
        email=parent[1] or None,
        phone=parent[2] or None,
        metadata={"parent_id": str(parent_id), "app": "hmusic-crm"}
    )

    now = datetime.now().strftime("%Y-%m-%d %H:%M")
    cursor.execute("""
    INSERT INTO parent_billing_profiles (
        parent_id,
        stripe_customer_id,
        status,
        created_at,
        updated_at
    )
    VALUES (?, ?, 'customer_created', ?, ?)
    ON CONFLICT(parent_id) DO UPDATE SET
        stripe_customer_id = excluded.stripe_customer_id,
        status = 'customer_created',
        updated_at = excluded.updated_at
    """, (
        parent_id,
        customer.id,
        now,
        now
    ))

    return customer.id


def get_saved_stripe_payment_method(cursor, parent_id):
    cursor.execute("""
    SELECT
        stripe_payment_method_id,
        autopay_enabled,
        stripe_customer_id,
        status
    FROM parent_billing_profiles
    WHERE parent_id = ?
    """, (parent_id,))
    row = cursor.fetchone()

    if not row:
        return None, 0, None, None

    return row[0], row[1] or 0, row[2], row[3]


def finalize_stripe_invoice_payment(invoice_id, checkout_session_id=None, payment_intent_id=None, source="stripe_checkout"):
    ensure_v321_schema()

    now = datetime.now().strftime("%Y-%m-%d %H:%M")
    payment_date = date.today().strftime("%Y-%m-%d")

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    cursor.execute("""
    SELECT
        id,
        student_name,
        charge_lessons,
        amount,
        status,
        invoice_type,
        created_at,
        enrollment_id,
        stripe_checkout_session_id,
        stripe_payment_intent_id
    FROM invoices
    WHERE id = ?
    """, (invoice_id,))
    invoice = cursor.fetchone()

    if not invoice:
        conn.close()
        return False

    if invoice[4] == "paid":
        conn.close()
        return True

    student_name = invoice[1]
    amount = invoice[3] or 0
    lessons_added = invoice[2] if invoice[5] == "package_invoice" else 0
    enrollment_id = invoice[7]
    checkout_session_id = checkout_session_id or invoice[8]
    payment_intent_id = payment_intent_id or invoice[9]
    course_type_name = ""
    teacher_name = ""
    if enrollment_id:
        cursor.execute("""
        SELECT COALESCE(course_type_name, ''), COALESCE(teacher_name, '')
        FROM enrollments
        WHERE id = ?
        """, (enrollment_id,))
        enrollment_row = cursor.fetchone()
        if enrollment_row:
            course_type_name, teacher_name = enrollment_row

    cursor.execute("""
    INSERT INTO payments
    (
        student_name,
        amount,
        lessons_added,
        payment_method,
        payment_date,
        enrollment_id,
        course_type_name,
        teacher_name,
        package_name,
        notes,
        visible_to_parent
    )
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    """, (
        student_name,
        amount,
        lessons_added,
        "Stripe ACH",
        payment_date,
        enrollment_id,
        course_type_name,
        teacher_name,
        "Tuition Invoice",
        f"Invoice #{invoice_id} paid via Stripe ACH ({source})",
        1
    ))

    payment_id = cursor.lastrowid

    if lessons_added and enrollment_id:
        cursor.execute("""
        UPDATE enrollments
        SET lessons_left = COALESCE(lessons_left, 0) + ?
        WHERE id = ?
        """, (lessons_added, enrollment_id))

    cursor.execute("""
    UPDATE invoices
    SET status = 'paid',
        stripe_checkout_session_id = COALESCE(?, stripe_checkout_session_id),
        stripe_payment_intent_id = COALESCE(?, stripe_payment_intent_id),
        autopay_status = 'paid'
    WHERE id = ?
    """, (
        checkout_session_id,
        payment_intent_id,
        invoice_id
    ))

    cursor.execute("""
    INSERT INTO student_ledger (
        student_name,
        entry_type,
        amount,
        description,
        related_invoice_id,
        related_payment_id,
        related_schedule_id,
        created_at
    )
    VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    """, (
        student_name,
        "invoice_payment",
        amount,
        f"Invoice #{invoice_id} paid via Stripe ACH",
        invoice_id,
        payment_id,
        None,
        now
    ))

    parent_id = get_primary_parent_for_student(cursor, student_name)
    conn.commit()
    conn.close()

    create_invoice_message_event(
        invoice_id,
        "stripe_paid",
        parent_id=parent_id,
        student_name=student_name,
        amount=amount
    )

    return True


def mark_stripe_invoice_payment_failed(invoice_id=None, payment_intent_id=None, checkout_session_id=None, reason="Stripe payment failed"):
    ensure_v321_schema()

    if not invoice_id and payment_intent_id:
        conn = sqlite3.connect("hmusic.db")
        cursor = conn.cursor()
        cursor.execute("""
        SELECT id
        FROM invoices
        WHERE stripe_payment_intent_id = ?
        ORDER BY id DESC
        LIMIT 1
        """, (payment_intent_id,))
        row = cursor.fetchone()
        conn.close()
        invoice_id = row[0] if row else None

    if not invoice_id:
        return False

    now = datetime.now().strftime("%Y-%m-%d %H:%M")
    reason_text = str(reason or "Stripe payment failed")[:180]

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    cursor.execute("""
    UPDATE invoices
    SET status = CASE WHEN status = 'paid' THEN status ELSE 'payment_failed' END,
        stripe_checkout_session_id = COALESCE(?, stripe_checkout_session_id),
        stripe_payment_intent_id = COALESCE(?, stripe_payment_intent_id),
        autopay_status = ?
    WHERE id = ?
    """, (
        checkout_session_id,
        payment_intent_id,
        f"failed: {reason_text}",
        invoice_id
    ))
    cursor.execute("""
    INSERT INTO notification_delivery_queue (
        user_role,
        user_key,
        channel,
        destination,
        title,
        body,
        link_url,
        related_type,
        related_id,
        status,
        created_at
    )
    VALUES ('owner', 'owner', 'push', 'owner:owner', ?, ?, ?, 'invoice', ?, 'pending', ?)
    """, (
        "Stripe payment failed",
        f"Invoice #{invoice_id} Stripe/ACH payment failed or was returned. Reason: {reason_text}",
        f"/pay_invoice/{invoice_id}",
        invoice_id,
        now
    ))
    conn.commit()
    conn.close()
    return True


def public_url_for(path):
    base_url = (os.environ.get("HMUSIC_PUBLIC_URL") or request.url_root.rstrip("/")).rstrip("/")
    return f"{base_url}{path}"


def get_square_access_token():
    return os.environ.get("SQUARE_ACCESS_TOKEN")


def get_square_location_id():
    return os.environ.get("SQUARE_LOCATION_ID")


def get_square_base_url():
    environment = (os.environ.get("SQUARE_ENVIRONMENT") or "production").strip().lower()
    if environment == "sandbox":
        return "https://connect.squareupsandbox.com"
    return "https://connect.squareup.com"


def square_is_configured():
    return bool(get_square_access_token() and get_square_location_id())


def square_api_request(path, payload=None, method="POST"):
    access_token = get_square_access_token()
    if not access_token:
        raise RuntimeError("SQUARE_ACCESS_TOKEN is not configured.")

    data = None
    headers = {
        "Authorization": f"Bearer {access_token}",
        "Square-Version": os.environ.get("SQUARE_VERSION", "2026-05-20"),
        "Accept": "application/json",
    }
    if payload is not None:
        data = json.dumps(payload).encode("utf-8")
        headers["Content-Type"] = "application/json"

    req = urlrequest.Request(
        get_square_base_url() + path,
        data=data,
        headers=headers,
        method=method,
    )
    try:
        with urlrequest.urlopen(req, timeout=20) as response:
            body = response.read().decode("utf-8")
            return json.loads(body) if body else {}
    except HTTPError as exc:
        body = exc.read().decode("utf-8", errors="replace")
        raise RuntimeError(f"Square API error {exc.code}: {body}") from exc
    except URLError as exc:
        raise RuntimeError(f"Square API connection failed: {exc.reason}") from exc


