def schedule_has_conflict(teacher, classroom, lesson_date, lesson_time, exclude_schedule_id=None, duration=30):
    target_start = minutes_from_time_text(lesson_time)
    if target_start is None:
        return {"has_conflict": False, "message": ""}

    duration = safe_minutes(duration, 30)

    target_end = target_start + duration

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()

    cursor.execute("""
    SELECT id, student_name, teacher, classroom, lesson_time, duration, status
    FROM schedule
    WHERE lesson_date = ?
    AND id != ?
    AND (
        teacher = ?
        OR classroom = ?
    )
    """, (
        lesson_date,
        exclude_schedule_id or -1,
        teacher,
        classroom
    ))

    rows = cursor.fetchall()
    conn.close()

    for row in rows:
        status = row[6] or "scheduled"
        if str(status).startswith("cancel") or status in ("excused_24h", "teacher_cancelled"):
            continue

        row_start = minutes_from_time_text(row[4])
        if row_start is None:
            continue

        row_duration = safe_minutes(row[5], 30)

        row_end = row_start + row_duration

        if max(target_start, row_start) < min(target_end, row_end):
            conflict_type = "teacher" if row[2] == teacher else "classroom"
            return {
                "has_conflict": True,
                "message": f"{conflict_type.title()} conflict with {row[1]} at {row[4]} in {row[3]}."
            }

    return {"has_conflict": False, "message": ""}



@app.route("/teacher_time_off_request", methods=["POST"])
def teacher_time_off_request():
    if not require_teacher():
        return redirect("/teacher_login")
    ensure_teacher_time_off_schema()
    teacher_name = session.get("teacher_name") or "Teacher"
    start_date = (request.form.get("start_date") or "").strip()
    end_date = (request.form.get("end_date") or start_date).strip()
    start_time = (request.form.get("start_time") or "").strip()
    end_time = (request.form.get("end_time") or "").strip()
    all_day = 1 if request.form.get("all_day") else 0
    reason = (request.form.get("reason") or "").strip()
    if not start_date:
        return redirect("/teacher_dashboard?view=time_off")
    if not end_date:
        end_date = start_date
    now = datetime.now().strftime("%Y-%m-%d %H:%M")
    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    cursor.execute("""
    INSERT INTO teacher_time_off_requests (
        teacher_name, start_date, end_date, start_time, end_time, all_day, reason, status, created_at, updated_at
    ) VALUES (?, ?, ?, ?, ?, ?, ?, 'pending', ?, ?)
    """, (teacher_name, start_date, end_date, start_time, end_time, all_day, reason, now, now))
    request_id = cursor.lastrowid
    conn.commit()
    conn.close()
    time_label = "full day" if all_day else f"{start_time or '?'}-{end_time or '?'}"
    body = f"{teacher_name} requested time off from {start_date} to {end_date} ({time_label})."
    if reason:
        body += f" Reason: {reason}"
    create_notification("owner", "owner", "Teacher time off request", body, "/teacher_dashboard", related_type="teacher_time_off", related_id=request_id)
    return redirect("/teacher_dashboard?view=time_off&sent=1")


