def ensure_v145_schema():
    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()

    cursor.execute("""
    CREATE TABLE IF NOT EXISTS renewal_email_logs (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        student_name TEXT,
        parent_email TEXT,
        lessons_left REAL,
        sent_at TEXT,
        status TEXT
    )
    """)

    cursor.execute("""
    CREATE TABLE IF NOT EXISTS sub_requests (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        schedule_id INTEGER,
        teacher_name TEXT,
        student_name TEXT,
        lesson_date TEXT,
        lesson_time TEXT,
        classroom TEXT,
        reason TEXT,
        status TEXT DEFAULT 'pending',
        substitute_teacher TEXT,
        created_at TEXT,
        assigned_at TEXT
    )
    """)

    conn.commit()
    conn.close()


