@app.route("/registration", methods=["GET", "POST"])
@app.route("/new_student_registration", methods=["GET", "POST"])
def public_student_registration():
    ensure_v17_schema()

    if request.method == "POST":
        data = {
            "student_name": request.form.get("student_name", "").strip(),
            "parent_name": request.form.get("parent_name", "").strip(),
            "parent_email": request.form.get("parent_email", "").strip(),
            "phone": request.form.get("phone", "").strip(),
            "age": request.form.get("age", "").strip(),
            "instrument": request.form.get("instrument", "").strip(),
            "program_interest": request.form.get("program_interest", "").strip() or "Enrollment Registration",
            "preferred_days": request.form.get("preferred_days", "").strip(),
            "preferred_times": request.form.get("preferred_times", "").strip(),
            "source": "Public Registration Form",
            "lead_temperature": "Hot",
            "trial_location": "",
            "notes": "",
        }
        if not data["student_name"] or not data["parent_name"] or not data["parent_email"] or not data["phone"]:
            return v35_registration_form("Please enter student name, primary guardian name, email, and phone.", request.form)
        if not request.form.get("billing_name", "").strip() or not request.form.get("billing_email", "").strip() or not request.form.get("billing_phone", "").strip():
            return v35_registration_form("Please enter billing contact name, email, and phone.", request.form)
        if not request.form.get("payment_setup", "").strip():
            return v35_registration_form("Please choose a preferred payment setup.", request.form)
        if request.form.get("policy_ack") != "1" or request.form.get("billing_ack") != "1":
            return v35_registration_form("Please review and agree to the policy and billing authorization.", request.form)
        if not request.form.get("guardian_signature", "").strip() or not request.form.get("signed_date", "").strip():
            return v35_registration_form("Please sign and date the registration.", request.form)
        extras = [
            ("Relationship", request.form.get("relationship", "")),
            ("Second guardian", request.form.get("guardian_2_name", "")),
            ("Second guardian contact", request.form.get("guardian_2_contact", "")),
            ("Family address", request.form.get("family_address", "")),
            ("Emergency contact", request.form.get("emergency_name", "")),
            ("Emergency phone", request.form.get("emergency_phone", "")),
            ("Preferred start date", request.form.get("preferred_start_date", "")),
            ("Schedule notes", request.form.get("schedule_notes", "")),
            ("Billing contact", request.form.get("billing_name", "")),
            ("Billing email", request.form.get("billing_email", "")),
            ("Billing phone", request.form.get("billing_phone", "")),
            ("Billing address", request.form.get("billing_address", "")),
            ("Preferred payment setup", request.form.get("payment_setup", "")),
            ("Student notes", request.form.get("student_notes", "")),
            ("Policy agreement", "Agreed"),
            ("Billing authorization", "Agreed"),
            ("Guardian signature", request.form.get("guardian_signature", "")),
            ("Signed date", request.form.get("signed_date", "")),
            ("Media permission", "Yes" if request.form.get("media_ok") == "1" else "No"),
        ]
        data["notes"] = "Formal registration submitted. " + " | ".join(
            f"{label}: {value.strip()}" for label, value in extras if value and value.strip()
        )
        inquiry_id = v35_insert_trial_lead(data, public=True)
        conn = sqlite3.connect(DB_NAME)
        cursor = conn.cursor()
        cursor.execute("""
        UPDATE inquiries
        SET status = ?, follow_up_status = ?, trial_status = ?, updated_at = ?
        WHERE id = ?
        """, ("Registration Submitted", "Ready to Enroll", "Registration", v35_now(), inquiry_id))
        conn.commit()
        conn.close()
        return v35_registration_thank_you(inquiry_id, data)

    return v35_registration_form()


def v35_trial_duration_minutes(duration_text):
    match = re.search(r"\d+", duration_text or "")
    return int(match.group(0)) if match else 30


def v35_trial_open_slot_options(selected_value=""):
    today = date.today().strftime("%Y-%m-%d")
    manual_slots = [
        slot for slot in get_manual_open_slots(start_date=today, days_ahead=60)
        if int(slot.get("active") or 0) == 1
    ]
    auto_slots = get_auto_open_slots(start_date=today, days_ahead=30)
    combined = manual_slots + auto_slots
    combined = sorted(combined, key=lambda item: (
        item.get("slot_date") or "",
        item.get("slot_time") or "",
        item.get("teacher") or "",
    ))[:120]

    options = ['<option value="">Choose an open slot...</option>']
    for slot in combined:
        payload = {
            "source": slot.get("source") or "manual",
            "id": slot.get("id") or "",
            "teacher": slot.get("teacher") or "",
            "slot_date": slot.get("slot_date") or "",
            "slot_time": slot.get("slot_time") or "",
            "classroom": slot.get("classroom") or "Trial Room",
        }
        value = json.dumps(payload, separators=(",", ":"))
        selected = "selected" if value == selected_value else ""
        label = (
            f"{payload['slot_date']} {payload['slot_time']} · "
            f"{payload['teacher']} · {payload['classroom']} · {payload['source']}"
        )
        options.append(f'<option value="{escape(value)}" {selected}>{escape(label)}</option>')
    return "".join(options)


def v35_apply_open_slot_to_trial_data(data, open_slot_value):
    if not open_slot_value:
        return None
    try:
        slot = json.loads(open_slot_value)
    except (TypeError, ValueError):
        return None

    data["trial_date"] = (slot.get("slot_date") or data.get("trial_date") or "").strip()
    data["trial_time"] = (slot.get("slot_time") or data.get("trial_time") or "").strip()
    data["trial_teacher"] = (slot.get("teacher") or data.get("trial_teacher") or "").strip()
    data["trial_location"] = (slot.get("classroom") or data.get("trial_location") or "Trial Room").strip()
    return slot


def v35_mark_trial_open_slot_used(slot, inquiry_id):
    if not slot or slot.get("source") != "manual" or not slot.get("id"):
        return False
    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()
    now = datetime.now().strftime("%Y-%m-%d %H:%M")
    cursor.execute("""
    UPDATE teacher_open_slots
    SET active = 0,
        notes = COALESCE(notes, '') || ?,
        updated_at = ?
    WHERE id = ?
    """, (f" | used by trial lead #{inquiry_id}", now, slot.get("id")))
    conn.commit()
    conn.close()
    return True


def v35_trial_confirmation_body(inquiry):
    student = inquiry["student_name"] or "your student"
    teacher = inquiry["trial_teacher"] or "your H-Music teacher"
    trial_date = inquiry["trial_date"] or "TBD"
    trial_time = inquiry["trial_time"] or "TBD"
    location = inquiry["trial_location"] or "H-Music"
    duration = inquiry["trial_duration"] or "Trial lesson"
    fee = inquiry["trial_fee"] or "trial fee"
    payment_method = inquiry["payment_method"] or "your selected payment method"
    if payment_method.lower() in ("paypal", "zelle"):
        payment_line = (
            f"Please send the trial payment by {payment_method} to hmusicjustplay@gmail.com. "
            "Please include the student name in the payment note."
        )
    else:
        payment_line = (
            "Trial lessons can be paid by ACH bank payment. H-Music covers the ACH processing fee. "
            "We will send secure payment instructions after confirming the trial slot."
        )
    return (
        f"Hi {inquiry['parent_name'] or 'there'},\n\n"
        f"{student}'s trial lesson is confirmed.\n\n"
        f"Date: {trial_date}\n"
        f"Time: {trial_time}\n"
        f"Teacher: {teacher}\n"
        f"Location: {location}\n"
        f"Trial: {duration} / {fee}\n"
        f"Payment method: {payment_method}\n\n"
        f"{payment_line}\n\n"
        f"After the trial, H-Music will help you set up the parent app if you continue lessons.\n\n"
        f"H-Music"
    )


def v35_queue_trial_confirmation(inquiry_id):
    ensure_v17_schema()
    conn = sqlite3.connect(DB_NAME)
    conn.row_factory = sqlite3.Row
    cursor = conn.cursor()
    cursor.execute("SELECT * FROM inquiries WHERE id=?", (inquiry_id,))
    inquiry = cursor.fetchone()
    conn.close()
    if not inquiry:
        return {"queued": 0, "email": None, "sms": None, "errors": ["Inquiry not found."]}

    title = "H-Music Trial Lesson Confirmed"
    body = v35_trial_confirmation_body(inquiry)
    link = "/trial"
    result = {"queued": 0, "email": None, "sms": None, "errors": []}
    if inquiry["parent_email"]:
        email_queue_id = queue_direct_delivery("email", inquiry["parent_email"], title, body, link, "trial_confirmation", inquiry_id)
        if email_queue_id:
            result["queued"] += 1
            sent, response = send_queued_email_now(email_queue_id)
            result["email"] = {
                "queue_id": email_queue_id,
                "sent": sent,
                "response": response,
            }
    else:
        result["errors"].append("Parent email is missing.")

    # SMS delivery is paused until a text provider such as Twilio is connected.
    result["sms"] = {
        "queue_id": None,
        "status": "disabled",
        "response": "SMS channel paused. Email is the active parent notification channel.",
    }

    return result


@app.route("/trial", methods=["GET", "POST"])
def public_trial_request():
    ensure_v17_schema()

    from_parent_app = request.args.get("from_parent_app") == "1" or request.form.get("existing_family") == "1"
    parent_id = session.get("parent_id") if from_parent_app else None
    family_context = {"is_existing_family": False, "students": []}
    prefill_values = {}
    if parent_id:
        ensure_v27_schema()
        conn = sqlite3.connect(DB_NAME)
        cursor = conn.cursor()
        cursor.execute("SELECT parent_name, email, COALESCE(phone, '') FROM parent_profiles WHERE id = ?", (parent_id,))
        parent_row = cursor.fetchone()
        linked = get_parent_students(parent_id)
        conn.close()
        family_context = {
            "is_existing_family": True,
            "students": [s[0] for s in linked],
        }
        if parent_row:
            prefill_values.update({
                "parent_name": parent_row[0] or "",
                "parent_email": parent_row[1] or "",
                "phone": parent_row[2] or "",
                "source": "Existing H-Music Family",
                "request_type": request.args.get("request_type") or "Another child",
                "existing_family": "1",
            })
            if family_context["students"]:
                prefill_values["existing_student_name"] = family_context["students"][0]

    if request.method == "POST":
        preferred_dates = []
        preferred_times = []
        for idx in range(1, 4):
            date_value = request.form.get(f"preferred_date_{idx}", "").strip()
            time_value = request.form.get(f"preferred_time_{idx}", "").strip()
            if date_value or time_value:
                preferred_dates.append(f"{idx}. {date_value or 'Day TBD'}")
                preferred_times.append(f"{idx}. {time_value or 'Time TBD'}")
        data = {
            "student_name": request.form.get("student_name", "").strip(),
            "parent_name": request.form.get("parent_name", "").strip(),
            "parent_email": request.form.get("parent_email", "").strip(),
            "phone": request.form.get("phone", "").strip(),
            "age": request.form.get("age", "").strip(),
            "instrument": request.form.get("instrument", "").strip(),
            "program_interest": request.form.get("program_interest", "").strip(),
            "preferred_days": "; ".join(preferred_dates),
            "preferred_times": "; ".join(preferred_times),
            "trial_location": request.form.get("trial_location", "").strip(),
            "previous_experience": request.form.get("previous_experience", "").strip(),
            "experience_duration": request.form.get("experience_duration", "").strip(),
            "trial_duration": request.form.get("trial_duration", "").strip(),
            "trial_fee": request.form.get("trial_fee", "").strip(),
            "payment_method": request.form.get("payment_method", "").strip(),
            "notes": request.form.get("notes", "").strip(),
            "source": request.form.get("source", "").strip() or ("Existing H-Music Family" if parent_id else "Public Trial Form"),
            "lead_temperature": "Warm",
            "parent_profile_id": str(parent_id or ""),
            "existing_family": "1" if parent_id else request.form.get("existing_family", "").strip(),
            "request_type": request.form.get("request_type", "").strip(),
            "existing_student_name": request.form.get("existing_student_name", "").strip(),
        }
        fee_by_duration = {
            "15 mins": "$15",
            "30 mins": "$30",
            "45 mins": "$45",
            "60 mins": "$60",
        }
        if data["trial_duration"] in fee_by_duration:
            data["trial_fee"] = fee_by_duration[data["trial_duration"]]
        form_values = {**prefill_values, **request.form, **data}
        if not data["student_name"] or not data["parent_name"]:
            return v35_public_trial_form("Please enter student and parent names.", form_values, family_context)
        if not data["parent_email"] and not data["phone"]:
            return v35_public_trial_form("Please enter either email or phone.", form_values, family_context)
        if data["trial_duration"] not in fee_by_duration:
            return v35_public_trial_form("Please select a trial class length.", form_values, family_context)
        if not data["payment_method"]:
            return v35_public_trial_form("Please select a payment method.", form_values, family_context)
        try:
            age_number = float(data["age"]) if data["age"] else None
        except ValueError:
            age_number = None
        if data["trial_duration"] == "15 mins" and age_number is not None and age_number > 5:
            return v35_public_trial_form("15 mins / $15 is only for children age 5 and under. Please choose 30, 45, or 60 mins.", form_values, family_context)
        if not data["preferred_days"] or not data["preferred_times"]:
            return v35_public_trial_form("Please enter at least one preferred day and time.", form_values, family_context)
        inquiry_id = v35_insert_trial_lead(data, public=True)
        return v35_public_trial_thank_you(inquiry_id, data)
    return v35_public_trial_form(values=prefill_values, family_context=family_context)


