@app.route("/add_enrollment_schedule/<int:enrollment_id>", methods=["GET", "POST"])
def add_enrollment_schedule(enrollment_id):
    if not require_owner():
        return redirect("/owner_login")

    ensure_v19_schema()

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()

    cursor.execute("""
    SELECT
        id,
        student_name,
        course_type_id,
        course_type_name,
        teacher_name,
        duration,
        student_billing_method,
        final_price,
        teacher_billing_method,
        teacher_rate,
        teacher_pay_amount
    FROM enrollments
    WHERE id = ?
    """, (enrollment_id,))

    e = cursor.fetchone()

    if not e:
        conn.close()
        return "<h1>Enrollment not found</h1>"

    cursor.execute("""
    SELECT room_name
    FROM classrooms
    ORDER BY room_name
    """)

    rooms = cursor.fetchall()

    if request.method == "POST":
        classroom = request.form.get("classroom")
        weekday = request.form.get("weekday")
        lesson_time = request.form.get("lesson_time")
        schedule_type = request.form.get("schedule_type")
        package_type = request.form.get("package_type")
        start_date = request.form.get("start_date")

        if schedule_type == "one_time":
            number_of_lessons = 1
        elif package_type == "10":
            number_of_lessons = 10
        elif package_type == "12":
            number_of_lessons = 12
        else:
            number_of_lessons = 24

        start_date_obj = datetime.strptime(start_date, "%Y-%m-%d")

        generated_count = 0

        for i in range(number_of_lessons):
            if schedule_type == "weekly":
                lesson_date_obj = start_date_obj + timedelta(days=7 * i)
            else:
                lesson_date_obj = start_date_obj

            lesson_date = lesson_date_obj.strftime("%Y-%m-%d")

            cursor.execute("""
            INSERT INTO schedule (
                enrollment_id,
                student_name,
                teacher,
                classroom,
                weekday,
                lesson_time,
                schedule_type,
                package_type,
                start_date,
                lesson_date,

                course_type_id,
                course_type_name,
                duration,
                student_billing_method,
                student_price,
                teacher_billing_method,
                teacher_pay,
                student_charge_amount,
                teacher_pay_amount,
                final_price,
                status
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """, (
                e[0],
                e[1],
                e[4],
                classroom,
                weekday,
                lesson_time,
                schedule_type,
                package_type,
                start_date,
                lesson_date,

                e[2],
                e[3],
                e[5],
                e[6],
                e[7],
                e[8],
                e[9],
                e[7],
                e[10],
                e[7],
                "scheduled"
            ))

            generated_count += 1

        conn.commit()
        conn.close()

        return f"""
        <h1>Enrollment Schedule Generated!</h1>

        <p>{generated_count} lesson(s) created.</p>
        <p>Student: {e[1]}</p>
        <p>Course: {e[3]}</p>
        <p>Teacher: {e[4]}</p>
        <p>Duration: {e[5]} mins</p>
        <p>Student Price: ${e[7]}</p>
        <p>Teacher Pay: ${e[10]}</p>

        <p><a href="/enrollment/{enrollment_id}">Back to Enrollment</a></p>
        <p><a href="/calendar">Calendar</a></p>
        """

    room_options = ""
    for r in rooms:
        room_options += f"<option value='{r[0]}'>{r[0]}</option>"

    conn.close()

    return f"""
    <h1>Schedule Enrollment</h1>

    <h2>{e[1]} - {e[3]}</h2>

    <p>Teacher: {e[4]}</p>
    <p>Duration: {e[5]} mins</p>
    <p>Student Price: ${e[7]}</p>
    <p>Teacher Pay: ${e[10]}</p>

    <form method="POST">

        Room:<br>
        <select name="classroom">
            {room_options}
        </select><br><br>

        Day of Week:<br>
        <select name="weekday">
            <option value="Monday">Monday</option>
            <option value="Tuesday">Tuesday</option>
            <option value="Wednesday">Wednesday</option>
            <option value="Thursday">Thursday</option>
            <option value="Friday">Friday</option>
            <option value="Saturday">Saturday</option>
            <option value="Sunday">Sunday</option>
        </select><br><br>

        Time:<br>
        <input type="time" name="lesson_time" required><br><br>

        Schedule Type:<br>
        <select name="schedule_type">
            <option value="one_time">One Time</option>
            <option value="weekly">Weekly</option>
        </select><br><br>

        Package:<br>
        <select name="package_type">
            <option value="10">10 Lessons</option>
            <option value="12">12 Lessons</option>
            <option value="unlimited">Unlimited</option>
        </select><br><br>

        Start Date:<br>
        <input type="date" name="start_date" required><br><br>

        <button type="submit">Generate Schedule</button>

    </form>

    <p><a href="/enrollment/{enrollment_id}">Back to Enrollment</a></p>
    """
