# V25.2 Owner Business Rules Settings
# =========================

def ensure_v252_schema():
    ensure_v25_schema()

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()

    cursor.execute("""
    CREATE TABLE IF NOT EXISTS business_rules (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        rule_name TEXT UNIQUE,
        rule_label TEXT,
        student_charge_percent REAL DEFAULT 100,
        teacher_pay_percent REAL DEFAULT 100,
        deduct_lesson INTEGER DEFAULT 1,
        active INTEGER DEFAULT 1,
        created_at TEXT,
        updated_at TEXT
    )
    """)

    now = datetime.now().strftime("%Y-%m-%d %H:%M")

    default_rules = [
        ("present", "Present", 100, 100, 1),
        ("no_show", "No Show", 100, 100, 1),
        ("last_min_cancel", "Last Min Cancel", 0, 0, 0),
        ("cancel_3h", "Cancel < 3h", 100, 100, 1),
        ("cancel_12h", "Cancel < 12h", 100, 75, 1),
        ("cancel_24h", "Cancel < 24h", 50, 50, 0),
        ("excused_24h", "Cancel > 24h", 0, 0, 0),
        ("teacher_cancelled", "Teacher Cancel", 0, 0, 0),
        ("makeup", "Makeup", 0, 100, 0),
    ]

    for r in default_rules:
        cursor.execute("""
        INSERT OR IGNORE INTO business_rules (
            rule_name,
            rule_label,
            student_charge_percent,
            teacher_pay_percent,
            deduct_lesson,
            active,
            created_at,
            updated_at
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
        """, (
            r[0],
            r[1],
            r[2],
            r[3],
            r[4],
            1,
            now,
            now
        ))

    conn.commit()
    conn.close()


def get_business_rule(status):
    ensure_v252_schema()

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()

    cursor.execute("""
    SELECT
        rule_name,
        rule_label,
        student_charge_percent,
        teacher_pay_percent,
        deduct_lesson
    FROM business_rules
    WHERE rule_name = ?
    AND active = 1
    """, (status,))

    r = cursor.fetchone()
    conn.close()

    if not r:
        return {
            "rule_name": status,
            "rule_label": status,
            "student_charge_percent": 0,
            "teacher_pay_percent": 0,
            "deduct_lesson": 0
        }

    return {
        "rule_name": r[0],
        "rule_label": r[1],
        "student_charge_percent": r[2],
        "teacher_pay_percent": r[3],
        "deduct_lesson": r[4]
    }


