def ensure_v26_schema():
    ensure_v252_schema()

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()

    cursor.execute("""
    CREATE TABLE IF NOT EXISTS payroll_periods (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        month TEXT UNIQUE,
        locked INTEGER DEFAULT 0,
        locked_at TEXT,
        locked_by TEXT
    )
    """)

    conn.commit()
    conn.close()


def is_payroll_locked(month):
    ensure_v26_schema()

    conn = sqlite3.connect("hmusic.db")
    cursor = conn.cursor()

    cursor.execute("""
    SELECT locked
    FROM payroll_periods
    WHERE month = ?
    """, (month,))

    row = cursor.fetchone()
    conn.close()

    if not row:
        return False

    return row[0] == 1


